window.COURSE=[{"id":1,"title":"Что такое Linux","en":"Introduction to Linux","intro":"Раздел объясняет, что именно называют Linux, как ядро связано с GNU и дистрибутивом и почему командная строка остаётся основным инструментом администратора.","sections":[{"title":"Linux вокруг нас","body":"Linux используют серверы, облака, транспорт, научные системы, смартфоны и встроенные устройства. Навыки Linux применимы в администрировании, разработке, сетях, безопасности и обработке данных. Многие команды наследуют подходы UNIX и сохраняют полезность между дистрибутивами."},{"title":"Ядро и полная система","body":"В строгом смысле Linux — ядро: центральная часть ОС, загружаемая при запуске и управляющая ресурсами. GNU предоставляет инструменты, компиляторы, редакторы и интерфейсы. GNU/Linux — сочетание ядра и этих инструментов; пользовательские приложения дополняют систему."},{"title":"История и UNIX","body":"UNIX появился в Bell Labs, а язык C помог сделать его переносимым. Проект GNU начал Richard Stallman в 1983 году; Linux начал Linus Torvalds в 1991 году. Linux — UNIX-подобная система: сходство устройства и интерфейсов не равнозначно сертификации UNIX. GNU расшифровывается как GNU’s Not Unix."},{"title":"Открытый исходный код","body":"Open source даёт доступ к исходному коду и позволяет его изучать и изменять согласно лицензии. Сообщество может обмениваться улучшениями и исправлениями. Закрытая лицензия обычно предоставляет право использовать исполняемую программу без доступа к её исходникам. Linux исторически написан преимущественно на C."},{"title":"Дистрибутивы","body":"Дистрибутив объединяет ядро, системные инструменты, установщик, приложения и менеджер пакетов. Набор и настройки зависят от назначения: сервер, рабочий стол, обучение или специализированные задачи. Крупные исторические семейства курса — Debian, Red Hat и Slackware."},{"title":"GUI и CLI","body":"GUI использует окна, меню и указатель; CLI принимает текстовые команды через оболочку. Linux может предоставлять оба интерфейса. CLI удобен для точного управления, повторяемых действий и автоматизации; знание общих команд переносится между дистрибутивами."}],"commands":[],"lab":[],"pitfalls":["Linux как ядро и Linux как полный дистрибутив — разные уровни системы.","Наличие GUI не исключает использование CLI.","Open source не означает, что программа обязательно бесплатна или лишена ошибок."],"questions":[{"type":"single","prompt":"Что обозначает Linux в самом строгом техническом смысле?","options":["Ядро операционной системы","Любую программу с открытым кодом","Только графический рабочий стол","Стандарт текстового редактора"],"answer":[0],"explanation":"Ядро управляет ресурсами; полный пользовательский комплект называется дистрибутивом.","difficulty":"basic"},{"type":"single","prompt":"Какой компонент продолжает работать после загрузки и управляет ресурсами системы?","options":["Установочный образ","Ядро","Архив исходников","Документация"],"answer":[1],"explanation":"Ядро загружается при старте и обслуживает работающие процессы и оборудование.","difficulty":"basic"},{"type":"single","prompt":"В чём вклад GNU в GNU/Linux?","options":["Создание только логотипа","Предоставление исключительно драйверов принтера","Инструменты, редакторы, компиляторы и другие системные программы","Обязательная сертификация каждого компьютера"],"answer":[2],"explanation":"GNU-инструменты сделали ядро частью практически пригодной ОС.","difficulty":"basic"},{"type":"single","prompt":"Кто начал разработку ядра Linux?","options":["Richard Stallman","Linus Torvalds","Dennis Ritchie","Bill Gates"],"answer":[1],"explanation":"Linus Torvalds начал Linux как собственный проект ядра.","difficulty":"basic"},{"type":"text","prompt":"В каком году начался проект Linux? Введите год.","answer":["1991"],"explanation":"В лекции начало проекта Linux относится к 1991 году.","difficulty":"basic"},{"type":"single","prompt":"Какой проект Richard Stallman начал в 1983 году?","options":["Android","Fedora","GNU","Apache"],"answer":[2],"explanation":"GNU создавал свободные инструменты и планировал свободную UNIX-подобную ОС.","difficulty":"basic"},{"type":"single","prompt":"Why is Linux described as UNIX-like in this chapter?","options":["It has a similar design without the UNIX certification discussed in the chapter","It can only run on a UNIX server","It is a text editor included in UNIX","It contains no kernel"],"answer":[0],"explanation":"Сходство с UNIX не даёт автоматически права использовать сертификационное название UNIX.","difficulty":"basic"},{"type":"single","prompt":"Что означает recursive acronym GNU?","options":["General Network Utility","Global New UNIX","GNU’s Not Unix","Graphical Network User"],"answer":[2],"explanation":"Первое слово расшифровки снова содержит саму аббревиатуру GNU.","difficulty":"basic"},{"type":"single","prompt":"Какая особенность языка C помогла распространению UNIX?","options":["Привязка к единственной модели компьютера","Переносимость программ между аппаратными платформами","Запрет компиляции","Обязательный графический интерфейс"],"answer":[1],"explanation":"C позволил снизить зависимость ОС от конкретного оборудования.","difficulty":"basic"},{"type":"single","prompt":"Что нужно добавить к ядру, чтобы получить привычную пользователю систему?","options":["Только название компании","Системные инструменты и приложения","Только фон рабочего стола","Только новую лицензию"],"answer":[1],"explanation":"Ядро само по себе не предоставляет весь набор пользовательских программ.","difficulty":"basic"},{"type":"multi","prompt":"Выберите 2 составляющие типичного дистрибутива.","options":["Ядро Linux","Установщик и менеджер пакетов","Обязательная подписка на один облачный сервис","Обязательное отсутствие приложений"],"answer":[0,1],"explanation":"Дистрибутив поставляет ядро и средства установки и сопровождения программ.","difficulty":"basic"},{"type":"single","prompt":"Компания выбирает Linux для узкоспециализированного научного компьютера. Что следует из лекции?","options":["Все дистрибутивы предназначены только для браузера","Можно выбрать дистрибутив под нужную задачу","Придётся отказаться от ядра","Научные приложения несовместимы с Linux по определению"],"answer":[1],"explanation":"Дистрибутивы различаются назначением и составом программ.","difficulty":"applied"},{"type":"single","prompt":"Какой инструмент отвечает за удобное добавление и удаление программ после установки дистрибутива?","options":["Менеджер пакетов","Только загрузчик","Обои рабочего стола","Только текстовый курсор"],"answer":[0],"explanation":"Пакетный менеджер сопровождает установленное программное обеспечение.","difficulty":"basic"},{"type":"multi","prompt":"Выберите 2 свойства open source из лекции.","options":["Можно получить исходный код","Можно изменять код в рамках лицензии","Автор обязан предоставлять круглосуточную поддержку","Все ошибки автоматически исчезают"],"answer":[0,1],"explanation":"Доступ к исходникам позволяет изучение и изменения, но не гарантирует поддержку или отсутствие ошибок.","difficulty":"basic"},{"type":"single","prompt":"Пользователь получил исполняемый файл без исходного кода. Достаточно ли этого, чтобы назвать программу open source?","options":["Да, любой executable открыт","Да, если файл небольшой","Нет, важны доступ к исходникам и лицензионные права","Нет, open source может существовать только на бумаге"],"answer":[2],"explanation":"Исполняемый файл и исходный код — разные формы программы.","difficulty":"applied"},{"type":"single","prompt":"Какой пример относится к CLI?","options":["Ввод текстовой команды в терминал","Перетаскивание окна мышью","Выбор цвета в графическом меню","Нажатие значка приложения на рабочем столе"],"answer":[0],"explanation":"CLI предполагает текстовый ввод команд.","difficulty":"basic"},{"type":"single","prompt":"Какое преимущество CLI особенно полезно для повторения одной задачи на многих системах?","options":["Автоматизация командами и сценариями","Запрет удалённой работы","Обязательное ручное перетаскивание окон","Отсутствие каких-либо параметров"],"answer":[0],"explanation":"Последовательности команд можно сохранять и повторять в сценариях.","difficulty":"applied"},{"type":"single","prompt":"Администратор сменил дистрибутив. Почему изученные команды по-прежнему полезны?","options":["Все графические интерфейсы обязаны быть одинаковыми","Многие базовые команды и подходы общие","Каждый дистрибутив использует Windows API вместо Linux","CLI существует только в одном дистрибутиве"],"answer":[1],"explanation":"Общая UNIX-подобная основа уменьшает зависимость от конкретного рабочего стола.","difficulty":"applied"},{"type":"single","prompt":"Какая пара правильно сопоставляет интерфейс и способ взаимодействия?","options":["GUI — окна и меню; CLI — текстовые команды","GUI — только бинарные инструкции; CLI — только мышь","GUI — ядро; CLI — аппаратная память","GUI — лицензия; CLI — дистрибутив"],"answer":[0],"explanation":"Интерфейсы отличаются способом взаимодействия, а не являются ядром или лицензией.","difficulty":"basic"},{"type":"single","prompt":"Коллега утверждает: «Linux применяется исключительно на настольных ПК». Какой пример из лекции опровергает это?","options":["Серверы и встроенные устройства","Только смена обоев","Только настольная клавиатура","Только офисный документ"],"answer":[0],"explanation":"Сфера Linux включает серверы, облака и специализированные устройства.","difficulty":"applied"}],"sources":[{"kind":"chapter","title":"NDG Linux Essentials - Chapter 1 - Introduction to Linux (1).txt","url":"https://drive.google.com/file/d/1Kg9Zm93wv5swTaufw3D6HhIkH9f97ecZ/view?usp=drivesdk"}]},{"id":2,"title":"ОС и дистрибутивы","en":"Operating Systems","intro":"Выбор ОС начинается с роли компьютера, необходимых приложений, поддержки и требований к стабильности. Важно различать семейства дистрибутивов, цикл выпусков и срок сопровождения.","sections":[{"title":"Что делает ОС","body":"ОС управляет аппаратными и программными ресурсами, распределяет время процессора между задачами и предоставляет приложениям общие службы. Сервер обслуживает удалённых клиентов, рабочая станция ориентирована на непосредственную работу пользователя; одна машина может выполнять несколько ролей."},{"title":"Критерии выбора","body":"Учитывай роль, нужные приложения, совместимость оборудования и библиотек, навыки команды, стоимость покупки и сопровождения, срок службы и интерфейс. Бесплатная загрузка дистрибутива не обнуляет затраты на поддержку и обслуживание."},{"title":"Выпуски и сопровождение","body":"Release cycle описывает частоту новых выпусков; maintenance/life cycle — период получения исправлений и поддержки. Beta содержит новые, ещё недостаточно проверенные изменения. Stable предпочтительна для предсказуемой эксплуатации. LTS означает длительное сопровождение, а backward compatibility — возможность запускать ПО прежних версий."},{"title":"Windows, macOS и Linux","body":"Windows имеет собственную не-UNIX кодовую основу, версии для настольных и серверных задач и средства автоматизации. macOS использует компоненты BSD и UNIX-наследие, тесно связана с оборудованием Apple. Linux поставляется как множество дистрибутивов. Указанные в лекции номера текущих версий относятся ко времени её написания."},{"title":"Семейства дистрибутивов","body":"Red Hat связан с RPM; RHEL ориентирован на предприятия, Fedora — на более быстрые обновления. CentOS и Scientific Linux описаны в лекции в историческом контексте производных RHEL. SUSE исторически вырос из Slackware; существуют корпоративные и общественные варианты. Debian использует .deb; Ubuntu происходит от Debian, а основная линия Mint — от Ubuntu."},{"title":"Специальные варианты","body":"Android использует ядро Linux, но отличается пользовательской средой от обычного GNU/Linux: общее ядро не гарантирует совместимость приложений. Raspbian в лекции — система для Raspberry Pi. Linux From Scratch — учебный проект сборки своей системы из исходников."},{"title":"Встроенные системы и облака","body":"Embedded system выполняет определённую задачу на специализированном оборудовании: например, маршрутизатор или датчик. IoT объединяет такие устройства в сети. Виртуализация позволяет нескольким гостевым ОС разделять физический компьютер; облака предоставляют удалённые ресурсы и уменьшают необходимость покупать всю инфраструктуру заранее."},{"title":"Терминал и оболочка","body":"Терминал принимает ввод и показывает результат, оболочка интерпретирует команды. GUI удобен для интерактивной работы, а сервер может обходиться CLI, сохраняя ресурсы. MOTD — сообщение, показываемое после входа; это не приглашение к вводу команды."}],"commands":[{"cmd":"w","description":"Показать вошедших пользователей и сведения об их сеансах."}],"lab":[],"pitfalls":["Release cycle и срок поддержки — разные понятия.","Android не обязан запускать пакеты обычного настольного GNU/Linux.","Исторические версии Windows, CentOS, Android и сроки поддержки из лекции нельзя принимать за текущий каталог продуктов."],"questions":[{"type":"single","prompt":"Какая задача относится к обязанностям ОС?","options":["Распределять ресурсы между программами","Писать весь исходный код приложений","Выбирать за пользователя тему диплома","Обязательно показывать GUI на каждом сервере"],"answer":[0],"explanation":"ОС управляет памятью, процессором, устройствами и выполнением программ.","difficulty":"basic"},{"type":"single","prompt":"Компьютер в основном предоставляет файлы удалённым пользователям. Какую роль он выполняет?","options":["Сервер","Только графический редактор","Компилятор","Лицензия"],"answer":[0],"explanation":"Роль определяется обслуживанием клиентов, а не внешним видом корпуса.","difficulty":"applied"},{"type":"single","prompt":"Почему сервер часто устанавливают без графического окружения?","options":["Чтобы снизить затраты ресурсов на ненужный интерфейс","Потому что Linux не поддерживает GUI","Потому что CLI запрещает сеть","Чтобы удалить возможность администрирования"],"answer":[0],"explanation":"Для удалённого обслуживания GUI часто не нужен.","difficulty":"applied"},{"type":"single","prompt":"Что означает release cycle?","options":["Промежуток и схема выпуска новых версий","Время одного входа в систему","Количество файлов в архиве","Срок действия пользовательского пароля"],"answer":[0],"explanation":"Частота выпусков не тождественна сроку поддержки отдельного выпуска.","difficulty":"basic"},{"type":"single","prompt":"Организация уточняет, до какой даты будут выходить исправления для установленной версии. Что она изучает?","options":["Maintenance cycle","Размер рабочего стола","Частоту переключения задач","Имя домашнего каталога"],"answer":[0],"explanation":"Цикл сопровождения определяет период поддержки версии.","difficulty":"applied"},{"type":"single","prompt":"Что лучше описывает beta release?","options":["Версия с новыми возможностями, ещё проходящими проверку","Всегда окончательная версия без ошибок","Другая запись слова root","Версия только для принтеров"],"answer":[0],"explanation":"Beta может быть полезна для тестирования, но несёт большую неопределённость.","difficulty":"basic"},{"type":"single","prompt":"Для критичного сервера важнее предсказуемость, чем самые новые функции. Какой вариант соответствует этому требованию?","options":["Stable с подходящим сроком поддержки","Любая unstable без оценки рисков","Обязательное обновление до каждой beta","Отказ от исправлений безопасности"],"answer":[0],"explanation":"Проверенный выпуск и сопровождение уменьшают эксплуатационные риски.","difficulty":"applied"},{"type":"text","prompt":"Расшифруйте LTS по-английски.","answer":["long-term support","long term support","Long-term support","Long-term Support","Long-Term Support","Long Term Support","LONG-TERM SUPPORT","LONG TERM SUPPORT"],"explanation":"LTS обозначает долгосрочное сопровождение выпуска.","difficulty":"basic"},{"type":"single","prompt":"После обновления ОС старое приложение продолжает работать. Как называется это свойство?","options":["Backward compatibility","Compression","Globbing","Multimedia"],"answer":[0],"explanation":"Обратная совместимость сохраняет возможность использовать ПО предыдущих версий.","difficulty":"basic"},{"type":"multi","prompt":"Выберите 2 фактора, которые действительно важны при выборе дистрибутива для компании.","options":["Поддержка необходимого приложения","Навыки обслуживающей команды","Только цвет логотипа","Только длина названия"],"answer":[0,1],"explanation":"Поддерживаемые приложения и квалификация команды напрямую влияют на эксплуатацию.","difficulty":"applied"},{"type":"single","prompt":"Какая система в лекции имеет BSD-основу и UNIX-сертификацию?","options":["macOS","MS-DOS","Linux From Scratch как любой результат сборки","Любая Android-прошивка"],"answer":[0],"explanation":"В сравнении ОС лекция выделяет UNIX-наследие и сертификацию macOS.","difficulty":"basic"},{"type":"single","prompt":"Какой формат пакетов связан с Debian?","options":[".deb",".jpg",".wav",".rpm"],"answer":[0],"explanation":"Debian и производные используют пакеты .deb.","difficulty":"basic"},{"type":"single","prompt":"Какое семейство непосредственно связано с RPM в лекции?","options":["Red Hat","Только macOS","Только iOS","GNU как отдельное семейство пакетов"],"answer":[0],"explanation":"RPM возник в экосистеме Red Hat.","difficulty":"basic"},{"type":"single","prompt":"Which distribution is derived from Debian?","options":["Ubuntu","RHEL","SUSE as described in the chapter","Windows Server"],"answer":[0],"explanation":"Ubuntu использует Debian как историческую основу.","difficulty":"basic"},{"type":"single","prompt":"Какую роль в экосистеме Red Hat лекция связывает с Fedora?","options":["Более быстрые обновления и новые технологии","Исключительно драйвер клавиатуры","Только платный архив документов","Полное отсутствие пакетного менеджера"],"answer":[0],"explanation":"Fedora развивает новые возможности быстрее корпоративной линии.","difficulty":"basic"},{"type":"single","prompt":"Что означает слово embedded в контексте ОС?","options":["Система внутри устройства, предназначенного для определённых задач","Любая ОС с большим монитором","Файл, помещённый в корзину","Только виртуальная машина"],"answer":[0],"explanation":"Примеры — датчики, бытовые устройства, сетевое оборудование.","difficulty":"basic"},{"type":"single","prompt":"Студент хочет понять сборку Linux из исходников по шагам. Какой проект из лекции подходит по назначению?","options":["Linux From Scratch","Thunderbird","GIMP","Sendmail"],"answer":[0],"explanation":"LFS — учебное руководство по построению собственной системы.","difficulty":"applied"},{"type":"single","prompt":"Почему приложение из Google Play не становится автоматически обычным пакетом Ubuntu?","options":["Пользовательские среды и API различаются, несмотря на общее ядро Linux","У Android вообще нет ядра","Ubuntu не умеет запускать программы","Все программы обязаны быть написаны для одного экрана"],"answer":[0],"explanation":"Общее ядро не означает одинаковые библиотеки и формат приложений.","difficulty":"applied"},{"type":"single","prompt":"Что позволяет виртуализация?","options":["Запускать несколько гостевых ОС на одном физическом хосте","Сделать физическую память бесконечной","Отменить необходимость в процессоре","Гарантировать отсутствие любых затрат"],"answer":[0],"explanation":"Ресурсы одного хоста распределяются между виртуальными машинами.","difficulty":"basic"},{"type":"multi","prompt":"Выберите 2 верных различия терминала и оболочки.","options":["Терминал принимает ввод и отображает текст","Оболочка интерпретирует команду","Терминал всегда является ядром","Оболочка обязательно является монитором"],"answer":[0,1],"explanation":"Терминал обеспечивает взаимодействие, а shell разбирает и запускает команды.","difficulty":"basic"}],"sources":[{"kind":"chapter","title":"NDG Linux Essentials - Chapter 2 - Operating Systems.txt","url":"https://drive.google.com/file/d/1gfYom-TqH4e9lTDswQGqJQsOe9AJxY2Y/view?usp=drivesdk"}]},{"id":3,"title":"Программы и работа в Linux","en":"Working in Linux","intro":"Узнай основные серверные и настольные программы, пакетные системы, языки разработки и базовые принципы безопасности, облаков и виртуализации.","sections":[{"title":"Рабочий стол и консоль","body":"CLI можно открыть в графическом терминале или отдельной виртуальной консоли. Терминал и оболочка — разные компоненты. Приложения запрашивают ресурсы через интерфейсы ОС; ядро отслеживает процессы и переключает задачи. Одна программа может состоять из нескольких процессов."},{"title":"Веб, данные и частное облако","body":"Apache HTTPD и NGINX обслуживают HTTP/HTTPS. Статическая страница отправляется как готовый файл, динамическая формируется приложением; WordPress — пример. MariaDB — ответвление MySQL; PostgreSQL и Firebird также являются СУБД. SQL позволяет запрашивать данные. ownCloud и Nextcloud помогают хранить, синхронизировать и совместно использовать файлы на частной инфраструктуре."},{"title":"Почта","body":"MTA передаёт письма между системами: примеры Sendmail и Postfix. MDA размещает письмо в локальном ящике. POP/IMAP-серверы, например Dovecot и Cyrus, предоставляют клиентам доступ к почте. Thunderbird, Evolution и KMail — пользовательские клиенты, а не замена всем серверным компонентам."},{"title":"Файлы и сетевые службы","body":"Samba обеспечивает совместную работу с Windows-ресурсами, NFS — типичный сетевой доступ к файлам UNIX/Linux, Netatalk связан с Apple file sharing. DNS сопоставляет имена и адреса; BIND — сервер DNS. DHCP выдаёт сетевые настройки, включая IP-адрес. LDAP хранит иерархические каталожные сведения; OpenLDAP реализует этот протокол."},{"title":"Настольные приложения","body":"LibreOffice включает Writer для документов и Calc для таблиц, а также средства презентаций; пакет происходит от OpenOffice. GIMP редактирует растровые изображения, Blender работает с 3D, Audacity — со звуком. Firefox и Chrome доступны в Linux; открытый проект Chromium следует отличать от продукта Chrome."},{"title":"Оболочки и редакторы","body":"Bash относится к семейству Bourne shell; tcsh — к семейству C shell. Есть ksh и zsh. Vi/Vim и Emacs — мощные редакторы, Nano — более простой редактор для небольших правок. Bash позволяет повторять действия, использовать переменные и создавать сценарии."},{"title":"Пакеты и репозитории","body":"Пакетный менеджер учитывает файлы, версии и зависимости. Debian/Ubuntu: .deb, низкоуровневый dpkg и средства APT, в лекции apt-get. Red Hat/Fedora: .rpm, rpm и средства управления репозиториями, в лекции yum. В SUSE используется zypper. Изменение установленных системных пакетов обычно требует административных прав, поиск информации обычно доступен обычному пользователю."},{"title":"Языки и библиотеки","body":"C компилируется в машинный код; C++ добавляет объектные возможности. Java обычно компилируется в bytecode для JVM; JavaScript — другой язык, распространённый в вебе. Perl удобен для текста и автоматизации, PHP — для серверного веба, Ruby/Rails и Python/Django — для приложений. Библиотеки переиспользуют функциональность: OpenSSL — криптография, ImageMagick — изображения, C library — базовые операции."},{"title":"Безопасность и приватность","body":"Cookies хранят состояние сайта и могут участвовать в отслеживании. Приватный режим уменьшает локальные следы сеанса, но не обеспечивает полной анонимности. Используй уникальные пароли, менеджер паролей, второй фактор и обновления. Root — привилегированная учётная запись. Firewall фильтрует сетевой трафик; UFW/Gufw упрощают управление правилами."},{"title":"HTTPS, VPN и Tor","body":"HTTPS защищает соединение браузера с веб-сервером; VPN создаёт защищённый туннель между конечными точками. Tor пересылает трафик через сеть узлов для уменьшения привязки запросов к исходному адресу. Эти механизмы решают разные задачи и не отменяют необходимость осторожно обращаться с паролями и данными."},{"title":"Модели облака","body":"Public cloud обслуживает многих потребителей; private предназначен одной организации; community — группе организаций с общими требованиями; hybrid объединяет несколько облаков. Linux удобен в облаке благодаря модульности, автоматизации, масштабированию и доступности инструментов."},{"title":"Виртуализация и контейнеры","body":"Host — физический компьютер, guest — гостевая ОС, hypervisor распределяет ресурсы между ВМ. Bare-metal hypervisor работает непосредственно на оборудовании. Контейнеры изолируют приложения с использованием ядра хоста; Docker и Kubernetes связаны с упаковкой и управлением контейнерными нагрузками. Контейнер не следует считать отдельной полной гостевой ОС."}],"commands":[{"cmd":"zypper in package","description":"Установка пакета с зависимостями в системах с zypper; нужны подходящие права."},{"cmd":"dpkg","description":"Низкоуровневое управление пакетами Debian."},{"cmd":"rpm","description":"Низкоуровневое управление RPM-пакетами."}],"lab":[],"pitfalls":["MTA, MDA и почтовый клиент выполняют разные задачи.","Java и JavaScript — разные языки.","HTTPS и приватный режим не делают пользователя полностью анонимным.","Контейнеры используют ядро хоста, а виртуальные машины имеют гостевую ОС.","Упоминания старых инструментов и версий в лекции — контекст курса."],"questions":[{"type":"single","prompt":"В браузере открыта динамическая страница с данными студентов. Как обычно получается её содержимое?","options":["Приложение формирует ответ, при необходимости запрашивая БД","Браузер обязательно читает только неизменяемый файл","DNS рисует таблицу студентов","DHCP выполняет SQL-запрос за приложение"],"answer":[0],"explanation":"Динамическая страница формируется логикой приложения на основании запроса и данных.","difficulty":"applied"},{"type":"multi","prompt":"Выберите 2 веб-сервера.","options":["Apache HTTPD","NGINX","Audacity","GIMP"],"answer":[0,1],"explanation":"Apache HTTPD и NGINX обслуживают веб-запросы.","difficulty":"basic"},{"type":"single","prompt":"Какой продукт является СУБД?","options":["MariaDB","Thunderbird","Blender","Bash"],"answer":[0],"explanation":"MariaDB хранит данные и обслуживает запросы; остальные инструменты имеют другие роли.","difficulty":"basic"},{"type":"text","prompt":"Какой язык запросов назван в разделе о базах данных? Введите аббревиатуру.","answer":["SQL","sql","Sql"],"explanation":"Structured Query Language применяется для работы с данными в реляционных СУБД.","difficulty":"basic"},{"type":"multi","prompt":"Организации нужна собственная служба синхронизации файлов. Выберите 2 подходящих проекта из лекции.","options":["ownCloud","Nextcloud","Nano","Postfix"],"answer":[0,1],"explanation":"Оба проекта предоставляют функции частного хранения, синхронизации и обмена файлами.","difficulty":"applied"},{"type":"single","prompt":"Что делает MTA?","options":["Передаёт почтовые сообщения между системами","Редактирует изображения","Выдаёт IP-адреса","Показывает только локальный календарь"],"answer":[0],"explanation":"MTA — Mail Transfer Agent; примеры — Postfix и Sendmail.","difficulty":"basic"},{"type":"single","prompt":"В цепочке доставки какой компонент сохраняет письмо в локальном ящике пользователя?","options":["MDA","DNS","GIMP","Компилятор C"],"answer":[0],"explanation":"Mail Delivery Agent отвечает за локальное размещение сообщения.","difficulty":"basic"},{"type":"single","prompt":"Which application is a desktop email client?","options":["Thunderbird","Postfix","BIND","MariaDB"],"answer":[0],"explanation":"Thunderbird — клиент, тогда как Postfix передаёт письма между системами.","difficulty":"basic"},{"type":"single","prompt":"Нужно открыть общий ресурс Linux для клиентов Windows. Что выбрать из перечисленного?","options":["Samba","Audacity","Ruby","GNU Info"],"answer":[0],"explanation":"Samba реализует совместимость с Windows file sharing.","difficulty":"applied"},{"type":"single","prompt":"Какой протокол используется для типичного сетевого монтирования файловых ресурсов UNIX/Linux?","options":["NFS","SMTP","SQL","HTML"],"answer":[0],"explanation":"NFS делает удалённую файловую систему доступной через локальную иерархию.","difficulty":"basic"},{"type":"single","prompt":"Компьютеру автоматически назначили свободный IP-адрес. Какая служба это делает?","options":["DHCP","DNS","MDA","HTTPD"],"answer":[0],"explanation":"DHCP выдаёт адрес и другие сетевые параметры; DNS разрешает имена.","difficulty":"applied"},{"type":"single","prompt":"Приложение преобразует имя сервера в IP-адрес. Какой сервис необходим?","options":["DNS","Nano","ZIP","Calc"],"answer":[0],"explanation":"DNS хранит сведения об именах и связанных сетевых ресурсах.","difficulty":"basic"},{"type":"single","prompt":"Каталог хранит подразделения организации и пользователей в виде дерева. Какой протокол соответствует описанию?","options":["LDAP","JPEG","SSH как формат изображений","RPM"],"answer":[0],"explanation":"LDAP предназначен для доступа к иерархическим каталожным данным.","difficulty":"applied"},{"type":"multi","prompt":"Выберите 2 верные пары.","options":["Audacity — обработка аудио","Blender — 3D-графика","GIMP — выдача IP-адресов","LibreOffice Calc — передача почты между серверами"],"answer":[0,1],"explanation":"Творческие инструменты имеют разные специализации: звук, 3D и 2D.","difficulty":"basic"},{"type":"single","prompt":"Какое приложение LibreOffice предназначено прежде всего для таблиц и формул?","options":["Calc","Writer","Postfix","Dovecot"],"answer":[0],"explanation":"Calc работает с таблицами; Writer — с текстовыми документами.","difficulty":"basic"},{"type":"single","prompt":"Какой инструмент является оболочкой?","options":["Bash","GIMP","MariaDB","Firefox"],"answer":[0],"explanation":"Оболочка принимает команды и предоставляет язык для сценариев.","difficulty":"basic"},{"type":"single","prompt":"Нужно быстро изменить небольшой текстовый файл в консоли. Какой простой редактор указан в лекции?","options":["Nano","NGINX","BIND","Samba"],"answer":[0],"explanation":"Nano — консольный текстовый редактор с простым интерфейсом.","difficulty":"applied"},{"type":"single","prompt":"Какая пара правильно связывает низкоуровневый инструмент и формат пакета?","options":["dpkg — .deb","dpkg — .rpm","rpm — .docx","zypper — .jpg"],"answer":[0],"explanation":"dpkg работает с пакетами Debian.","difficulty":"basic"},{"type":"single","prompt":"Почему менеджер пакетов проверяет зависимости?","options":["Приложению могут требоваться другие пакеты и библиотеки","Каждый пакет обязан содержать браузер","Зависимость означает только цвет значка","Чтобы запретить обновления"],"answer":[0],"explanation":"Без требуемых библиотек установленная программа может не работать.","difficulty":"basic"},{"type":"single","prompt":"Какая операция обычно доступна без прав root?","options":["Поиск сведений о пакете","Удаление системного пакета","Обновление всех системных библиотек","Запись пакета в системный каталог"],"answer":[0],"explanation":"Запрос метаданных обычно не изменяет состояние системы.","difficulty":"basic"},{"type":"single","prompt":"Что исполняет bytecode Java?","options":["JVM","Только Bash без дополнительных компонентов","Только GIMP","DNS-сервер"],"answer":[0],"explanation":"Java Virtual Machine обеспечивает выполнение байткода на поддерживаемой платформе.","difficulty":"basic"},{"type":"single","prompt":"Какая библиотека связана с криптографией?","options":["OpenSSL","LibreOffice Calc","NFS","Thunderbird"],"answer":[0],"explanation":"OpenSSL предоставляет криптографические функции другим программам.","difficulty":"basic"},{"type":"single","prompt":"Пользователь открыл приватное окно браузера. Какой вывод корректен?","options":["Это не гарантия анонимности перед сайтами и сетевыми участниками","Все сайты перестают получать его запросы","Система автоматически получает права root","Все пароли становятся уникальными"],"answer":[0],"explanation":"Приватный режим прежде всего ограничивает сохранение локальных данных сеанса.","difficulty":"applied"},{"type":"multi","prompt":"Выберите 2 меры повышения защиты учётной записи.","options":["Уникальные пароли","Двухфакторная аутентификация","Один пароль для всех сайтов","Передача пароля через публичный чат"],"answer":[0,1],"explanation":"Разные пароли ограничивают последствия утечки, второй фактор добавляет независимую проверку.","difficulty":"basic"},{"type":"single","prompt":"Для одной организации выделена облачная инфраструктура исключительно под её задачи. Это…","options":["Private cloud","Public cloud по определению","Только локальный текстовый файл","Не может быть облаком"],"answer":[0],"explanation":"Частное облако предназначено одной организации и может размещаться у внешнего провайдера.","difficulty":"applied"},{"type":"single","prompt":"Две организации с общими требованиями совместно используют отдельное облако. Какая модель точнее?","options":["Community cloud","Hybrid обязательно в любом случае","Отдельный shell alias","Только public cloud"],"answer":[0],"explanation":"Community cloud рассчитано на сообщество организаций с общими целями.","difficulty":"applied"},{"type":"single","prompt":"Что отличает hypervisor от гостевого приложения?","options":["Он управляет ресурсами виртуальных машин","Он является только электронной таблицей","Он обязательно работает внутри браузера","Он заменяет любое оборудование"],"answer":[0],"explanation":"Гипервизор обеспечивает работу нескольких гостевых систем.","difficulty":"basic"},{"type":"multi","prompt":"Выберите 2 верных утверждения о виртуализации.","options":["Один host может запускать несколько guest OS","Гости могут использовать разные ОС","Каждому гостю обязательно нужен отдельный физический монитор","Виртуализация делает оперативную память бесконечной"],"answer":[0,1],"explanation":"ВМ разделяют ограниченные ресурсы хоста; гостевые ОС не обязаны совпадать.","difficulty":"basic"},{"type":"single","prompt":"Какое утверждение о контейнере точнее?","options":["Он изолирует приложение, используя ядро хоста","Он обязательно содержит отдельное физическое ядро CPU","Он всегда равен новой полной гостевой ОС","Он не связан с операционной системой"],"answer":[0],"explanation":"Контейнерная изоляция отличается от виртуальной машины с собственным гостевым ядром.","difficulty":"challenge"},{"type":"single","prompt":"Что объединяет несколько отдельных public/private/community clouds?","options":["Hybrid cloud","Один пароль","Только файловое расширение","Shell history"],"answer":[0],"explanation":"Гибридная модель соединяет разные облачные инфраструктуры.","difficulty":"basic"}],"sources":[{"kind":"chapter","title":"NDG Linux Essentials - Chapter 3 - Working in Linux.txt","url":"https://drive.google.com/file/d/1neYfQprUtL2vsBIG25UXfaeIV4B0amzt/view?usp=drivesdk"}]},{"id":4,"title":"Открытый код и лицензии","en":"Open Source Software and Licensing","intro":"Раздел о свободе использования программ, доступе к исходникам и условиях распространения. Различай стоимость, авторские права и лицензию: это не одно и то же.","sections":[{"title":"Исходный и исполняемый код","body":"Исходный код читают и изменяют разработчики. Компилятор переводит его в исполняемые инструкции; интерпретатор выполняет инструкции сценария. Доступ только к бинарному файлу не равен open source. Открытый процесс помогает совместно исправлять ошибки и изучать поведение программы."},{"title":"Стандарты и переносимость","body":"UNIX, язык C и стандартизированные интерфейсы способствовали переносу приложений между системами. POSIX задаёт общие интерфейсы и поведение; соответствие стандартам помогает совместимости независимо от открытости кода."},{"title":"Владение, оплата, лицензия","body":"Авторские права, цена и условия использования — три отдельные вещи. Лицензия определяет разрешённые действия. Бесплатное скачивание само по себе не даёт права изменять или распространять код. Открытое ПО можно продавать и сопровождать коммерчески."},{"title":"FSF и copyleft","body":"Free Software Foundation основана Richard Stallman; free здесь означает свободу изучать, использовать, изменять и распространять. Copyleft сохраняет эти свободы для распространяемых производных работ. GPL — семейство copyleft-лицензий; ядро Linux использует GPLv2. Не следует превращать это в правило «любое личное изменение надо немедленно публиковать»: важен контекст распространения. В лекции также упомянута LGPL для библиотек. Различия GPLv2 и GPLv3 иллюстрируются Tivoization: исходники доступны, но устройство препятствует запуску изменённых сборок; GPLv3 рассматривает такие ограничения отдельно."},{"title":"OSI и разрешительные лицензии","body":"Open Source Initiative оценивает лицензии по критериям open source. BSD и MIT — permissive-лицензии: они не требуют общего copyleft для всех производных работ, но сохраняют свои условия, например уведомления об авторских правах. FOSS объединяет free/open source; FLOSS добавляет libre, чтобы подчеркнуть свободу, а не нулевую цену."},{"title":"Creative Commons","body":"CC применяется прежде всего к творческому контенту. BY — указание авторства; SA — распространение адаптации на тех же условиях; NC — ограничение коммерческого использования; ND — запрет распространения производных работ без дополнительного разрешения. Сочетания дают CC BY, BY-SA, BY-ND, BY-NC, BY-NC-SA и BY-NC-ND. CC0 связано с отказом от прав в максимально доступной степени."},{"title":"Бизнес на open source","body":"Компании зарабатывают на поддержке, гарантиях, интеграции, обучении, оборудовании и дополнительных продуктах. Разработку поддерживают и организации, которым проект нужен для собственных систем. Возможность продажи не отменяет лицензионные условия распространения."}],"commands":[],"lab":[],"pitfalls":["Free software — про свободы, а не обязательную нулевую цену.","Copyleft не тождественен public domain.","Open source не означает отсутствие авторских прав.","Условия BY, SA, NC и ND независимы: проверяй всю комбинацию.","Лекция упрощает некоторые юридические детали; вопросы проверяют базовые учебные понятия."],"questions":[{"type":"single","prompt":"Какие три понятия необходимо различать при обсуждении покупки ПО?","options":["Владение правами, оплату и лицензию","CPU, RAM и монитор","Только бренд, размер и цвет","Директорию, файл и ссылку"],"answer":[0],"explanation":"Цена не определяет автоматически права на изменение и распространение.","difficulty":"basic"},{"type":"single","prompt":"Разработчик разрешил бесплатно скачать закрытую программу. Какой вывод верен?","options":["Это ещё не означает open source","Исходники автоматически стали public domain","Пользователь автоматически получил авторские права","GPL применяется без согласия автора"],"answer":[0],"explanation":"Бесплатная цена и открытая лицензия — независимые свойства.","difficulty":"applied"},{"type":"single","prompt":"Что означает free в философии FSF?","options":["Свободы пользователя","Обязательно отсутствие стоимости","Отсутствие условий распространения вообще","Обязательно отсутствие поддержки"],"answer":[0],"explanation":"FSF подчёркивает свободу использовать, изучать, изменять и распространять ПО.","difficulty":"basic"},{"type":"single","prompt":"Какая организация связана с созданием семейства GPL?","options":["FSF","Mozilla как автор всех GPL","ISC как автор всех GPL","Xerox PARC"],"answer":[0],"explanation":"Free Software Foundation развивает GPL и связанные лицензии.","difficulty":"basic"},{"type":"single","prompt":"В чём основная идея copyleft?","options":["Сохранять свободы и условия лицензии при распространении производных работ","Запретить изучать код","Отменить любое авторское право","Разрешить только личное чтение документации"],"answer":[0],"explanation":"Copyleft использует лицензионные условия, чтобы сохранять открытость распространяемых производных работ.","difficulty":"basic"},{"type":"single","prompt":"Какую версию GPL лекция связывает с ядром Linux?","options":["GPLv2","CC BY-ND","Только BSD 2-Clause","Никакую"],"answer":[0],"explanation":"В курсе ядро Linux рассматривается как GPLv2-проект.","difficulty":"basic"},{"type":"single","prompt":"What is the role of the Open Source Initiative?","options":["Evaluating licenses against open source principles","Assigning IP addresses","Maintaining every Linux package","Writing all proprietary EULAs"],"answer":[0],"explanation":"OSI поддерживает определение open source и признаёт соответствующие лицензии.","difficulty":"basic"},{"type":"multi","prompt":"Выберите 2 разрешительные лицензии, упомянутые в лекции.","options":["MIT","BSD","GPL как пример сильного copyleft","CC BY-NC-ND как лицензия программы"],"answer":[0,1],"explanation":"MIT и BSD обычно относятся к permissive free software licenses.","difficulty":"basic"},{"type":"single","prompt":"Какое утверждение о permissive-лицензиях наиболее точное?","options":["Они могут позволять включение кода в закрытый продукт при соблюдении условий","Они вообще не содержат условий","Они всегда запрещают продажу","Они требуют опубликовать любой несвязанный код компании"],"answer":[0],"explanation":"Разрешительность не отменяет сохранения нужных уведомлений и других конкретных условий.","difficulty":"applied"},{"type":"single","prompt":"Зачем в FLOSS добавлено слово libre?","options":["Чтобы отличить свободу от нулевой цены","Чтобы запретить Linux на серверах","Чтобы обозначить формат файла","Чтобы заменить слово software словом server"],"answer":[0],"explanation":"Libre снимает неоднозначность английского free.","difficulty":"basic"},{"type":"single","prompt":"Для каких объектов в первую очередь предназначены Creative Commons?","options":["Творческий контент: тексты, иллюстрации и подобные произведения","Только драйверы ядра","Только таблицы маршрутизации","Только аппаратные адреса"],"answer":[0],"explanation":"CC переносит идеи разрешённого использования на контент вне обычного программного лицензирования.","difficulty":"basic"},{"type":"text","prompt":"Какое условие CC требует указать автора? Введите две буквы.","answer":["BY","by","By"],"explanation":"Attribution обозначается BY.","difficulty":"basic"},{"type":"single","prompt":"Нужно распространять адаптацию на тех же лицензионных условиях. Какой элемент CC это выражает?","options":["SA","NC","ND","RPM"],"answer":[0],"explanation":"ShareAlike задаёт сохранение условий при распространении производной работы.","difficulty":"basic"},{"type":"single","prompt":"Что означает NC в CC BY-NC?","options":["NonCommercial","NoCopyright","NewCompiler","NetworkControl"],"answer":[0],"explanation":"NC ограничивает коммерческое использование.","difficulty":"basic"},{"type":"single","prompt":"Автор разрешает распространение неизменённой работы, но не адаптаций без разрешения. Какой элемент отражает это?","options":["ND","SA","BY как единственное ограничение","LTS"],"answer":[0],"explanation":"NoDerivatives касается распространения изменённых версий.","difficulty":"applied"},{"type":"multi","prompt":"В лицензии CC BY-NC-SA выберите 2 явно выраженных условия помимо указания авторства.","options":["Ограничение коммерческого использования","Сохранение условий для распространяемых адаптаций","Полный запрет любых адаптаций","Обязательная компиляция материала"],"answer":[0,1],"explanation":"NC и SA означают разные ограничения; ND в этой комбинации отсутствует.","difficulty":"applied"},{"type":"single","prompt":"Что обозначает CC0 в учебном сравнении?","options":["Инструмент отказа от прав, близкий к public domain","Особую лицензию только для root","Запрет любого копирования","Архив с нулевым сжатием"],"answer":[0],"explanation":"CC0 стремится максимально снять ограничения авторских и смежных прав.","difficulty":"basic"},{"type":"single","prompt":"Может ли бизнес зарабатывать на сопровождении открытого ПО?","options":["Да, например на поддержке и интеграции","Нет, слово free запрещает любой доход","Только если скрыть все исходники","Только если убрать лицензию"],"answer":[0],"explanation":"Коммерческая модель может продавать услуги вокруг открытого продукта.","difficulty":"applied"},{"type":"single","prompt":"Какую пользу дают стандартные API, например POSIX?","options":["Упрощают переносимость и совместимость приложений","Гарантируют одинаковые цены","Отменяют любую лицензию","Запрещают разные ОС"],"answer":[0],"explanation":"Стандарты определяют общие интерфейсы независимо от модели распространения.","difficulty":"basic"},{"type":"single","prompt":"Коллега говорит: «Copyleft — это отсутствие авторских прав». Почему это неверно?","options":["Copyleft опирается на авторское право и лицензионные условия","Copyleft — только алгоритм сжатия","Copyleft действует только на оборудование","Авторское право существует только у закрытых программ"],"answer":[0],"explanation":"Лицензия использует права автора для закрепления свобод и обязанностей.","difficulty":"challenge"}],"sources":[{"kind":"chapter","title":"NDG Linux Essentials - Chapter 4 - Open Source Software and Licensing.txt","url":"https://drive.google.com/file/d/1YVAqjr6IXqlBdqTF9olCkSTtbhIGRwxH/view?usp=drivesdk"}]},{"id":5,"title":"Командная строка","en":"Command Line Skills","intro":"Научись читать команду как «имя + опции + аргументы», понимать работу Bash, переменных, кавычек и условного запуска. Это основа большинства практических вопросов.","sections":[{"title":"Оболочка и приглашение","body":"Bash интерпретирует команды, поддерживает историю, сценарии, функции, переменные и aliases. В приглашении sysadmin@localhost:~$ обычно видны пользователь, имя узла и текущий каталог. Приглашение настраивается, поэтому его вид не гарантирован."},{"title":"Команды, опции и аргументы","body":"Общая форма: command [options] [arguments]. В ls -l /home команда — ls, опция — -l, аргумент — /home. Короткие опции часто объединяют: ls -lr равно ls -l -r. Длинные опции обычно начинаются с --. Регистр важен."},{"title":"История","body":"history показывает нумерованный список; history 5 — последние пять записей. ↑ и ↓ выбирают команды для редактирования. !n повторяет запись номер n; !-n — n-ю с конца; !! — последнюю; !ls — последнюю команду, начинающуюся с ls. HISTSIZE задаёт размер списка истории в Bash."},{"title":"Переменные и окружение","body":"Присваивание: name=value, без пробелов вокруг =. Значение читается как $name; echo выводит его. export делает переменную доступной дочерним процессам; env показывает окружение; unset удаляет переменную. Экспорт не меняет автоматически окружение уже работающих независимых оболочек и сам по себе не сохраняет значение навсегда."},{"title":"Поиск команд и PATH","body":"PATH содержит каталоги поиска исполняемых команд, разделённые двоеточиями. Порядок важен. which ищет внешний исполняемый файл по PATH; полный путь позволяет обратиться к нему явно. type учитывает встроенные команды, aliases и функции; type -a показывает все найденные варианты."},{"title":"Виды команд","body":"Builtin выполняется самой оболочкой, например cd. Внешняя команда — отдельный исполняемый файл. Alias заменяет короткое имя заданной командной строкой: alias ll='ls -l'. Функция объединяет последовательность команд. Настройки, созданные только в текущей оболочке, обычно исчезают при её закрытии."},{"title":"Кавычки и экранирование","body":"Одинарные кавычки сохраняют текст буквально. Двойные отключают globbing, но позволяют подстановку $variable и $(command). Обратная косая черта экранирует следующий специальный символ. Backticks и $(...) выполняют подстановку вывода команды. Незакрытая кавычка оставляет оболочку ждать продолжения."},{"title":"Последовательность и условия","body":"A ; B выполняет B после A независимо от результата. A && B запускает B только после успеха A; A || B — только после ошибки A. true всегда завершает успешно, false — неуспешно. Отсутствие видимого текста не означает ошибку."}],"commands":[{"cmd":"whoami","description":"Показать имя текущего пользователя."},{"cmd":"uname -n","description":"Показать имя сетевого узла; аналог --nodename."},{"cmd":"pwd","description":"Показать текущий каталог."},{"cmd":"history 5","description":"Показать пять последних записей истории."},{"cmd":"type -a echo","description":"Показать встроенную и внешние реализации echo, если они доступны."},{"cmd":"which date","description":"Найти внешний date по PATH."},{"cmd":"export course=Linux","description":"Создать экспортируемую переменную."},{"cmd":"echo \"$course\"","description":"Вывести значение переменной."},{"cmd":"alias ll='ls -l'","description":"Создать сокращение для длинного списка."},{"cmd":"false || echo retry","description":"Выполнить echo после неуспешной команды."}],"lab":[{"task":"Определи текущего пользователя, имя узла и рабочий каталог.","answer":"whoami\nuname -n\npwd","explanation":"Это три разных свойства среды; приглашение может показывать не все из них."},{"task":"Покажи последние пять команд и повтори последнюю запись без её перепечатывания.","answer":"history 5\n!!","explanation":"history выводит записи; !! выполняет последнюю, поэтому после history повторится именно history."},{"task":"Создай переменную course со значением Linux и сделай её доступной дочерним процессам.","answer":"course=Linux\nexport course\necho \"$course\"","explanation":"Без export это переменная текущей оболочки; export добавляет её в окружение будущих дочерних процессов."},{"task":"Сравни текст без подстановки и значение переменной.","answer":"echo '$HOME'\necho \"$HOME\"","explanation":"Первая команда выводит буквальное $HOME, вторая — значение HOME."},{"task":"Предскажи результат цепочки: echo Start && false && echo End.","answer":"Будет напечатано только Start.","explanation":"После false условие для последней команды && не выполнено."},{"task":"Создай короткое имя для подробного списка и проверь его тип.","answer":"alias ll='ls -l'\ntype ll","explanation":"type покажет alias; это не новый внешний исполняемый файл."}],"pitfalls":["Пробелы в name=value меняют разбор команды.","export не означает «изменить переменную во всех уже открытых терминалах».","Двойные кавычки не блокируют подстановку переменных.","; не проверяет успех предыдущей команды.","which и type могут дать разные ответы для одной команды."],"questions":[{"type":"single","prompt":"В строке ls -l /var что является аргументом, задающим объект действия?","options":["/var","ls","-l","Вся строка является одной опцией"],"answer":[0],"explanation":"Путь /var задаёт каталог; -l меняет формат вывода.","difficulty":"basic"},{"type":"single","prompt":"Какая запись для ls эквивалентна ls -l -r?","options":["ls -lr","ls --lr","ls /lr","ls -L -R"],"answer":[0],"explanation":"Короткие опции -l и -r можно объединить; регистр менять нельзя.","difficulty":"basic"},{"type":"single","prompt":"Что означает ~ в типичном приглашении anna@pc:~$?","options":["Домашний каталог anna","Корень файловой системы","Обязательно /tmp","Имя пакета"],"answer":[0],"explanation":"Тильда сокращённо обозначает домашний каталог текущего пользователя.","difficulty":"basic"},{"type":"single","prompt":"Какое присваивание корректно создаёт переменную label?","options":["label=Linux","label = Linux","$label=Linux","set label Linux как синтаксис Bash-присваивания"],"answer":[0],"explanation":"У обычного Bash-присваивания нет пробелов вокруг =.","difficulty":"basic"},{"type":"single","prompt":"После item=book что выведет echo \"$item\"?","options":["book","$item","item","Ничего, echo не читает переменные"],"answer":[0],"explanation":"В двойных кавычках Bash подставляет значение переменной.","difficulty":"applied"},{"type":"single","prompt":"После item=book что выведет echo '$item'?","options":["$item","book","item=book","Ошибка имени файла"],"answer":[0],"explanation":"Одинарные кавычки запрещают подстановку.","difficulty":"applied"},{"type":"single","prompt":"Для чего нужен export?","options":["Передать переменную в окружение будущих дочерних процессов","Сохранить все переменные навсегда","Изменить значения во всех независимых терминалах","Превратить текст в файл архива"],"answer":[0],"explanation":"Экспорт влияет на наследование окружения дочерними процессами.","difficulty":"basic"},{"type":"single","prompt":"Какая команда удалит переменную item из текущей оболочки?","options":["unset item","rm $item","delete item","export -all item"],"answer":[0],"explanation":"unset работает с переменными оболочки; rm удаляет файлы.","difficulty":"basic"},{"type":"text","prompt":"Каким символом разделены каталоги в PATH? Введите символ.","answer":[":"],"explanation":"Двоеточие отделяет один каталог поиска от другого.","difficulty":"basic"},{"type":"single","prompt":"PATH=/tools:/usr/bin. Исполняемый report есть в обоих каталогах; alias и функции с таким именем отсутствуют. Какой путь будет найден первым?","options":["/tools/report","/usr/bin/report","Оба выполнятся по очереди","Выбор всегда случайный"],"answer":[0],"explanation":"Каталоги PATH проверяются в указанном порядке.","difficulty":"applied"},{"type":"single","prompt":"Почему type echo может показать builtin, а which echo — /bin/echo?","options":["У echo могут быть встроенная и внешняя реализации","Один из инструментов обязан быть сломан","which всегда показывает домашний каталог","type никогда не работает с командами"],"answer":[0],"explanation":"type знает сущности оболочки; which обычно ищет внешний файл по PATH.","difficulty":"challenge"},{"type":"single","prompt":"Как проверить все доступные варианты команды echo?","options":["type -a echo","echo -a type","history echo","env echo -a"],"answer":[0],"explanation":"Опция -a у type показывает все найденные определения/местоположения.","difficulty":"basic"},{"type":"single","prompt":"Какой пример создаёт alias для ls -l?","options":["alias ll='ls -l'","alias=ll ls -l","ll alias ls -l","export ll ls -l"],"answer":[0],"explanation":"Alias задаётся как имя='командная строка'.","difficulty":"basic"},{"type":"single","prompt":"Что отличает функцию оболочки от простого сокращения имени команды?","options":["Она может объединять несколько команд и логику","Она обязательно хранится в ядре","Она не может вызываться по имени","Она всегда меняет файловую систему"],"answer":[0],"explanation":"Функции позволяют повторно вызывать группу действий.","difficulty":"basic"},{"type":"single","prompt":"В текущем каталоге есть a.txt и b.txt. Что выведет echo \"*.txt\"?","options":["*.txt","a.txt b.txt","Только a.txt","Содержимое обоих файлов"],"answer":[0],"explanation":"Двойные кавычки подавляют globbing.","difficulty":"applied"},{"type":"multi","prompt":"Выберите 2 вида подстановки, которые обычно сохраняются в двойных кавычках Bash.","options":["Подстановка переменной","Подстановка команды","Раскрытие * в список файлов","Обязательное удаление всех пробелов"],"answer":[0,1],"explanation":"Двойные кавычки сохраняют $variable и $(command), но блокируют pathname expansion.","difficulty":"basic"},{"type":"single","prompt":"Как вывести знак доллара буквально и при этом подставить значение HOME?","options":["echo \"Cost: \\$5; home: $HOME\"","echo 'Cost: $5; home: $HOME'","echo Cost: $5; home: $HOME","echo $(HOME)"],"answer":[0],"explanation":"Экранирован только доллар цены; $HOME остаётся подстановкой.","difficulty":"challenge"},{"type":"single","prompt":"Для чего служит конструкция $(date)?","options":["Подставляет вывод команды date","Всегда печатает буквальное date","Создаёт каталог date","Присваивает переменную с именем date"],"answer":[0],"explanation":"Command substitution заменяет конструкцию выводом команды.","difficulty":"basic"},{"type":"single","prompt":"What does !! do in interactive Bash history expansion?","options":["Runs the previous command","Deletes the history","Lists only aliases","Ends the current shell"],"answer":[0],"explanation":"!! повторяет последнюю команду истории.","difficulty":"basic"},{"type":"single","prompt":"Как выполнить запись истории под номером 17?","options":["!17","history=17","$17","!!17 как точный эквивалент"],"answer":[0],"explanation":"!n обращается к абсолютному номеру записи.","difficulty":"basic"},{"type":"single","prompt":"Что выведет false; echo Ready?","options":["Ready","Ничего","false Ready","Только сообщение синтаксической ошибки"],"answer":[0],"explanation":"Точка с запятой запускает следующую команду независимо от статуса предыдущей.","difficulty":"applied"},{"type":"single","prompt":"Что выведет false && echo Ready?","options":["Ничего","Ready","false","&&"],"answer":[0],"explanation":"После ошибки false правая сторона && пропускается.","difficulty":"applied"},{"type":"single","prompt":"Что выведет true || echo Retry?","options":["Ничего","Retry","true Retry","Сообщение о неизвестном true"],"answer":[0],"explanation":"true успешна, поэтому правая сторона || не выполняется.","difficulty":"applied"},{"type":"single","prompt":"Как запустить echo Failed только при неуспехе команды check?","options":["check || echo Failed","check && echo Failed","check; echo Failed","echo Failed; check"],"answer":[0],"explanation":"|| выполняет правую команду при неуспешном завершении левой.","difficulty":"applied"},{"type":"single","prompt":"Какой командой из лабораторной узнают имя текущего пользователя?","options":["whoami","uname -n","pwd","cal"],"answer":[0],"explanation":"whoami показывает пользователя, uname -n — имя узла, pwd — каталог.","difficulty":"basic"},{"type":"single","prompt":"После незакрытой кавычки оболочка показывает приглашение продолжения. Что это означает?","options":["Она ожидает завершения команды","Весь компьютер обязательно завис","Команда уже успешно завершилась","Файл автоматически удалён"],"answer":[0],"explanation":"Кавычки должны быть парными; пока строка не завершена, shell ждёт продолжения.","difficulty":"applied"}],"sources":[{"kind":"lab","title":"NDG Linux Essentials - Lab 5_ Command Line Skills.txt","url":"https://drive.google.com/file/d/13Lceo1Wd0Z_mNZMmwj6Hcmz9U-cT81om/view?usp=drivesdk"},{"kind":"chapter","title":"NDG Linux Essentials - Chapter 5 - Command Line Skills.txt","url":"https://drive.google.com/file/d/1qNfdjkWSf84C7dmHjf6Rnis6jW-uWmrv/view?usp=drivesdk"}]},{"id":6,"title":"Справка и поиск","en":"Getting Help","intro":"Умение найти нужную опцию важнее заучивания всех команд. Освой man, info, краткую справку и различия между поиском программы, документации и обычного файла.","sections":[{"title":"Чтение man","body":"man command открывает manual page через pager, обычно less. q выходит, пробел/PageDown листает вперёд, b/PageUp назад, стрелки перемещают по строкам. /term ищет вперёд; n повторяет поиск в его направлении, N — в противоположном. h показывает помощь pager."},{"title":"Структура страницы","body":"NAME даёт краткое назначение; SYNOPSIS — синтаксис; DESCRIPTION/OPTIONS — поведение и параметры; FILES — связанные файлы; AUTHOR, REPORTING BUGS и COPYRIGHT — сведения об авторах и сопровождении; SEE ALSO — связанные материалы. Не все страницы содержат все эти подразделы."},{"title":"Обозначения SYNOPSIS","body":"[item] означает необязательный элемент; ... — возможность повторения; A|B — альтернативы. В cal [[month] year] можно указать только год, а месяц требует года. Квадратные скобки из документации не нужно буквально печатать в обычной команде."},{"title":"Разделы руководства","body":"Номера категорий man: 1 — пользовательские команды; 2 — системные вызовы; 3 — библиотечные вызовы; 4 — специальные файлы; 5 — форматы файлов; 6 — игры; 7 — разное; 8 — администрирование; 9 — функции ядра. man 5 passwd открывает формат файла, а passwd(1) описывает команду смены пароля."},{"title":"Поиск в документации","body":"man -f name и whatis name показывают краткие сведения по имени. man -k keyword и apropos keyword ищут ключевое слово в именах и кратких описаниях. Это не то же самое, что /term внутри уже открытой страницы."},{"title":"Где находится файл","body":"which ищет исполняемый файл по PATH. whereis ищет команду, исходники и страницы справки в типичных местах. locate ищет пути в заранее построенной базе; locate -c считает совпадения, -b ограничивает поиск базовым именем. updatedb обновляет базу с соответствующими правами. Новый файл может ещё отсутствовать в базе."},{"title":"Info и другие источники","body":"info организует материалы в связанные узлы: Tab выбирает ссылку, Enter открывает, n/p перемещают между соседними узлами, u — выше, l — назад, q — выход. info без аргументов показывает верхний уровень. H открывает список команд, h — учебник. command --help даёт краткую справку; README и дополнительная документация обычно находятся в /usr/share/doc."}],"commands":[{"cmd":"man ls","description":"Открыть руководство по ls."},{"cmd":"man 5 passwd","description":"Открыть описание формата passwd."},{"cmd":"man -k password","description":"Найти страницы по ключевому слову."},{"cmd":"whatis passwd","description":"Показать краткие описания страниц с таким именем."},{"cmd":"whereis passwd","description":"Найти программу и связанную документацию."},{"cmd":"locate -c passwd","description":"Посчитать найденные пути в базе locate."},{"cmd":"locate -b '\\passwd'","description":"Искать точное базовое имя passwd в используемой в курсе реализации locate."},{"cmd":"info date","description":"Открыть Info-документацию date."},{"cmd":"date --help","description":"Показать краткую встроенную справку date."}],"lab":[{"task":"Открой man date, найди слово file, перейди к следующему совпадению и выйди.","answer":"man date\nВнутри страницы: /file, Enter, n, q","explanation":"Поиск выполняется в pager; n после поиска вперёд двигается к следующему совпадению."},{"task":"Найди справочные страницы, связанные с паролями, не зная точного имени команды.","answer":"man -k password\nили apropos password","explanation":"Поиск проводится по названиям и коротким описаниям."},{"task":"Открой документацию о структуре файла passwd, а не о команде смены пароля.","answer":"man 5 passwd","explanation":"Раздел 5 посвящён форматам файлов."},{"task":"Сравни поиск программы и поиск любых известных базе путей.","answer":"whereis passwd\nlocate passwd","explanation":"whereis ориентирован на программу и документацию; locate ищет по базе путей."},{"task":"Открой info date, перейди по ссылке и вернись назад.","answer":"info date\nTab → Enter → l → q","explanation":"Узлы Info связаны гиперссылками; l возвращает к предыдущему месту."},{"task":"Найди каталог с дополнительными README установленных пакетов.","answer":"ls /usr/share/doc","explanation":"Эта документация дополняет man/info и часто содержит подробности настройки."}],"pitfalls":["Раздел NAME внутри страницы и номер man(1)/man(5) — разные виды «раздела».","locate не проверяет всю файловую систему заново при каждом вызове.","whereis не является универсальным поиском всех пользовательских файлов.","Значение клавиши n в man и в info различается.","Синтаксические скобки в SYNOPSIS обычно не вводятся буквально."],"questions":[{"type":"single","prompt":"Как открыть руководство по команде cp?","options":["man cp","cp man","manual=cp","info --delete cp"],"answer":[0],"explanation":"man принимает имя нужной страницы.","difficulty":"basic"},{"type":"single","prompt":"Какой подраздел man показывает общую форму вызова команды?","options":["SYNOPSIS","COPYRIGHT","AUTHOR","REPORTING BUGS"],"answer":[0],"explanation":"SYNOPSIS кратко описывает допустимые параметры и аргументы.","difficulty":"basic"},{"type":"single","prompt":"Что означают квадратные скобки в SYNOPSIS?","options":["Элемент необязателен","Скобки всегда нужно вводить буквально","Элемент обязательно повторить дважды","Команда доступна только root"],"answer":[0],"explanation":"Это условное обозначение документации, а не обязательные символы команды.","difficulty":"basic"},{"type":"single","prompt":"В cal [[month] year] какое использование разрешает синтаксис?","options":["Указать только год","Указать месяц без года как документированный отдельный вариант","Всегда указывать две пары квадратных скобок","Обязательно не указывать аргументы"],"answer":[0],"explanation":"Внешняя группа допускает год, внутренняя — необязательный месяц при наличии года.","difficulty":"applied"},{"type":"single","prompt":"Что обозначает ... после [OPTION]?","options":["Можно использовать несколько элементов указанного типа","Команда находится в родительском каталоге","Нужно вывести три точки","Всегда требуется root"],"answer":[0],"explanation":"Многоточие обозначает повторяемость предшествующей конструкции.","difficulty":"basic"},{"type":"single","prompt":"В какой категории man обычно находится описание формата /etc/passwd?","options":["5","1","6","8"],"answer":[0],"explanation":"Категория 5 посвящена форматам файлов и соглашениям.","difficulty":"basic"},{"type":"single","prompt":"Нужно описание файла passwd, но man passwd показывает смену пароля. Что выполнить?","options":["man 5 passwd","passwd 5","man -k 5","man passwd /etc"],"answer":[0],"explanation":"Номер категории перед именем выбирает конкретную страницу.","difficulty":"applied"},{"type":"text","prompt":"Введите номер категории man для команд системного администрирования.","answer":["8"],"explanation":"Раздел 8 содержит команды администрирования.","difficulty":"basic"},{"type":"multi","prompt":"Выберите 2 команды, выполняющие поиск по ключевому слову в названиях и кратких описаниях man.","options":["apropos copy","man -k copy","man 5 copy","which copy"],"answer":[0,1],"explanation":"apropos и man -k имеют одно назначение.","difficulty":"basic"},{"type":"single","prompt":"Какая команда соответствует man -f passwd?","options":["whatis passwd","apropos passwd как поиск по всем описаниям","locate passwd","pwd passwd"],"answer":[0],"explanation":"whatis выдаёт краткие сведения по имени страницы.","difficulty":"basic"},{"type":"single","prompt":"Внутри man выполнен поиск /size. Какая клавиша переходит к следующему совпадению вперёд?","options":["n","q","u","Tab"],"answer":[0],"explanation":"После прямого поиска n продолжает в том же направлении.","difficulty":"basic"},{"type":"single","prompt":"Как выйти из просмотра man в обычном pager less?","options":["q","x как единственный способ","export","Ctrl+L как команда выхода"],"answer":[0],"explanation":"q закрывает просмотр и возвращает в оболочку.","difficulty":"basic"},{"type":"single","prompt":"Где искать ссылки на родственные команды в man?","options":["SEE ALSO","Только AUTHOR","Только COPYRIGHT","Только имя файла в prompt"],"answer":[0],"explanation":"SEE ALSO перечисляет связанные руководства и другие материалы.","difficulty":"basic"},{"type":"single","prompt":"Нужно найти исполняемый файл и его man-страницы в типичных местах. Что выбрать?","options":["whereis","echo","history","touch"],"answer":[0],"explanation":"whereis ориентирован на команды, исходники и справочные файлы.","difficulty":"applied"},{"type":"single","prompt":"Новый файл создан минуту назад, но locate его не показывает. Наиболее вероятное объяснение?","options":["База locate ещё не обновлялась","Файла заведомо не существует","locate всегда ищет только каталоги","Нужно переименовать файл в .gz"],"answer":[0],"explanation":"locate использует снимок путей, а не живой обход диска.","difficulty":"applied"},{"type":"single","prompt":"Какой инструмент обновляет базу locate?","options":["updatedb","update-shell","man -f","whereis -new"],"answer":[0],"explanation":"updatedb перестраивает поисковую базу; системная база требует подходящих прав.","difficulty":"basic"},{"type":"single","prompt":"Чем ограничивает поиск опция locate -b?","options":["Базовым именем без каталогов пути","Только бинарными программами","Только файлами размером в байт","Только архивами bzip2"],"answer":[0],"explanation":"Basename — последний компонент пути.","difficulty":"basic"},{"type":"single","prompt":"Что выдаёт locate -c pattern?","options":["Количество совпадений","Содержимое всех файлов","Текущий каталог","Полную справку по компрессии"],"answer":[0],"explanation":"Опция -c подсчитывает найденные пути.","difficulty":"basic"},{"type":"single","prompt":"Which documentation tool organizes topics into linked nodes?","options":["info","whoami","gzip","cp"],"answer":[0],"explanation":"Info связывает узлы документации в иерархию.","difficulty":"basic"},{"type":"single","prompt":"В Info открыта ссылка на дополнительную тему. Как вернуться к предыдущему просмотру?","options":["l","n как всегда возврат назад","rm","export"],"answer":[0],"explanation":"l возвращает к последнему посещённому узлу/месту; u поднимается по иерархии.","difficulty":"basic"},{"type":"single","prompt":"Какая команда быстро покажет краткое использование date без входа в pager?","options":["date --help","date --man-only","help-file date как универсальная команда","man -delete date"],"answer":[0],"explanation":"Многие команды поддерживают --help.","difficulty":"basic"},{"type":"single","prompt":"В каком каталоге обычно находятся дополнительные README установленных пакетов?","options":["/usr/share/doc","/dev/null","/proc/cpuinfo","/boot/grub как универсальное хранилище README"],"answer":[0],"explanation":"В /usr/share/doc пакеты размещают дополнительную документацию.","difficulty":"basic"},{"type":"single","prompt":"В чем разница между /password внутри man и man -k password?","options":["Первое ищет в открытой странице, второе — среди имён и описаний страниц","Оба всегда ищут файлы на диске","Первое удаляет совпадения","Второе меняет пароль"],"answer":[0],"explanation":"Это поиск на разных уровнях документации.","difficulty":"challenge"}],"sources":[{"kind":"lab","title":"NDG Linux Essentials - Lab 6_ Getting Help.txt","url":"https://drive.google.com/file/d/1TAIqJ8GW6T0q91sy0TLSoLWBnuxa6-KJ/view?usp=drivesdk"},{"kind":"chapter","title":"NDG Linux Essentials - Chapter 6 - Getting Help.txt","url":"https://drive.google.com/file/d/11xWT7ZXQ1OWpzkW6suTrZRlE9FcO2e1N/view?usp=drivesdk"}]},{"id":7,"title":"Навигация по файлам","en":"Navigating the Filesystem","intro":"Понимай дерево каталогов и различай абсолютный путь, относительный путь, домашний и текущий каталог. Учись читать ls и выбирать нужную сортировку.","sections":[{"title":"Дерево файловой системы","body":"Корень Linux обозначается /. Устройства подключаются к общей иерархии каталогов, а не получают обязательные буквы дисков C: и D:. Каталог — особый объект файловой системы, связывающий имена с файлами. Фраза «всё является файлом» подчёркивает единый подход к доступу к данным и устройствам."},{"title":"Домашний и текущий каталог","body":"Обычный домашний каталог часто имеет вид /home/имя, но это не обязательное правило. ~ обозначает home текущего пользователя; ~bob — home пользователя bob, если он существует. У root обычно /root. HOME хранит путь home, pwd показывает текущий каталог. Эти значения могут различаться. Доступ к чужому home определяется правами."},{"title":"Переход и пути","body":"cd path меняет текущий каталог, cd без аргументов возвращает домой. Абсолютный путь начинается с / и не зависит от текущего каталога. Относительный путь считается от текущего места. . — текущий каталог, .. — родитель; например ../../Downloads поднимается на два уровня и входит в Downloads. Тильда после раскрытия обычно образует абсолютный путь."},{"title":"Список и скрытые файлы","body":"ls без аргументов перечисляет видимые имена в текущем каталоге. ls /path показывает содержимое указанного каталога. Имя, начинающееся с точки, скрыто по соглашению; ls -a показывает такие имена. Цвет зависит от настроек и --color, а не является обязательным свойством вывода."},{"title":"Подробный вывод","body":"ls -l показывает тип, права, число жёстких ссылок, владельца, группу, размер, время изменения и имя. Первые символы: - обычный файл, d каталог, l символическая ссылка, s сокет, p FIFO, b блочное устройство, c символьное устройство. Стрелка у ссылки указывает цель. Размер каталога в этой строке не равен сумме размеров его содержимого."},{"title":"Размеры и каталоги","body":"ls -lh добавляет удобные единицы K/M/G к подробному выводу. ls -ld dir показывает сведения о самом каталоге вместо списка внутри него. ls -R dir рекурсивно перечисляет подкаталоги. Для выбора самих совпавших имён по шаблону полезно ls -d pattern."},{"title":"Порядок и время","body":"По умолчанию ls сортирует по имени с учётом локали. -S сортирует по размеру от большего к меньшему, -t — по времени изменения от нового к старому, -r разворачивает выбранный порядок. -R означает рекурсию, а не обратную сортировку. --full-time показывает подробное время. Время изменения каталога связано с изменениями его записей, а не с любым редактированием вложенного файла."},{"title":"Шаблоны из лабораторной","body":"В ls -d /etc/s* звёздочка выбирает имена, начинающиеся с s. /etc/???? — имена ровно из четырёх символов. /etc/[abcd]* — имена, начинающиеся с одного из перечисленных символов. Шаблоны раскрывает shell до запуска ls."}],"commands":[{"cmd":"pwd","description":"Показать текущий рабочий каталог."},{"cmd":"cd","description":"Перейти в домашний каталог."},{"cmd":"cd ../dict","description":"Перейти в соседний каталог dict через родительский."},{"cmd":"ls -a","description":"Показать в том числе скрытые имена."},{"cmd":"ls -ld /etc","description":"Показать метаданные самого /etc."},{"cmd":"ls -lhS","description":"Подробно вывести размеры, от большего к меньшему."},{"cmd":"ls -lrt","description":"Показать подробный список от старых изменений к новым."},{"cmd":"ls -R Documents","description":"Перечислить содержимое и подкаталоги Documents."},{"cmd":"ls -d /etc/????","description":"Выбрать имена из четырёх символов непосредственно в /etc."}],"lab":[{"task":"Из /usr/share/doc перейди в его дочерний каталог bash относительным путём и проверь результат.","answer":"cd bash\npwd","explanation":"Получится /usr/share/doc/bash, если этот каталог существует."},{"task":"Находясь в /usr/share/doc, перейди в соседний /usr/share/dict.","answer":"cd ../dict\npwd","explanation":".. означает /usr/share, затем выбирается dict."},{"task":"Покажи домашний и текущий каталог, затем вернись домой.","answer":"echo \"$HOME\"\npwd\ncd","explanation":"HOME не меняется при обычном cd; pwd показывает текущее место."},{"task":"Посмотри сведения о самом /etc и отдельно содержимое /etc.","answer":"ls -ld /etc\nls -l /etc","explanation":"Опция -d переключает ls на объект каталога вместо его содержимого."},{"task":"Перечисли скрытые файлы и каталоги дома.","answer":"ls -a ~","explanation":"Точка в начале имени скрывает запись от обычного ls."},{"task":"Покажи пути непосредственно в /etc, чьи имена имеют ровно четыре символа.","answer":"ls -d /etc/????","explanation":"Каждый ? соответствует одному символу, а -d не раскрывает содержимое найденных каталогов."}],"pitfalls":["/ — корень дерева, /root — обычно home администратора.","pwd и $HOME отвечают на разные вопросы.","ls -r разворачивает сортировку, ls -R включает рекурсию.","ls -l dir показывает содержимое, ls -ld dir — сам каталог.","Скрытое имя не означает, что файл защищён от доступа."],"questions":[{"type":"single","prompt":"Какой путь обозначает корень файловой системы Linux?","options":["/","/root","~","C:"],"answer":[0],"explanation":"Корень дерева — /; /root является отдельным каталогом.","difficulty":"basic"},{"type":"single","prompt":"У пользователя HOME=/home/lea, текущий каталог /etc. Что покажет pwd?","options":["/etc","/home/lea","~lea","/root"],"answer":[0],"explanation":"pwd показывает текущее место, а не домашний каталог.","difficulty":"applied"},{"type":"single","prompt":"Куда обычно приведёт cd без аргументов?","options":["В домашний каталог текущего пользователя","Всегда в /","На уровень выше","В первый каталог PATH"],"answer":[0],"explanation":"При отсутствии аргумента cd использует домашний каталог.","difficulty":"basic"},{"type":"multi","prompt":"Выберите 2 абсолютных пути.","options":["/usr/share/doc","/home/lea/notes.txt","../notes.txt","Documents/notes.txt"],"answer":[0,1],"explanation":"Абсолютные пути начинаются с корня /.","difficulty":"basic"},{"type":"single","prompt":"Текущий каталог /home/lea/Documents/School. Куда приведёт cd ../../Downloads, если каталог существует?","options":["/home/lea/Downloads","/home/Downloads","/home/lea/Documents/Downloads","/Downloads"],"answer":[0],"explanation":"Два .. поднимают от School к Documents, затем к /home/lea.","difficulty":"applied"},{"type":"single","prompt":"Находясь в /usr/share/doc, каким относительным путём перейти в /usr/share/man?","options":["../man","./man","../../man","/man"],"answer":[0],"explanation":"Сначала подняться в /usr/share, затем войти в man.","difficulty":"applied"},{"type":"single","prompt":"Что обозначает одиночная точка . в пути?","options":["Текущий каталог","Всегда домашний каталог","Всегда скрытый корень","Любую букву имени"],"answer":[0],"explanation":"Точка используется как ссылка на текущий каталог.","difficulty":"basic"},{"type":"single","prompt":"Что означает ~bob, если учётная запись bob существует?","options":["Домашний каталог bob","Файл с именем bob в текущем каталоге","Обязательно /root/bob","Родитель текущего каталога"],"answer":[0],"explanation":"Тильда с именем раскрывается в home указанного пользователя.","difficulty":"basic"},{"type":"single","prompt":"Файл .profile не виден в обычном ls. Какая опция покажет его?","options":["-a","-r","-S","-t"],"answer":[0],"explanation":"ls -a включает имена, начинающиеся с точки.","difficulty":"basic"},{"type":"single","prompt":"Что означает первый символ d в drwxr-xr-x?","options":["Каталог","Файл удалён","Размер равен десяти","Файл сжат"],"answer":[0],"explanation":"Первый символ long listing описывает тип объекта.","difficulty":"basic"},{"type":"single","prompt":"Строка начинается с lrwxrwxrwx и содержит стрелку ->. Что это?","options":["Символическая ссылка","Обычный каталог","Архив ZIP","Сокет"],"answer":[0],"explanation":"l обозначает symbolic link, стрелка показывает её цель.","difficulty":"basic"},{"type":"single","prompt":"В строке «-rw-r--r-- 1 lea staff 420 Nov 1 10:00 notes» что означает 420?","options":["Размер файла в байтах","UID владельца","Число строк","Количество жёстких ссылок"],"answer":[0],"explanation":"Размер следует за владельцем и группой; число ссылок расположено раньше.","difficulty":"applied"},{"type":"single","prompt":"Как получить права и владельца самого каталога Documents?","options":["ls -ld Documents","ls -l Documents","ls -R Documents","cd Documents"],"answer":[0],"explanation":"С -d ls выводит метаданные каталога, а не его дочерних записей.","difficulty":"applied"},{"type":"single","prompt":"Как прочитать значение размера каталога из ls -l?","options":["Это не суммарный размер всех вложенных файлов","Это всегда сумма всего дерева","Это всегда число пользователей","Это объём свободной памяти"],"answer":[0],"explanation":"Размер объекта каталога относится к его служебной структуре.","difficulty":"basic"},{"type":"single","prompt":"Нужно перечислить вложенные подкаталоги вместе с содержимым. Какая опция ls нужна?","options":["-R","-r","-d","-h"],"answer":[0],"explanation":"-R включает рекурсивный обход.","difficulty":"basic"},{"type":"single","prompt":"Какой порядок задаёт ls -lS?","options":["От больших файлов к меньшим","От меньших к большим","Только по времени от старых к новым","Всегда случайный"],"answer":[0],"explanation":"Заглавная -S сортирует по размеру по убыванию.","difficulty":"basic"},{"type":"single","prompt":"Как показать изменения от самых старых к самым новым?","options":["ls -lrt","ls -lt","ls -lS","ls -la"],"answer":[0],"explanation":"-t выбирает время, -r обращает стандартный порядок от новых к старым.","difficulty":"applied"},{"type":"single","prompt":"Какой параметр ls позволяет увидеть полный timestamp?","options":["--full-time","--all-sizes","--complete-path","--clock-only"],"answer":[0],"explanation":"--full-time показывает подробное время и включает длинный формат.","difficulty":"basic"},{"type":"single","prompt":"Есть каталог /etc/abcd с файлами внутри. Почему ls -d /etc/???? покажет /etc/abcd, а не его содержимое?","options":["-d просит показать сам совпавший каталог","? автоматически делает архив","Четыре ? означают поиск только обычных файлов","ls не умеет читать каталоги"],"answer":[0],"explanation":"? выбирает длину имени, а -d управляет поведением ls для каталога.","difficulty":"challenge"},{"type":"multi","prompt":"Выберите 2 верных утверждения о времени изменения каталога.","options":["Добавление записи файла меняет его содержимое","Удаление записи файла меняет его содержимое","Любое чтение вложенного файла обязательно меняет mtime каталога","mtime каталога всегда равно времени загрузки Linux"],"answer":[0,1],"explanation":"Каталог содержит записи имён; добавление и удаление меняют эту структуру.","difficulty":"basic"}],"sources":[{"kind":"chapter","title":"NDG Linux Essentials - Chapter 7 - Navigating the Filesystem.txt","url":"https://drive.google.com/file/d/1oerWiIO-FhG7TqBeu1XHAfY1xZJ39HUu/view?usp=drivesdk"},{"kind":"lab","title":"NDG Linux Essentials - Lab 7_ Navigating the Filesystem.txt","url":"https://drive.google.com/file/d/1kiRyMow2LxnqWz0eXjGGxJZFs4FitY88/view?usp=drivesdk"}]},{"id":8,"title":"Управление файлами","en":"Managing Files and Directories","intro":"Освой шаблоны имён и базовые действия: создать, скопировать, переименовать, переместить и удалить. Всегда различай исходный файл, цель и каталог назначения.","sections":[{"title":"Имена и globbing","body":"Linux различает регистр: notes.txt и Notes.txt — разные имена. Шаблоны glob раскрывает оболочка до запуска команды; они выбирают имена, а не строки внутри файлов. В обычных настройках Bash * не включает имена, начинающиеся с точки."},{"title":"Звёздочка и вопрос","body":"* соответствует нулю или более символов; ? — ровно одному. a* выбирает имена с начальной a, *.txt — с окончанием .txt, a?? — имена длиной три с начальной a. ?????*s требует как минимум шесть символов и завершающую s. Кавычки могут отключить раскрытие шаблона."},{"title":"Наборы и отрицание","body":"[abc] выбирает один символ из списка, [0-9] — одну цифру. [!DP]* означает имена, первый символ которых не D и не P. Набор всегда выбирает один символ; диапазоны зависят от правил сопоставления и локали, поэтому для учебных ASCII-примеров используй простые диапазоны."},{"title":"Просмотр совпадений","body":"echo pattern показывает раскрытые имена. Если glob передаёт каталог в ls, обычный ls показывает его содержимое. ls -d pattern выводит сами совпавшие объекты. Перед массовой операцией полезно проверить, какие имена выбраны."},{"title":"Копирование","body":"cp source destination создаёт копию. Если цель — существующий каталог, исходное имя сохраняется; если новое имя файла, копия получает это имя. -v показывает действия; -i спрашивает перед перезаписью; -n не перезаписывает существующую цель. -p сохраняет поддерживаемые атрибуты в пределах прав пользователя. Для каталога нужен -r или -R."},{"title":"Перемещение и переименование","body":"mv source destination переносит объект, а при новом имени также переименовывает. Исходное имя после успешного переноса исчезает. mv умеет переносить каталоги без -r. Опции -i, -n и -v похожи по смыслу на соответствующие опции cp."},{"title":"Создание и удаление","body":"touch newfile создаёт пустой файл, если его нет; существующий файл touch не обнуляет. mkdir создаёт каталог. rm удаляет файлы; -i запрашивает подтверждение, -r удаляет дерево каталога. rmdir удаляет только пустые каталоги. rm не перемещает объект в обычную графическую корзину."}],"commands":[{"cmd":"echo [DP]*","description":"Посмотреть имена, начинающиеся с D или P."},{"cmd":"ls -d *[0-9]*","description":"Показать имена с цифрой, не раскрывая найденные каталоги."},{"cmd":"cp -iv notes.txt backup.txt","description":"Скопировать с выводом действия и вопросом перед перезаписью."},{"cmd":"cp -p /etc/hosts hosts.copy","description":"Скопировать с сохранением допустимых атрибутов."},{"cmd":"cp -R project project-copy","description":"Скопировать дерево каталога."},{"cmd":"mv old.txt new.txt","description":"Переименовать файл."},{"cmd":"touch draft.txt","description":"Создать отсутствующий пустой файл."},{"cmd":"mkdir practice","description":"Создать каталог practice."},{"cmd":"rmdir empty-dir","description":"Удалить пустой каталог."}],"lab":[{"task":"В учебном каталоге есть draft.txt, data.csv, notes.txt и каталог docs. Выбери только имена с окончанием .txt.","answer":"ls -d *.txt","explanation":"Совпадут draft.txt и notes.txt; шаблон проверяет имена."},{"task":"Скопируй /etc/hosts в текущий учебный каталог под именем hosts.copy и покажи действие.","answer":"cp -v /etc/hosts hosts.copy","explanation":"Источник сохраняется, создаётся отдельная копия с новым именем."},{"task":"Скопируй hosts.copy в hosts.backup, не перезаписывая уже существующий backup.","answer":"cp -n hosts.copy hosts.backup","explanation":"No clobber сохраняет существующую цель без интерактивного вопроса."},{"task":"Создай Myetc, скопируй туда дерево /etc/udev и просмотри его.","answer":"mkdir Myetc\ncp -R /etc/udev Myetc\nls -lR Myetc","explanation":"В существующем Myetc появится подкаталог udev с содержимым, если доступ разрешён."},{"task":"Создай пустой premove и переименуй в postmove.","answer":"touch premove\nmv premove postmove\nls -l postmove","explanation":"mv меняет имя; копия premove не остаётся."},{"task":"В учебном каталоге создай и удали пустую папку scratch.","answer":"mkdir scratch\nrmdir scratch","explanation":"rmdir подходит только для пустой папки; для непустой он выдаст ошибку."},{"task":"Скопируй исходный файл с сохранением доступных времён и прав и сравни вывод.","answer":"cp -p /etc/hosts hosts.saved\nls -l /etc/hosts hosts.saved","explanation":"Обычный пользователь не обязательно сможет сохранить владельца root, хотя время и режим сохраняются."}],"pitfalls":["* и ? — не одно и то же: * может соответствовать пустой строке.","[abc] выбирает один символ, а не строку abc.","cp -r рекурсивен, но ls -r разворачивает сортировку.","mv каталогов не требует -r.","touch существующего файла не означает очистку его содержимого.","cp и mv могут перезаписать цель; rm обычно не использует корзину."],"questions":[{"type":"single","prompt":"Кто раскрывает *.txt перед запуском команды?","options":["Оболочка","Только cp","Ядро как отдельный редактор текста","Только файловый менеджер GUI"],"answer":[0],"explanation":"Globbing — функция shell, поэтому работает со многими командами.","difficulty":"basic"},{"type":"multi","prompt":"Какие 2 имени соответствуют шаблону a*?","options":["a","alpha","beta","Alpha"],"answer":[0,1],"explanation":"Звёздочка может сопоставиться с нулём символов, но регистр a остаётся значимым.","difficulty":"basic"},{"type":"single","prompt":"Какое имя подходит шаблону log?.txt?","options":["log7.txt","log.txt","log12.txt","xlog7.txt"],"answer":[0],"explanation":"? соответствует ровно одному символу.","difficulty":"basic"},{"type":"multi","prompt":"Какие 2 имени подходят шаблону [DP]*?","options":["Data","Public","Music","alphaDP"],"answer":[0,1],"explanation":"Набор действует только на первый символ.","difficulty":"basic"},{"type":"single","prompt":"Что выбирает [!ab]* среди обычных нескрытых имён?","options":["Имена, первый символ которых не a и не b","Имена без a и b в любой позиции","Только имя !ab","Все имена, начинающиеся с ab"],"answer":[0],"explanation":"Отрицание относится к одному символу внутри набора.","difficulty":"applied"},{"type":"single","prompt":"Какой шаблон выбирает имена с хотя бы одной цифрой?","options":["*[0-9]*","[0-9] без звёздочек как все такие имена","[!0-9]*","*.digit"],"answer":[0],"explanation":"Звёздочки разрешают любой префикс и суффикс вокруг одной обязательной цифры.","difficulty":"basic"},{"type":"text","prompt":"Какая минимальная длина имени соответствует ?????*s? Введите число.","answer":["6"],"explanation":"Пять ? требуют пять символов, затем обязательна s; * может быть пустым.","difficulty":"applied"},{"type":"single","prompt":"Почему ls -d a* бывает удобнее ls a* для проверки выбранных объектов?","options":["Он показывает имена совпавших каталогов вместо их содержимого","Он автоматически удаляет каталоги","Он отключает все совпадения","Он выбирает только файлы, созданные сегодня"],"answer":[0],"explanation":"Без -d каталог-аргумент раскрывается ls в список дочерних имён.","difficulty":"applied"},{"type":"single","prompt":"backup — существующий каталог. Что делает cp report.txt backup?","options":["Создаёт или перезаписывает backup/report.txt","Переименовывает report.txt в каталог","Удаляет report.txt после копирования","Всегда создаёт файл с буквальным именем backup вместо каталога"],"answer":[0],"explanation":"Существующий каталог назначения сохраняет базовое имя источника.","difficulty":"basic"},{"type":"single","prompt":"Как получить запрос перед перезаписью цели при копировании?","options":["cp -i a.txt b.txt","cp -v a.txt b.txt","cp -r a.txt b.txt","cp -p a.txt b.txt"],"answer":[0],"explanation":"-i — interactive; -v лишь сообщает о действиях.","difficulty":"basic"},{"type":"single","prompt":"Нужна копия, но существующий файл назначения должен остаться без вопросов. Какая опция соответствует этому в курсе?","options":["-n","-i","-v","-r"],"answer":[0],"explanation":"-n означает no clobber и предотвращает перезапись.","difficulty":"applied"},{"type":"single","prompt":"Как скопировать каталог вместе с вложенными файлами?","options":["cp -R project backup","cp project backup без опций","cp -l-only project backup","mv project backup как копирование"],"answer":[0],"explanation":"Для рекурсивной копии каталога нужна -R или -r.","difficulty":"basic"},{"type":"single","prompt":"В чём цель cp -p?","options":["Сохранить доступные атрибуты источника","Обязательно изменить владельца на root","Показать только справку","Удалить оригинал"],"answer":[0],"explanation":"-p сохраняет режим, времена и владение в пределах доступных прав.","difficulty":"basic"},{"type":"single","prompt":"Что делает mv old.txt new.txt, если new.txt не существует?","options":["Переименовывает old.txt в new.txt","Создаёт вторую копию и сохраняет старое имя","Объединяет текст двух файлов","Создаёт каталог old.txt"],"answer":[0],"explanation":"mv переносит имя, поэтому исходный путь после успеха исчезает.","difficulty":"basic"},{"type":"single","prompt":"Для перемещения каталога project в существующий каталог archive требуется…","options":["mv project archive","mv -r project archive как обязательная форма","cp project archive без рекурсии","touch project archive"],"answer":[0],"explanation":"mv умеет переносить каталоги без рекурсивной опции.","difficulty":"basic"},{"type":"single","prompt":"Каков размер нового отсутствовавшего файла сразу после touch empty.txt?","options":["0 байт","Всегда 1 КБ","Размер текущего каталога","Он обязательно содержит имя пользователя"],"answer":[0],"explanation":"touch создаёт пустой файл, если он отсутствует.","difficulty":"basic"},{"type":"single","prompt":"Как создать каталог practice?","options":["mkdir practice","touch practice как создание каталога","pwd practice","cd --create practice"],"answer":[0],"explanation":"mkdir создаёт каталог; touch создаёт обычный файл.","difficulty":"basic"},{"type":"single","prompt":"Каталог old содержит файл. Как поведёт себя rmdir old?","options":["Откажется удалить непустой каталог","Удалит всё дерево без вопросов","Создаст архив old.tar","Переместит файл в home"],"answer":[0],"explanation":"rmdir предназначен только для пустых каталогов.","difficulty":"applied"},{"type":"single","prompt":"Какая опция rm включает запрос подтверждения удаления?","options":["-i","-v","-p","-S"],"answer":[0],"explanation":"Интерактивная опция позволяет подтвердить конкретное удаление.","difficulty":"basic"},{"type":"multi","prompt":"После cp a.txt b.txt выполнено mv b.txt c.txt. Все команды успешны, исходно был только a.txt. Какие 2 имени остаются?","options":["a.txt","c.txt","b.txt","a.txt.backup"],"answer":[0,1],"explanation":"cp оставляет оригинал, затем mv заменяет имя b.txt на c.txt.","difficulty":"challenge"}],"sources":[{"kind":"lab","title":"NDG Linux Essentials - Lab 8_ Managing Files and Directories.txt","url":"https://drive.google.com/file/d/1Fw4GgQDdlOKNEqBbv02WSGRTopw_kW4Q/view?usp=drivesdk"},{"kind":"chapter","title":"NDG Linux Essentials - Chapter 8 - Managing Files and Directories.txt","url":"https://drive.google.com/file/d/1-SuLjFDuDU3HQJK9UnElLwAMgMFua31E/view?usp=drivesdk"}]},{"id":9,"title":"Архивы и сжатие","en":"Archiving and Compression","intro":"Архивирование собирает файлы в один контейнер, сжатие уменьшает представление данных. Отдельно отработай создание, просмотр и извлечение tar и ZIP.","sections":[{"title":"Зачем архивировать","body":"Архив удобен для передачи множества файлов, резервных копий и хранения старых журналов. Архивирование и сжатие можно использовать отдельно или вместе. Несжатый tar часто чуть больше суммы исходных данных из-за метаданных и выравнивания."},{"title":"Без потерь и с потерями","body":"Lossless позволяет восстановить исходные байты; это нужно программам, документам и логам. Lossy отбрасывает часть информации и подходит некоторым изображениям и звуку. PNG/GIF в рассматриваемом смысле используют сжатие без потерь, JPEG — с потерями. Уже сжатые данные часто плохо сжимаются повторно; эффективность зависит от содержимого."},{"title":"gzip, bzip2 и xz","body":"gzip file обычно заменяет исходный файл на file.gz; gunzip или gzip -d восстанавливает его. bzip2/bunzip2 используют .bz2, xz/unxz — .xz. gzip -l показывает размеры и степень сжатия. Алгоритмы дают разные соотношения скорости, памяти и размера; bzip2 или xz не гарантируют лучший результат для каждого файла."},{"title":"Режимы tar","body":"tar -c создаёт архив, -t перечисляет содержимое, -x извлекает. -f задаёт имя архива и требует своего аргумента; -v показывает обрабатываемые имена. tar -cf backup.tar dir автоматически включает вложенные каталоги. -r добавляет файлы в существующий несжатый tar-архив."},{"title":"tar со сжатием","body":"-z использует gzip, -j — bzip2. Примеры: tar -czf backup.tar.gz dir и tar -cjf backup.tar.bz2 dir. Расширения .tar.gz/.tgz и .tar.bz2/.tbz/.tbz2 — соглашения; одно переименование не меняет формат. Лучше ставить f последней в группе коротких опций и сразу указывать имя архива."},{"title":"Просмотр и извлечение","body":"tar -tf archive.tar показывает имена без извлечения. tar -xzf archive.tar.gz извлекает в текущий каталог, сохраняя относительные пути. Для одного файла укажи точное имя из списка архива. При создании архива из абсолютных путей обычный tar удаляет ведущий /; в лабораторной etc/udev восстанавливается внутри текущего каталога. Сам архив при извлечении остаётся."},{"title":"ZIP","body":"zip archive.zip files создаёт или дополняет ZIP и обычно оставляет исходные файлы. Для дерева каталога нужен zip -r archive.zip dir. unzip -l показывает содержимое, unzip archive.zip извлекает. Для одного объекта указывается его путь внутри ZIP. При совпадении имён unzip может спросить о замене; удобнее тренироваться в отдельном пустом каталоге."},{"title":"Практическое сравнение","body":"Сравнивай размеры на одинаковых данных и после каждой проверки восстанавливай исходный файл. В лабораторном примере xz оказался меньше gzip, а bzip2 — больше gzip; это результат конкретного файла, а не универсальный рейтинг. tar -r означает append, zip -r — рекурсию."}],"commands":[{"cmd":"gzip notes.txt","description":"Сжать один файл, обычно заменив его на notes.txt.gz."},{"cmd":"gunzip notes.txt.gz","description":"Восстановить несжатый файл."},{"cmd":"bzip2 notes.txt","description":"Сжать в notes.txt.bz2."},{"cmd":"bunzip2 notes.txt.bz2","description":"Распаковать bzip2."},{"cmd":"xz notes.txt","description":"Сжать в notes.txt.xz."},{"cmd":"unxz notes.txt.xz","description":"Распаковать xz."},{"cmd":"tar -czvf backup.tar.gz project","description":"Создать gzip-сжатый tar с выводом имён."},{"cmd":"tar -tf backup.tar","description":"Просмотреть архив без извлечения."},{"cmd":"tar -xjf backup.tar.bz2","description":"Извлечь bzip2-сжатый tar."},{"cmd":"tar -rf backup.tar notes.txt","description":"Добавить файл в несжатый tar."},{"cmd":"zip -r project.zip project","description":"Создать ZIP со всем деревом project."},{"cmd":"unzip -l project.zip","description":"Показать содержимое ZIP без извлечения."}],"lab":[{"task":"Собери учебную копию /etc/udev в несжатый архив и просмотри его.","answer":"mkdir mybackups\ntar -cvf mybackups/udev.tar /etc/udev\ntar -tvf mybackups/udev.tar","explanation":"tar рекурсивно добавляет дерево; ведущий / обычно удаляется из имён."},{"task":"Создай gzip-сжатую версию архива /etc/udev.","answer":"tar -czvf mybackups/udev.tar.gz /etc/udev\nls -lh mybackups","explanation":"Разница между обычным tar и этим архивом — использование gzip через -z."},{"task":"В отдельном каталоге mybackups извлеки архив udev.tar.gz.","answer":"cd mybackups\ntar -xzvf udev.tar.gz\nls etc/udev","explanation":"Запись etc/udev создаётся относительно текущего каталога, исходный архив остаётся."},{"task":"Добавь /etc/hosts в существующий несжатый udev.tar и проверь.","answer":"tar -rvf udev.tar /etc/hosts\ntar -tvf udev.tar","explanation":"-r означает добавление; имя архивного объекта обычно будет etc/hosts."},{"task":"Сожми учебный notes.txt и восстанови его каждым из трёх инструментов.","answer":"gzip notes.txt\ngunzip notes.txt.gz\nbzip2 notes.txt\nbunzip2 notes.txt.bz2\nxz notes.txt\nunxz notes.txt.xz","explanation":"После каждого сжатия исходное имя обычно заменяется, после восстановления появляется снова."},{"task":"Создай ZIP дерева project и проверь список, не извлекая данные.","answer":"zip -r project.zip project\nunzip -l project.zip","explanation":"ZIP требует -r для включения содержимого каталогов; -l у unzip только перечисляет."}],"pitfalls":["tar сам по себе не обязан сжимать данные.","Расширение файла не преобразует его формат.","-f у tar требует имя архива; не отдавай ему случайно букву другой опции.","gzip по умолчанию заменяет исходный файл, zip обычно сохраняет его.","tar включает вложенные каталоги автоматически; zip требует -r.","Имена при выборочном извлечении должны совпадать с путями внутри архива."],"questions":[{"type":"single","prompt":"Чем архивирование отличается от сжатия?","options":["Архивирование объединяет файлы, сжатие уменьшает представление данных","Это всегда одна и та же операция","Сжатие обязательно создаёт дерево каталогов","Архивирование всегда уничтожает исходники"],"answer":[0],"explanation":"Можно иметь несжатый архив или отдельно сжатый одиночный файл.","difficulty":"basic"},{"type":"single","prompt":"Какой тип сжатия нужен исполняемой программе, которую надо восстановить байт в байт?","options":["Lossless","Lossy","Только JPEG","Любой, данные не важны"],"answer":[0],"explanation":"Потеря даже части байтов может повредить программу.","difficulty":"applied"},{"type":"single","prompt":"Почему повторное сжатие уже сжатого изображения часто даёт мало пользы?","options":["Большая часть избыточности уже устранена","У изображения нет байтов","gzip всегда отказывается читать изображения","PNG обязательно несжатый"],"answer":[0],"explanation":"Новый алгоритм может почти не уменьшить размер уже сжатых данных.","difficulty":"basic"},{"type":"single","prompt":"Что обычно остаётся после успешного gzip report.txt без дополнительных опций?","options":["report.txt.gz вместо report.txt","Оба файла всегда","Только каталог report.txt","Файл report.zip"],"answer":[0],"explanation":"Обычное сжатие gzip заменяет исходный файл сжатым.","difficulty":"basic"},{"type":"multi","prompt":"Выберите 2 способа восстановить report.txt.gz.","options":["gunzip report.txt.gz","gzip -d report.txt.gz","zip report.txt.gz","tar -c report.txt.gz"],"answer":[0,1],"explanation":"gunzip и режим -d у gzip выполняют декомпрессию.","difficulty":"basic"},{"type":"single","prompt":"Какое расширение обычно создаёт xz?","options":[".xz",".bz2",".gz",".tar без дополнительных действий"],"answer":[0],"explanation":"Имя xz-компрессора соответствует расширению .xz.","difficulty":"basic"},{"type":"single","prompt":"Как распаковать файл data.bz2 специализированной парой к bzip2?","options":["bunzip2 data.bz2","unxz data.bz2","gzip data.bz2 как правильная декомпрессия","zip -r data.bz2"],"answer":[0],"explanation":"bunzip2 восстанавливает данные bzip2.","difficulty":"basic"},{"type":"single","prompt":"Что делает gzip -l data.gz?","options":["Показывает сведения о сжатом и исходном размере","Извлекает все каталоги","Удаляет архив","Создаёт новую символическую ссылку"],"answer":[0],"explanation":"Режим -l выводит статистику, а не распаковывает файл.","difficulty":"basic"},{"type":"single","prompt":"Какая команда создаст несжатый tar из каталога project?","options":["tar -cf project.tar project","tar -xf project.tar project","tar -tf project.tar project","gzip project.tar project как эквивалент"],"answer":[0],"explanation":"-c выбирает создание, -f задаёт имя архива.","difficulty":"basic"},{"type":"single","prompt":"Какая опция tar включает gzip?","options":["-z","-j","-t","-r"],"answer":[0],"explanation":"-z связано с gzip; -j — с bzip2.","difficulty":"basic"},{"type":"single","prompt":"Which tar option lists archive members without extraction?","options":["-t","-x","-c","-r"],"answer":[0],"explanation":"List mode -t показывает имена, не восстанавливая файлы.","difficulty":"basic"},{"type":"single","prompt":"Какая команда создаёт tar со сжатием bzip2?","options":["tar -cjf project.tar.bz2 project","tar -czf project.tar.bz2 project как bzip2","tar -xjf project.tar.bz2 project","zip -j project.tar.bz2 project"],"answer":[0],"explanation":"Формат задаёт -j; расширение само по себе алгоритм не переключает.","difficulty":"basic"},{"type":"single","prompt":"Чем опасна запись tar -xjfv data.tbz в рассматриваемом синтаксисе?","options":["-f получает v как имя архива","Она всегда удаляет data.tbz","-j превращается в Java","Она просто включает все флаги независимо от порядка"],"answer":[0],"explanation":"Опция -f потребляет следующий аргумент; безопасная форма — tar -xjvf data.tbz.","difficulty":"challenge"},{"type":"single","prompt":"В архиве объект называется School/Art/linux.txt. Как извлечь именно его?","options":["tar -xjf school.tbz School/Art/linux.txt","tar -xjf school.tbz linux.txt без пути как точное имя","tar -cjf school.tbz School/Art/linux.txt","tar -tjf school.tbz как извлечение"],"answer":[0],"explanation":"Путь должен соответствовать записи внутри архива, а -x выбирает извлечение.","difficulty":"applied"},{"type":"single","prompt":"В /home/lea/restore выполнено извлечение архива с относительным именем etc/hosts. Где появится файл?","options":["/home/lea/restore/etc/hosts","Всегда /etc/hosts","Всегда /root/hosts","Только внутри исходного архива, извлечения не будет"],"answer":[0],"explanation":"По умолчанию относительные пути восстанавливаются от текущего каталога.","difficulty":"applied"},{"type":"single","prompt":"Как добавить notes.txt в уже существующий несжатый backup.tar?","options":["tar -rf backup.tar notes.txt","tar -cf backup.tar notes.txt как добавление без пересоздания","tar -tf backup.tar notes.txt","gzip -r backup.tar notes.txt"],"answer":[0],"explanation":"-r означает append; -c создаёт новый архив.","difficulty":"basic"},{"type":"single","prompt":"Что необходимо для включения всех файлов подкаталога при создании ZIP?","options":["zip -r backup.zip project","zip backup.zip project без -r как полное дерево","unzip -l project","zip -f как обязательная рекурсия"],"answer":[0],"explanation":"ZIP не включает содержимое дерева каталогов автоматически, в отличие от tar.","difficulty":"basic"},{"type":"single","prompt":"Как просмотреть содержимое ZIP без распаковки?","options":["unzip -l backup.zip","zip -x backup.zip","gzip -l backup.zip как универсальный просмотр ZIP","tar -c backup.zip"],"answer":[0],"explanation":"-l у unzip перечисляет файлы.","difficulty":"basic"},{"type":"multi","prompt":"Выберите 2 корректных утверждения об исходных файлах.","options":["zip обычно оставляет исходные файлы","Извлечение tar обычно сохраняет сам архив","gzip без специальных опций всегда оставляет исходник","unzip обязан удалить ZIP после извлечения"],"answer":[0,1],"explanation":"Различай замену файла компрессором и создание/извлечение архива.","difficulty":"basic"},{"type":"single","prompt":"В лабораторной один и тот же файл дал .gz 260 КБ, .bz2 346 КБ, .xz 199 КБ. Какой вывод обоснован?","options":["В этом опыте xz дал наименьший файл; результат зависит от данных","xz всегда будет лучшим на любых данных","bzip2 никогда не умеет сжимать","gzip использует сжатие с потерями"],"answer":[0],"explanation":"Сравнение показывает результат конкретного набора данных, а не универсальное превосходство.","difficulty":"applied"}],"sources":[{"kind":"chapter","title":"NDG Linux Essentials - Chapter 9 - Archiving and Compression.txt","url":"https://drive.google.com/file/d/1NbcfUtceUxzJTcRLmAUVFnVFdD4EQqty/view?usp=drivesdk"},{"kind":"lab","title":"NDG Linux Essentials - Lab 9_ Archiving and Compression.txt","url":"https://drive.google.com/file/d/1gkDZyqDqP2H_v6nPVfKFbe87OGL3FEn9/view?usp=drivesdk"}]},{"id":10,"title":"Работа с текстом","en":"Working With Text","intro":"Потоки позволяют связать простые команды в цепочку: получить данные, отобрать строки, извлечь поля и сохранить результат. На экзамене важно проследить порядок обработки и отличать шаблоны shell от регулярных выражений grep.","sections":[{"title":"Просмотр файлов и навигация","body":"cat выводит содержимое и объединяет файлы. more и less показывают текст страницами; Space — следующая страница, Enter — строка, q — выход. В less доступны движение назад, /pattern для поиска вперёд, ?pattern назад, n для повтора и N для обратного направления. head и tail по умолчанию выводят 10 начальных или конечных строк. head -n -3 исключает последние 3 строки; tail -n +3 начинает с третьей. tail -f следит за дописыванием файла."},{"title":"Потоки, конвейеры и перенаправление","body":"stdin имеет номер 0, stdout — 1, stderr — 2. Символ | передаёт stdout предыдущей команды в stdin следующей; stderr автоматически в такой конвейер не попадает. > создаёт или обнуляет файл, >> дописывает, 2> направляет ошибки, < читает ввод из файла. command > all.txt 2>&1 объединяет потоки; в Bash можно &>. Порядок перенаправлений с 2>&1 важен. Порядок команд тоже важен: сначала пронумеровать строки и затем выбрать последние — не то же самое, что сначала выбрать и затем пронумеровать."},{"title":"Сортировка, статистика и столбцы","body":"sort сортирует строки; -n сравнивает числа, -r разворачивает порядок, -t задаёт разделитель, -k выбирает ключ. Для отдельного третьего поля удобно -k3,3. wc выводит число строк, слов и байтов; -l, -w, -c выбирают показатель. Байт не всегда равен символу, особенно в UTF-8. cut -d: -f1,5-7 извлекает поля, cut -c1-4 — позиции символов. tr преобразует символы и принимает данные через stdin."},{"title":"Фильтрация grep","body":"grep выводит целые строки, содержащие совпадение. -i игнорирует регистр, -v выбирает несовпавшие строки, -n добавляет исходные номера, -c считает совпавшие строки, -w ищет целые слова. --color подсвечивает совпадения. grep -F ищет буквальный текст (в лабораторной также встречается старое имя fgrep)."},{"title":"Базовые и расширенные regex","body":"Точка . означает один символ, [abc] — один из перечисленных, [0-9] — цифру, [^0-9] — один нецифровой символ. * повторяет предыдущий элемент ноль или более раз: re*d совпадает с rd, red, reed. ^ и $ закрепляют начало и конец строки; ^$ находит пустую строку. Обратная косая черта экранирует специальный символ. С grep -E доступны + (один и более), ? (ноль или один), | (или), группировка (...) и {3} (три повторения). Одинарные кавычки защищают шаблон от обработки shell."}],"commands":[{"cmd":"cut -d: -f1 /etc/passwd | sort | more","description":"Извлечь имена пользователей, отсортировать и показать страницами."},{"cmd":"grep -nE 'error|warning' app.log","description":"Найти два варианта и показать номера строк."},{"cmd":"tr 'a-z' 'A-Z' < input.txt > upper.txt","description":"Преобразовать латинские буквы из файла в верхний регистр."},{"cmd":"find /etc -name hosts > found.txt 2> errors.txt","description":"Разделить обычный вывод и диагностику."}],"lab":[{"task":"Сохраните Hello в message, затем допишите Again. Что проверить?","answer":"echo 'Hello' > message\necho 'Again' >> message\ncat message","explanation":"После двух команд файл содержит обе строки. Второй > вместо >> уничтожил бы Hello."},{"task":"Из /etc/passwd получите отсортированный список имён и просмотрите его страницами.","answer":"cut -d: -f1 /etc/passwd | sort | less","explanation":"Каждый этап получает stdout предыдущего; cut выбирает первое поле."},{"task":"Покажите первые 2 и последние 5 строк файла, затем найдите записи, начинающиеся с root.","answer":"head -n 2 /etc/passwd\ntail -n 5 /etc/passwd\ngrep '^root:' /etc/passwd","explanation":"Якорь и двоеточие отличают точное имя root от rootbackup и упоминаний /root в других полях."},{"task":"Найдите строки с тремя последовательными цифрами; затем найдите буквально текст a*b.","answer":"grep -E '[0-9]{3}' data.txt\ngrep -F 'a*b' data.txt","explanation":"Первый шаблон допускает совпадение внутри более длинной последовательности. Во второй команде * не оператор."}],"pitfalls":["grep -c считает строки, а не число всех совпадений.","[^0-9] не означает «строка без цифр»: в a7 тоже есть нецифровой символ.","В regex * повторяет предыдущий элемент; в glob *.txt обозначает имена файлов.","Не перенаправляй вывод команды в тот же входной файл через >: shell может обнулить его до чтения."],"questions":[{"type":"single","prompt":"После echo A > note и echo B > note что находится в note?","options":["A и B","Только B","Только A","Пустой файл"],"answer":[1],"explanation":"> обнуляет существующий файл перед записью.","difficulty":"basic"},{"type":"single","prompt":"Как сохранить старый журнал и дописать новую строку?","options":["echo done < run.log","echo done > run.log","echo done >> run.log","echo done | run.log"],"answer":[2],"explanation":">> дописывает stdout в конец файла.","difficulty":"basic"},{"type":"text","prompt":"Какой номер файлового дескриптора имеет stderr?","answer":["2"],"explanation":"Стандартные номера: stdin 0, stdout 1, stderr 2.","difficulty":"basic"},{"type":"single","prompt":"find /etc -name hosts > out.txt оставляет Permission denied на экране. Почему?","options":["find запрещает перенаправление","Ошибка идёт в stderr","Файл out.txt является каталогом","stdout всегда дублируется"],"answer":[1],"explanation":"Оператор > перенаправляет только stdout, ошибки требуют 2>.","difficulty":"applied"},{"type":"single","prompt":"Как направить stdout и stderr в один файл в указанном порядке?","options":["cmd > all.txt 2>&1","cmd 2< all.txt","cmd | all.txt","cmd < all.txt 2>1"],"answer":[0],"explanation":"Сначала stdout направляется в файл, затем stderr дублирует его назначение.","difficulty":"applied"},{"type":"single","prompt":"Что передаёт обычный конвейер cmd1 | cmd2?","options":["stdin cmd2 в stderr cmd1","stdout cmd1 в stdin cmd2","Оба вывода cmd1 в файл cmd2","Только код завершения"],"answer":[1],"explanation":"Обычный | соединяет стандартный вывод с вводом.","difficulty":"basic"},{"type":"single","prompt":"В файле 30 строк. Сколько выведет head -n -7 file?","options":["7","30","23","0"],"answer":[2],"explanation":"Отрицательный аргумент -n в GNU head исключает указанное число конечных строк.","difficulty":"challenge"},{"type":"single","prompt":"Файл содержит строки 1–12. Что выдаст tail -n +9 file?","options":["Последние 9 строк","Строки 1–9","Только строку 9","Строки 9–12"],"answer":[3],"explanation":"Плюс означает начать с указанной строки, а не отсчитать с конца.","difficulty":"applied"},{"type":"single","prompt":"Как наблюдать строки, которые приложение дописывает в лог?","options":["head -f app.log","tail -f app.log","cut -f app.log","sort -f app.log"],"answer":[1],"explanation":"tail -f продолжает следить за появлением данных.","difficulty":"applied"},{"type":"text","prompt":"Какой клавишей выйти из less? Введите один символ.","answer":["q"],"explanation":"q завершает просмотр и возвращает приглашение shell.","difficulty":"basic"},{"type":"single","prompt":"После поиска /disk в less какой символ повторит поиск в обратном направлении?","options":["n","N","x","!"],"answer":[1],"explanation":"n повторяет текущее направление поиска; N меняет его.","difficulty":"applied"},{"type":"single","prompt":"Строки 2, 11, 3 надо упорядочить по числовому значению. Какая команда подходит?","options":["sort -n nums","sort -r nums","wc -n nums","cut -n nums"],"answer":[0],"explanation":"-n сравнивает числа; обычная текстовая сортировка может поставить 11 перед 2.","difficulty":"applied"},{"type":"single","prompt":"Что делает cut -d: -f1,3 users?","options":["Выводит строки 1–3","Выводит поля 1 и 3 с разделителем :","Удаляет символы :","Сортирует по третьему полю"],"answer":[1],"explanation":"-d задаёт разделитель, -f выбирает поля.","difficulty":"applied"},{"type":"single","prompt":"В строке error error error. Чему равен grep -c error для файла только с этой строкой?","options":["3","0","1","9"],"answer":[2],"explanation":"Счётчик -c относится к подходящим строкам, а не к повторениям слова.","difficulty":"applied"},{"type":"single","prompt":"Нужно исключить строки с nologin из /etc/passwd. Выберите команду.","options":["grep -i nologin /etc/passwd","grep -v nologin /etc/passwd","grep -n nologin /etc/passwd","grep -w nologin /etc/passwd"],"answer":[1],"explanation":"-v инвертирует отбор: остаются строки без совпадения.","difficulty":"applied"},{"type":"multi","prompt":"Какие 2 строки совпадут с ^r..t$?","options":["root","rot","r00t","rooted"],"answer":[0,2],"explanation":"Между r и t требуется ровно два символа, а якоря ограничивают всю строку.","difficulty":"applied"},{"type":"single","prompt":"Какой шаблон выбирает только пустые строки?","options":[".*","^$","[ ]","$^."],"answer":[1],"explanation":"Между началом и концом строки нет символов.","difficulty":"basic"},{"type":"multi","prompt":"Какие 2 строки совпадут с ^re*d$?","options":["rd","reed","read","redder"],"answer":[0,1],"explanation":"e* допускает ноль или несколько e, но не a и не лишние символы после d.","difficulty":"applied"},{"type":"single","prompt":"Why does grep 'z*' match a line containing no z?","options":["* означает отрицание","Разрешено ноль вхождений z","grep игнорирует z","Без -E поиск всегда успешен"],"answer":[1],"explanation":"Нулевое совпадение возможно в любой строке.","difficulty":"applied"},{"type":"single","prompt":"Какой вариант ищет gray ИЛИ grey?","options":["grep 'gray|grey' file","grep -E 'gray|grey' file","grep -v 'gray|grey' file","grep -F 'gray|grey' file"],"answer":[1],"explanation":"В расширенном regex | — альтернативы; -F ищет буквальную вертикальную черту.","difficulty":"applied"},{"type":"single","prompt":"Какая строка НЕ совпадает с [^0-9]?","options":["abc","123","a1","7!"],"answer":[1],"explanation":"123 состоит только из цифр; остальные строки содержат хотя бы один нецифровой символ.","difficulty":"challenge"},{"type":"single","prompt":"Как получить число строк в файле?","options":["wc -w file","wc -c file","wc -l file","wc -f file"],"answer":[2],"explanation":"-l считает символы перевода строки; для обычного построчного файла это число строк.","difficulty":"basic"},{"type":"single","prompt":"Команда tr 'a-z' 'A-Z' file.txt жалуется на лишний аргумент. Как исправить?","options":["tr 'a-z' 'A-Z' < file.txt","tr -f file.txt","tr file.txt | 'A-Z'","tr > file.txt"],"answer":[0],"explanation":"tr читает преобразуемый текст из stdin, а не из аргумента с именем файла.","difficulty":"applied"},{"type":"single","prompt":"Есть 20 непустых строк. Чем отличается nl file | tail -5 от tail -5 file | nl?","options":["Ничем","В первой номера 16–20, во второй 1–5","В первой 1–5, во второй 16–20","Первая удаляет строки из файла"],"answer":[1],"explanation":"Нумерация до отбора сохраняет исходные номера; после отбора начинает заново.","difficulty":"challenge"}],"sources":[{"kind":"lab","title":"NDG Linux Essentials - Lab 10_ Working With Text.txt","url":"https://drive.google.com/file/d/1mFFoixNaezLnf_moXb906pOQGga57Uq9/view?usp=drivesdk"},{"kind":"chapter","title":"NDG Linux Essentials - Chapter 10 - Working With Text.txt","url":"https://drive.google.com/file/d/1eTDq83DX3e09YE90gn-RRVKkCbK5n8za/view?usp=drivesdk"}]},{"id":11,"title":"Скрипты и редакторы","en":"Basic Scripting","intro":"Shell-скрипт — обычный текстовый файл с командами. Он автоматизирует повторяемую последовательность; переменные хранят данные, условия выбирают действия, циклы повторяют их. Длинные программы для этого раздела не нужны: достаточно уверенно читать короткие фрагменты.","sections":[{"title":"Запуск и shebang","body":"Строка #!/bin/bash в самом начале задаёт интерпретатор при прямом запуске. ./task.sh указывает файл в текущем каталоге и требует права выполнения. bash task.sh запускает уже выбранный Bash и требует чтения скрипта, но не бита x на самом скрипте. Если команда task.sh не найдена, проверь PATH: текущий каталог обычно туда не включён."},{"title":"nano","body":"nano file открывает простой текстовый редактор. Ctrl+O сохраняет, Ctrl+X выходит, Ctrl+W ищет, Ctrl+K вырезает строку, Ctrl+U вставляет, Ctrl+G показывает помощь. Внизу ^ означает клавишу Ctrl. После Ctrl+X при несохранённых изменениях можно подтвердить сохранение Y и имя Enter."},{"title":"vi: режимы, движение, правки","body":"vi начинает в командном режиме. i вставляет перед курсором, a после; I и A — в начале и конце строки; o/O открывают новую строку ниже/выше. Esc возвращает командный режим. h/j/k/l движутся влево/вниз/вверх/вправо, w/e/b — по словам, 0/$ — к началу/концу строки, nG — к строке n, G — в конец файла. x/X удаляют символ справа/слева, dw слово, dd строку, D остаток строки, cw заменяет слово. Число повторяет действие: 2dd. u отменяет, yw/yy копируют, p/P вставляют после/перед, J объединяет строки, ~ меняет регистр."},{"title":"vi: поиск и сохранение","body":"/text ищет вперёд, ?text назад, n повторяет текущее направление. :%s/old/new/g заменяет все совпадения во всём файле. :w сохраняет; :wq, :x и ZZ сохраняют и выходят; :q! выходит без сохранения; :e! перечитывает файл, отбрасывая изменения. Восклицательный знак не даёт прав root и не отменяет ограничения файловой системы."},{"title":"Переменные, ввод и статус","body":"NAME=value присваивает без пробелов вокруг =; $NAME подставляет значение. Двойные кавычки позволяют подстановку и сохраняют пробелы. read NAME читает ввод. $1 — первый аргумент, $0 — имя скрипта, $? — статус последней команды: 0 обычно успех, ненулевой код — иной результат или ошибка. grep возвращает 1 при отсутствии совпадения; -q подавляет обычный вывод. Подстановка команды $(pwd), как и обратные кавычки из курса, сохраняет её вывод. exit 1 завершает скрипт с кодом 1; # начинает комментарий."},{"title":"Условия и циклы","body":"if command; then ...; else ...; fi проверяет успешность команды. test и [ ... ] сравнивают значения: -eq/-ne для чисел, =/!= для строк, -lt/-le/-gt для порядка, -f для обычного файла, -d для каталога, -x для разрешения выполнения, ! для отрицания. Вокруг [ и ] нужны пробелы. elif добавляет проверки, case выбирает первую подходящую ветку, ;; завершает её, esac закрывает case. for перебирает список; while повторяет тело, пока условие истинно. do/done ограничивают тело. $((i + 1)) вычисляет арифметику, seq формирует числовую последовательность."}],"commands":[{"cmd":"chmod u+x task.sh","description":"Разрешить владельцу прямой запуск скрипта."},{"cmd":"bash task.sh","description":"Прочитать скрипт интерпретатором Bash."},{"cmd":"if [ -d /tmp ]; then echo yes; fi","description":"Короткая проверка существования каталога."},{"cmd":"for n in 1 2 3; do echo \"$n\"; done","description":"Напечатать три значения по одному."}],"lab":[{"task":"В vi удалите две строки, отмените удаление и сохраните файл.","answer":"Esc → 2dd → u → :w → Enter","explanation":"2dd — одно действие над двумя строками, поэтому достаточно одного u."},{"task":"Создайте скрипт, который приветствует первый переданный аргумент.","answer":"#!/bin/bash\necho \"Hello $1\"","explanation":"После сохранения запустите bash hello.sh Aida; результат Hello Aida."},{"task":"Что проверять, если ./sample.sh работает, а sample.sh — нет?","answer":"echo \"$PATH\"","explanation":"Прямой путь обходит поиск PATH. Для запуска по имени каталог скрипта должен быть в PATH."},{"task":"Составьте короткий цикл для создания test1, test2 и test3 в учебной папке.","answer":"for n in 1 2 3; do touch \"test$n\"; done","explanation":"for присваивает n каждый элемент списка; кавычки сохраняют собранное имя одним аргументом."},{"task":"Сколько раз выполнится тело while [ \"$num\" -le 100 ], если вводы последовательно 25, 99, 101 и следующий read стоит в теле?","answer":"Два раза.","explanation":"25 и 99 удовлетворяют условию; при 101 происходит выход из цикла."}],"pitfalls":["NAME = value не является присваиванием Bash.","Числа 01 и 1 численно равны, но как строки различны.","Проверка -f означает обычный файл; она не считает каталог обычным файлом.","После любой новой команды $? уже относится к ней, а не к более ранней проверке."],"questions":[{"type":"single","prompt":"What does #!/bin/bash specify when a script is executed directly?","options":["Каталог вывода","Интерпретатор","Имя владельца","Список аргументов"],"answer":[1],"explanation":"Shebang задаёт программу, которая прочитает исполняемый текст.","difficulty":"basic"},{"type":"single","prompt":"Скрипт читается, но не имеет x. Как запустить его через Bash?","options":["./script.sh","bash script.sh","chmod script.sh","exec -r script.sh"],"answer":[1],"explanation":"Bash читает файл как данные; прямой запуск ./ требует x.","difficulty":"applied"},{"type":"single","prompt":"Почему исполняемый файл в текущей папке работает как ./run.sh, но не как run.sh?","options":["У имени .sh запрещён поиск","Текущая папка не включена в PATH","Нужен root для .sh","Shebang игнорирует точки"],"answer":[1],"explanation":"Без / shell ищет команду в PATH; ./ явно задаёт путь.","difficulty":"applied"},{"type":"single","prompt":"Какая строка корректно присваивает переменную?","options":["TOPIC = Linux","$TOPIC=Linux","TOPIC=Linux","set TOPIC Linux"],"answer":[2],"explanation":"В присваивании нет $ перед именем и нет пробелов вокруг =.","difficulty":"basic"},{"type":"single","prompt":"После NAME=Sam; echo \"Hi $NAME\" что выводится?","options":["Hi NAME","Hi $NAME","Hi Sam","Sam Hi"],"answer":[2],"explanation":"Двойные кавычки разрешают подстановку переменной.","difficulty":"applied"},{"type":"text","prompt":"Как обозначается первый аргумент shell-скрипта?","answer":["$1"],"explanation":"$0 — имя скрипта, $1 — первый переданный аргумент.","difficulty":"basic"},{"type":"single","prompt":"Как сохранить введённое пользователем имя в переменную NAME?","options":["echo NAME","read NAME","read $NAME","input NAME"],"answer":[1],"explanation":"read получает имя переменной без знака $.","difficulty":"basic"},{"type":"single","prompt":"Команда grep -q absent file завершилась с кодом 1. Что это обычно означает?","options":["Совпадение найдено","Совпадение не найдено","Успешно удалён файл","Обязательно отказ прав"],"answer":[1],"explanation":"grep различает найдено (0), не найдено (1) и ошибки; -q только скрывает обычный вывод.","difficulty":"applied"},{"type":"text","prompt":"Какой код завершения обычно означает успешное выполнение?","answer":["0"],"explanation":"Shell-условия считают код 0 истинным результатом команды.","difficulty":"basic"},{"type":"single","prompt":"Что хранит HERE=$(pwd)?","options":["Буквальные символы pwd","Содержимое домашней папки","Вывод pwd — путь текущего каталога","PID команды"],"answer":[2],"explanation":"Подстановка команды выполняет pwd и подставляет её стандартный вывод.","difficulty":"applied"},{"type":"single","prompt":"Выберите корректный тест существования каталога /tmp.","options":["[ -d /tmp ]","[-d /tmp]","[ -f /tmp ]","test /tmp -dir"],"answer":[0],"explanation":"-d проверяет каталог; [ и ] должны быть отдельными аргументами.","difficulty":"applied"},{"type":"single","prompt":"Для значений 01 и 1 какой вывод верен?","options":["И строки, и числа различны","Численно равны, как строки различны","Строки равны, числа различны","Bash не сравнивает такие значения"],"answer":[1],"explanation":"-eq сравнивает числа, = сравнивает текст.","difficulty":"challenge"},{"type":"single","prompt":"Сколько строк напечатает for x in red blue green; do echo \"$x\"; done?","options":["1","2","3","Бесконечно"],"answer":[2],"explanation":"Тело выполняется один раз на каждый элемент списка.","difficulty":"applied"},{"type":"single","prompt":"i=0; while [ \"$i\" -lt 3 ]; do echo \"$i\"; i=$((i+1)); done — последний вывод?","options":["0","2","3","4"],"answer":[1],"explanation":"Цикл выводит 0, 1, 2; при i=3 условие уже ложно.","difficulty":"applied"},{"type":"single","prompt":"В case какая ветка обычно играет роль варианта по умолчанию?","options":["?)","*)","default:","else)"],"answer":[1],"explanation":"Шаблон * совпадает с любым оставшимся значением; обычно его ставят последним.","difficulty":"applied"},{"type":"single","prompt":"В nano что означает подпись ^O WriteOut?","options":["Нажать буквы ^ и O","Ctrl+O — сохранить","Alt+O — открыть","Shift+O — выйти"],"answer":[1],"explanation":"^ в подсказках nano обозначает Ctrl.","difficulty":"basic"},{"type":"text","prompt":"Какой клавишей вернуться из insert mode vi в command mode?","answer":["Esc","Escape","esc","escape"],"explanation":"Esc прекращает ввод текста и возвращает режим команд.","difficulty":"basic"},{"type":"single","prompt":"В vi нужно открыть пустую строку НАД текущей и начать ввод. Какая команда?","options":["o","O","i","a"],"answer":[1],"explanation":"O вставляет строку сверху; o — снизу.","difficulty":"applied"},{"type":"single","prompt":"Что делает 2dd в командном режиме vi?","options":["Копирует две строки","Удаляет текущую и следующую строки","Удаляет два символа","Переходит на строку 2"],"answer":[1],"explanation":"dd удаляет строку, числовой префикс повторяет действие.","difficulty":"applied"},{"type":"single","prompt":"Вы случайно изменили файл в vi и хотите выйти, сохранив старую версию на диске.","options":[":wq",":q!",":w!",":x"],"answer":[1],"explanation":":q! отбрасывает несохранённые изменения.","difficulty":"applied"},{"type":"multi","prompt":"Какие 2 действия в vi сохраняют изменения и завершают редактор?","options":[":wq","ZZ",":w",":e!"],"answer":[0,1],"explanation":":w только сохраняет, :e! перечитывает старую версию.","difficulty":"applied"},{"type":"single","prompt":"Как заменить все old на new во всём файле в vi?","options":[":s/old/new/",":%s/old/new/g","/old/new","%replace old new"],"answer":[1],"explanation":"% задаёт все строки, g — все совпадения внутри каждой строки.","difficulty":"applied"},{"type":"single","prompt":"В условии if [ \"$age\" -lt 16 ]; then ... что означает -lt?","options":["Меньше","Меньше или равно","Больше","Строки совпадают"],"answer":[0],"explanation":"-lt — less than, строгое числовое сравнение.","difficulty":"basic"},{"type":"single","prompt":"Выполнены false, затем echo ok, затем echo $?. Чей статус показывается?","options":["false","echo ok","Всего скрипта заранее","Первого аргумента"],"answer":[1],"explanation":"$? обновляется после каждой команды; успешный echo заменил статус false.","difficulty":"challenge"}],"sources":[{"kind":"lab","title":"NDG Linux Essentials - Lab 11_ Basic Scripting.txt","url":"https://drive.google.com/file/d/1L_46DJQxlCkCAlgA7baxRM7Qv73r8wcs/view?usp=drivesdk"},{"kind":"chapter","title":"NDG Linux Essentials - Chapter 11 - Basic Scripting.txt","url":"https://drive.google.com/file/d/1RK3VgIx7u_1XT95r-PN9UlmKK6zrOXoz/view?usp=drivesdk"}]},{"id":12,"title":"Аппаратное обеспечение","en":"Understanding Computer Hardware","intro":"Раздел связывает физические компоненты компьютера с тем, как Linux показывает их пользователю. Нужно различать вычисление, память, постоянное хранение и подключение устройств, а затем выбрать подходящую диагностическую команду.","sections":[{"title":"Плата, процессор и архитектура","body":"Материнская плата соединяет CPU, RAM и устройства. CPU выполняет инструкции. Несколько процессоров — multiprocessor; несколько ядер в одном чипе — multicore. В обозначениях курса x86 относится к 32-битной архитектуре, x86_64 — к 64-битной. 64-битные процессоры семейства x86_64 поддерживают также совместимый 32-битный режим; поддержка приложений зависит и от ОС. arch показывает архитектуру, lscpu — подробности CPU, /proc/cpuinfo — характеристики и флаги."},{"title":"RAM и swap","body":"RAM хранит работающие программы и данные; после выключения её содержимое не сохраняется. Swap — область диска для временного размещения страниц памяти. Она помогает при нехватке RAM, но не заменяет её по скорости. 32-битное адресное пространство содержит 2^32 адресов, то есть 4 GiB при байтовой адресации; реальные возможности платформы зависят от архитектурных расширений. free -m и free -g показывают память в соответствующих масштабах, включая swap."},{"title":"Шины и периферия","body":"Шина связывает компоненты. PCI/PCIe применяются для внутренних контроллеров и плат; USB — для множества внешних устройств. lspci перечисляет PCI-устройства, lspci -k показывает связанные драйверы, lsusb перечисляет USB. Hot-plug означает подключение при работающей системе; cold-plug требует выключения. Для накопителя hot-plug не отменяет корректное размонтирование файловой системы."},{"title":"Диски, разделы и устройства","body":"HDD использует вращающиеся пластины, SSD — память без движущихся частей. SSD обычно быстрее и тише; выбор ёмкости и стоимости зависит от модели. Раздел — логическая часть накопителя. MBR имеет ограничения числа разделов и адресуемого объёма; GPT снимает ключевые ограничения MBR. В курсе рассматриваются fdisk/cfdisk/sfdisk и gdisk/cgdisk/sgdisk, а также parted и gparted. fdisk -l только перечисляет таблицы разделов. Файлы устройств находятся в /dev: в схеме sd* /dev/sda — диск, /dev/sda1 — его раздел; /dev/sdb2 — второй раздел второго диска."},{"title":"Оптика, драйверы и модули","body":"CD, DVD и Blu-ray — оптические съёмные носители; конкретный привод и диск определяют возможность записи. Автоматические точки монтирования часто находятся в /media, временные ручные — в /mnt. umount отключает файловую систему от дерева каталогов. Драйвер обеспечивает взаимодействие ОС с устройством: он может быть встроен в ядро или загружен модулем. lsmod показывает загруженные модули, их размер и зависимости. Совместимость оборудования зависит от наличия поддержки в системе."},{"title":"Видео и питание","body":"Видеоконтроллер формирует изображение для монитора; поддерживаемый режим зависит от обоих устройств и драйвера. В курсе названы VGA, DVI, HDMI, DisplayPort и Mini DisplayPort; VGA передаёт аналоговый видеосигнал. Блок питания преобразует переменный ток в постоянный нужных напряжений. Он влияет на надёжность всей системы; аккумулятор ноутбука позволяет пережить краткое исчезновение внешнего питания."}],"commands":[{"cmd":"lscpu","description":"Архитектура, режимы, ядра и характеристики CPU."},{"cmd":"head -n 20 /proc/cpuinfo","description":"Начало подробной информации о процессоре."},{"cmd":"free -m","description":"Использование RAM и swap."},{"cmd":"lspci -k","description":"PCI-устройства и драйверы ядра."},{"cmd":"lsusb","description":"Подключённые USB-устройства."},{"cmd":"lsmod","description":"Загруженные модули."},{"cmd":"sudo fdisk -l","description":"Просмотр дисков и разделов без интерактивного изменения."}],"lab":[{"task":"Сопоставьте архитектуру и режимы работы CPU двумя командами.","answer":"arch\nlscpu","explanation":"Первая даёт краткое имя, вторая позволяет отличить текущую архитектуру от поддерживаемых режимов."},{"task":"Проверьте RAM и swap, затем найдите устройства PCI, USB и загруженные драйверы.","answer":"free -m\nlspci -k\nlsusb\nlsmod","explanation":"Это разные уровни: ресурсы памяти, шины устройств и программные модули."},{"task":"Выведите таблицы разделов без запуска редактирования.","answer":"sudo fdisk -l","explanation":"Ключ -l перечисляет сведения и завершает команду; номера устройств зависят от компьютера."}],"pitfalls":["Наличие устройства в lspci не доказывает, что все его функции поддерживаются драйвером.","Swap находится на накопителе, а не добавляет физические модули RAM.","Номер /dev/sda1 относится к разделу; /dev/sda — ко всему устройству.","В виртуальной машине часть оборудования представлена виртуальными устройствами и вывод отличается от учебного примера."],"questions":[{"type":"single","prompt":"Какая часть компьютера непосредственно выполняет инструкции программы?","options":["RAM","CPU","Блок питания","Оптический диск"],"answer":[1],"explanation":"Процессор выполняет код; RAM хранит используемые данные и инструкции.","difficulty":"basic"},{"type":"single","prompt":"Четыре вычислительных ядра расположены в одном процессорном чипе. Как это называется?","options":["Multicore","Четыре отдельных диска","Hot-plug","Swap"],"answer":[0],"explanation":"Multicore — несколько ядер внутри одного процессора.","difficulty":"basic"},{"type":"single","prompt":"Как быстро узнать архитектуру текущей системы?","options":["arch","lsusb","who","route"],"answer":[0],"explanation":"arch выводит название аппаратной архитектуры.","difficulty":"basic"},{"type":"single","prompt":"Что означает x86_64 в контексте курса?","options":["64 процессора","64-битная архитектура семейства x86","64 GB установленной RAM","Имя файловой системы"],"answer":[1],"explanation":"Число относится к разрядности архитектуры, не к количеству устройств.","difficulty":"applied"},{"type":"single","prompt":"Какая команда показывает и архитектуру, и сведения о ядрах CPU?","options":["lscpu","ls -cpu","free -c","uname --ram"],"answer":[0],"explanation":"lscpu агрегирует сведения о процессоре.","difficulty":"applied"},{"type":"text","prompt":"Какой файл /proc содержит подробности и flags процессора?","answer":["/proc/cpuinfo"],"explanation":"Флаги перечисляют поддерживаемые возможности CPU.","difficulty":"basic"},{"type":"single","prompt":"Какой ресурс обычно теряет содержимое после выключения питания?","options":["HDD","SSD","RAM","DVD-ROM"],"answer":[2],"explanation":"Оперативная память энергозависима.","difficulty":"basic"},{"type":"single","prompt":"Система переносит редко используемые страницы памяти на диск. Как называется используемая область?","options":["Swap","PCI","ROM","DNS"],"answer":[0],"explanation":"Swap служит дисковым дополнением механизма управления памятью.","difficulty":"applied"},{"type":"single","prompt":"Что показывает free -m?","options":["Только свободное место HDD","RAM и swap в масштабе MiB","Список USB-накопителей","Температуру платы"],"answer":[1],"explanation":"free относится к памяти; -m меняет единицы вывода.","difficulty":"applied"},{"type":"single","prompt":"Сколько байтовых адресов содержит 32-битное адресное пространство?","options":["2^16","2^32","32 миллиона","64 миллиарда"],"answer":[1],"explanation":"32 бита дают 2^32 комбинаций, около 4 GiB байтовых адресов.","difficulty":"challenge"},{"type":"single","prompt":"Как проверить обнаружение внутреннего Ethernet-контроллера на PCI?","options":["lsusb","lspci","free","passwd"],"answer":[1],"explanation":"Контроллер на PCI перечисляется lspci.","difficulty":"applied"},{"type":"single","prompt":"Нужны имя PCI-устройства и используемый kernel driver. Что выбрать?","options":["lspci -k","lscpu -k","lsmod -p","lsusb -d"],"answer":[0],"explanation":"-k у lspci добавляет информацию о драйвере и модулях.","difficulty":"applied"},{"type":"single","prompt":"Подключена USB-мышь. Какой командой искать её в списке устройств?","options":["lsusb","fdisk -l","arch","top"],"answer":[0],"explanation":"lsusb показывает устройства шины USB.","difficulty":"applied"},{"type":"single","prompt":"What is hot-plug?","options":["Подключение при работающей системе","Перегрев процессора","Ускоренное форматирование","Подключение только после выключения"],"answer":[0],"explanation":"Hot-plug противопоставляется cold-plug.","difficulty":"basic"},{"type":"single","prompt":"Почему USB-диск всё же надо размонтировать перед извлечением?","options":["USB не поддерживает hot-plug","Могут оставаться несохранённые записи файловой системы","Иначе изменится CPU","Это обязательно удаляет файлы"],"answer":[1],"explanation":"Физическая поддержка подключения не гарантирует завершение записи данных.","difficulty":"applied"},{"type":"single","prompt":"Что обозначает /dev/sdb2 в схеме именования курса?","options":["Второй раздел второго sd-диска","Второй диск без разделов","Второй USB-порт","Вторая версия драйвера"],"answer":[0],"explanation":"b обозначает второй диск, 2 — номер раздела.","difficulty":"applied"},{"type":"single","prompt":"Чем SSD конструктивно отличается от обычного HDD?","options":["Имеет больше вращающихся пластин","Хранит данные без движущихся механических частей","Работает только через USB","Не сохраняет данные без питания"],"answer":[1],"explanation":"SSD использует энергонезависимую память вместо вращающихся пластин.","difficulty":"applied"},{"type":"multi","prompt":"Выберите 2 свойства GPT в сравнении с традиционной MBR-разметкой из курса.","options":["Поддержка больших дисков за пределами типичного ограничения MBR","Более гибкое число разделов","Обязательное наличие вращающихся пластин","Невозможность использовать Linux"],"answer":[0,1],"explanation":"GPT расширяет возможности разметки; тип накопителя не определяет формат таблицы разделов.","difficulty":"applied"},{"type":"single","prompt":"Нужно только посмотреть разделы. Какая команда соответствует лабораторной?","options":["fdisk -l","fdisk --delete-all","mkfs /dev/sda","rm /dev/sda"],"answer":[0],"explanation":"-l перечисляет таблицы и завершает команду.","difficulty":"applied"},{"type":"single","prompt":"Что перечисляет lsmod?","options":["Все доступные пакеты драйверов","Только USB-устройства","Загруженные модули ядра","Разделы диска"],"answer":[2],"explanation":"Загруженный модуль — программный компонент ядра, а не само устройство.","difficulty":"applied"},{"type":"single","prompt":"Какой каталог обычно служит местом автоматического монтирования съёмных носителей?","options":["/etc","/media","/bin","/proc"],"answer":[1],"explanation":"В FHS /media предназначен для точек монтирования съёмных носителей.","difficulty":"applied"},{"type":"single","prompt":"Какова основная функция блока питания?","options":["Преобразовать переменный ток в постоянный нужных напряжений","Выдавать IP-адреса","Хранить процессы","Отображать графику"],"answer":[0],"explanation":"Компонентам требуются постоянные напряжения питания.","difficulty":"basic"},{"type":"single","prompt":"Какой из перечисленных видеоинтерфейсов традиционно аналоговый?","options":["HDMI","DisplayPort","VGA","Mini DisplayPort"],"answer":[2],"explanation":"VGA — аналоговый интерфейс, в отличие от перечисленных цифровых.","difficulty":"applied"},{"type":"single","prompt":"Устройство видно в списке шины, но часть функций не работает. Какое объяснение наиболее вероятно?","options":["Устройство автоматически стало разделом","Не хватает подходящего драйвера или его возможностей","Нужно изменить имя пользователя","Необходимо удалить swap"],"answer":[1],"explanation":"Обнаружение оборудования и поддержка его функций драйвером — разные вещи.","difficulty":"applied"}],"sources":[{"kind":"lab","title":"NDG Linux Essentials - Lab 12_ Understanding Computer Hardware.txt","url":"https://drive.google.com/file/d/1ZnlXt2k5zx5o-pGuosfPD-xpXnDTpfnU/view?usp=drivesdk"},{"kind":"chapter","title":"NDG Linux Essentials - Chapter 12 - Understanding Computer Hardware.txt","url":"https://drive.google.com/file/d/1jA993zOCGh1VFz72JtP3jubQnwUMhm7u/view?usp=drivesdk"}]},{"id":13,"title":"Процессы, память и каталоги","en":"Where Data is Stored","intro":"В Linux полезно отличать данные на диске от текущего состояния ядра. Этот раздел объединяет наблюдение за процессами, управление заданиями, журналы и расположение системных файлов.","sections":[{"title":"Ядро, /proc и /sys","body":"Ядро управляет процессами, памятью, файловыми системами, сетью и драйверами; приложения обращаются к нему через системные вызовы. /proc и /sys — виртуальные файловые системы, данные которых формирует ядро. /proc/PID описывает процесс с данным идентификатором; /proc/1 — первый процесс. /proc/cmdline хранит параметры загрузки ядра, /proc/meminfo — память, /proc/modules — модули, /proc/cpuinfo — CPU. /dev содержит файлы устройств. Значения /proc/sys могут менять поведение работающего ядра; для сохранения настроек после перезагрузки применяют конфигурацию sysctl."},{"title":"Процессы и наблюдение","body":"Процесс — выполняющийся экземпляр программы. PID идентифицирует его, PPID — родителя. Первый процесс имеет PID 1 (init или systemd). pstree и ps --forest отображают связи. ps даёт снимок; ps -e, ps -ef или ps aux расширяют выборку до системы, ps -u user фильтрует пользователя, ps -o выбирает столбцы, --sort задаёт сортировку. top обновляет список и показывает CPU, память и load average; q выходит, k посылает сигнал, r меняет nice. Больший nice обычно означает меньший приоритет."},{"title":"Задания и сигналы","body":"& запускает команду в фоне, jobs показывает задания текущего shell. Номер задания вроде %1 локален для shell; PID относится к процессу. fg %1 возвращает задание на передний план, Ctrl+Z приостанавливает, bg %1 продолжает в фоне. Ctrl+C обычно прерывает foreground-команду. kill PID по умолчанию посылает SIGTERM (15), позволяющий завершиться корректно; SIGKILL (9) нельзя обработать или игнорировать. killall и pkill выбирают процессы по имени. /dev/null принимает и отбрасывает записанные данные."},{"title":"Память и нагрузка","body":"Ядро отделяет защищённое kernel space от user space; виртуальные адреса позволяют процессам иметь собственное представление памяти. free показывает RAM, кеши и swap; -s 10 повторяет вывод каждые 10 секунд. Кеш может быть освобождён под приложения, поэтому малая free сама по себе не доказывает дефицит памяти. Load average за 1, 5 и 15 минут описывает среднее число активных/ожидающих задач, а не процент CPU; интерпретация зависит от числа ядер и ожидания ввода-вывода."},{"title":"Журналы и сообщения ядра","body":"Журналы помогают искать ошибки и попытки входа. Основное место — /var/log. В зависимости от системы встречаются syslog/messages, auth.log/secure, cron, maillog, boot.log и Xorg.0.log. syslogd, klogd, rsyslogd и journald представляют разные механизмы журналирования. journalctl читает журнал systemd, dmesg — кольцевой буфер ядра. Ротация переименовывает/архивирует старый лог и начинает новый. Не все логи текстовые: wtmp читают через last, btmp через lastb; file помогает определить тип."},{"title":"FHS и расположение данных","body":"FHS описывает стандартную организацию дерева. / — его корень, /boot — загрузка, /etc — системная конфигурация, /home — домашние папки, /root — дом root, /bin и /sbin — основные команды, /lib и /lib64 — библиотеки. /usr — программы и общие данные, /usr/local — локально установленное ПО, /opt — дополнительные приложения, /srv — данные служб. /media и /mnt — точки монтирования. /var содержит меняющиеся данные: log, cache, spool, lib; /tmp — временные файлы, /var/tmp — временные файлы, сохраняемые между перезагрузками. Реальные дистрибутивы могут объединять некоторые каталоги ссылками."},{"title":"Пакеты и библиотеки","body":"Файлы одной программы распределяются между bin, lib, share, etc и var. dpkg -L package и rpm -ql package показывают установленные файлы пакета. Общие библиотеки часто имеют расширение .so; могут сосуществовать версии для разных архитектур. Документация находится в /usr/share/doc, man и info, персональная конфигурация — часто в скрытых файлах домашнего каталога. FHS также различает изменяемые/статические и разделяемые/локальные данные. Разрастание /var может заполнить общий корневой раздел."}],"commands":[{"cmd":"ps -eo pid,ppid,user,%mem,cmd --sort=-%mem","description":"Снимок всех процессов, сначала наиболее потребляющие память."},{"cmd":"top","description":"Динамическое наблюдение."},{"cmd":"sleep 60 &","description":"Учебное фоновое задание."},{"cmd":"dmesg | grep -i usb","description":"Найти сообщения ядра о USB."},{"cmd":"tail -n 5 /var/log/auth.log","description":"Последние события аутентификации на системах с этим логом."}],"lab":[{"task":"Посмотрите параметры загрузки и сведения о процессе 1.","answer":"cat /proc/cmdline\nps -p 1\ncat /proc/1/cmdline","explanation":"Общий cmdline относится к ядру, вложенный в /proc/1 — к первому процессу."},{"task":"Запустите учебный sleep, верните его на передний план, приостановите и продолжите в фоне.","answer":"sleep 60 &\njobs\nfg %1\nCtrl+Z\nbg %1","explanation":"%1 подходит, если созданное задание получило номер 1; фактический номер показывает jobs."},{"task":"Завершите своё учебное фоновое задание обычным сигналом и проверьте список.","answer":"kill %1\njobs","explanation":"Обычный kill посылает SIGTERM; номер нужно брать из своего shell."},{"task":"В top найдите процесс, использующий больше всего CPU, затем выйдите.","answer":"top → проверить %CPU и COMMAND → q","explanation":"Это наблюдение в реальном времени; PID и значения не обязаны совпадать с лабораторным скриншотом."},{"task":"Сравните снимок процессов и журнал входов.","answer":"ps -e\nls /var/log\nlast","explanation":"Процессы показывают текущее состояние, журнал — зарегистрированную историю."}],"pitfalls":["Ctrl+Z приостанавливает процесс, а не завершает его.","SIGKILL не позволяет программе выполнить обычную очистку.","PID и номер задания не одно и то же.","Load average 1 не означает универсальные 100% CPU.","ps -ef | grep name может показать также сам процесс grep."],"questions":[{"type":"single","prompt":"Где искать сведения о процессе с PID 742?","options":["/etc/742","/proc/742","/var/742","/dev/cpu742"],"answer":[1],"explanation":"Числовые каталоги /proc соответствуют PID.","difficulty":"basic"},{"type":"text","prompt":"Какой PID имеет первый пользовательский процесс после загрузки ядра?","answer":["1"],"explanation":"Init или systemd выполняет роль процесса 1.","difficulty":"basic"},{"type":"single","prompt":"Что обозначает PPID?","options":["Приоритет процесса","PID родительского процесса","Процент памяти","Номер порта"],"answer":[1],"explanation":"PPID показывает родителя, создавшего процесс.","difficulty":"basic"},{"type":"single","prompt":"Чем top отличается от обычного ps?","options":["top только редактирует процессы","top обновляет отображение, ps даёт снимок","ps не показывает PID","top работает только с дисками"],"answer":[1],"explanation":"top предназначен для продолжающегося наблюдения.","difficulty":"applied"},{"type":"single","prompt":"Как получить список всех процессов с подробными сведениями?","options":["ps -ef","ps -home","jobs -all-users","who -p"],"answer":[0],"explanation":"-e выбирает все процессы, -f задаёт полный формат.","difficulty":"applied"},{"type":"single","prompt":"Что покажет pstree?","options":["Дерево каталогов","Дерево отношений родитель–потомок","Только потоки ошибок","Размер swap"],"answer":[1],"explanation":"pstree визуализирует иерархию процессов.","difficulty":"applied"},{"type":"single","prompt":"Как запустить sleep 60, сохранив возможность вводить другие команды?","options":["sleep 60 &","sleep 60 >","sleep 60 <","sleep 60 !"],"answer":[0],"explanation":"& помещает команду в фон.","difficulty":"applied"},{"type":"single","prompt":"Shell вывел [2] 918. Что означают числа?","options":["PID 2 и GID 918","Задание 2 и PID 918","Два потока и 918 байтов","Порт 2 и адрес 918"],"answer":[1],"explanation":"Число в скобках — job ID текущего shell, второе — PID.","difficulty":"applied"},{"type":"single","prompt":"Нужно приостановить foreground-процесс без завершения. Что нажать?","options":["Ctrl+C","Ctrl+Z","Ctrl+D","Ctrl+L"],"answer":[1],"explanation":"Ctrl+Z обычно посылает сигнал остановки задания.","difficulty":"applied"},{"type":"single","prompt":"Как продолжить приостановленное задание 2 в фоне?","options":["fg %2","bg %2","kill -9 2","jobs 2"],"answer":[1],"explanation":"bg продолжает stopped-задание без захвата терминала.","difficulty":"applied"},{"type":"text","prompt":"Какой номер у сигнала SIGTERM?","answer":["15"],"explanation":"Это сигнал по умолчанию для обычного kill.","difficulty":"basic"},{"type":"single","prompt":"Почему SIGTERM обычно предпочтительнее SIGKILL для штатной остановки?","options":["SIGTERM повышает приоритет","Программа может обработать его и освободить ресурсы","SIGKILL всегда сохраняет данные","SIGTERM работает только с файлами"],"answer":[1],"explanation":"SIGKILL не может быть перехвачен и не даёт выполнить обработчик завершения.","difficulty":"applied"},{"type":"single","prompt":"Что произойдёт с stdout при перенаправлении > /dev/null?","options":["Он попадёт в журнал","Он будет отброшен","Он станет stderr","Команда обязательно остановится"],"answer":[1],"explanation":"/dev/null принимает данные без сохранения.","difficulty":"applied"},{"type":"single","prompt":"Нужно видеть самые большие значения %mem первыми. Какой ключ сортировки ps подходит?","options":["--sort=%mem","--sort=-%mem","--sort=+%mem","--sort=pid"],"answer":[1],"explanation":"Минус перед именем поля задаёт убывание.","difficulty":"applied"},{"type":"single","prompt":"Nice процесса увеличили с 0 до 10. Как обычно изменился его приоритет CPU?","options":["Повысился","Понизился","Процесс стал root","Изменился PID"],"answer":[1],"explanation":"Более «уступчивый» процесс имеет больший nice и меньший приоритет.","difficulty":"applied"},{"type":"single","prompt":"Что означают три числа load average?","options":["RAM, swap, диск","Средняя нагрузка за 1, 5, 15 минут","Проценты трёх пользователей","Три последних PID"],"answer":[1],"explanation":"Эти временные интервалы используются top, uptime и /proc/loadavg.","difficulty":"applied"},{"type":"single","prompt":"Какое утверждение про /proc верно?","options":["Это только архив завершённых процессов","Это виртуальная файловая система с текущими данными ядра","Любой файл /proc можно сохранить текстовым редактором","Она хранится только на USB"],"answer":[1],"explanation":"Содержимое предоставляет ядро; обычный размер на диске не описывает эти псевдофайлы.","difficulty":"applied"},{"type":"single","prompt":"Какой инструмент специально читает журнал systemd?","options":["journalctl","catctl","sysctl","logmod"],"answer":[0],"explanation":"journalctl интерпретирует журнал journald.","difficulty":"basic"},{"type":"single","prompt":"Где обычно находятся системные журналы?","options":["/var/log","/usr/bin","/home/bin","/etc/skel"],"answer":[0],"explanation":"/var/log — стандартное место логов.","difficulty":"basic"},{"type":"multi","prompt":"Выберите 2 верные пары каталог → назначение.","options":["/etc → системная конфигурация","/usr/local → локально установленное ПО","/proc → архив ISO-образов","/boot → личные документы пользователей"],"answer":[0,1],"explanation":"FHS разделяет конфигурацию, программы, загрузочные и текущие системные данные.","difficulty":"applied"},{"type":"single","prompt":"Как найти сообщения ядра с USB без учёта регистра?","options":["dmesg | grep -i usb","last | grep -x usb","free -m usb","lsmod > usb"],"answer":[0],"explanation":"dmesg читает кольцевой буфер ядра, grep фильтрует его строки.","difficulty":"applied"},{"type":"single","prompt":"Что делает ротация логов?","options":["Удаляет все события каждый раз","Перемещает старые записи в отдельные файлы и продолжает новый лог","Превращает PID в UID","Выключает журналирование"],"answer":[1],"explanation":"История отделяется от текущего файла и может сжиматься.","difficulty":"applied"},{"type":"single","prompt":"Which path is the root user's usual home directory?","options":["/","/root","/home","/usr/root"],"answer":[1],"explanation":"Корень дерева / и домашний каталог администратора /root различны.","difficulty":"applied"},{"type":"single","prompt":"Как вывести файлы установленного Debian-пакета nano?","options":["dpkg -L nano","rpm -install nano","cat /proc/nano","nano -files"],"answer":[0],"explanation":"dpkg -L перечисляет файлы установленного пакета.","difficulty":"applied"},{"type":"single","prompt":"Какая команда показывает RAM повторно каждые 10 секунд?","options":["free -s 10","free -n 10","top -r 10","ps --memory=10"],"answer":[0],"explanation":"-s у free задаёт интервал обновления.","difficulty":"applied"},{"type":"single","prompt":"Что означает расширение .so у многих библиотек?","options":["System owner","Shared object","Socket only","Sorted output"],"answer":[1],"explanation":"Разделяемая библиотека содержит код, используемый несколькими программами.","difficulty":"basic"}],"sources":[{"kind":"lab","title":"NDG Linux Essentials - Lab 13_ Where Data is Stored.txt","url":"https://drive.google.com/file/d/1_5Yix7ppNw1JMCfP62eVPCHq3MEyJJU1/view?usp=drivesdk"},{"kind":"chapter","title":"NDG Linux Essentials - Chapter 13 - Where Data is Stored.txt","url":"https://drive.google.com/file/d/15HSqZP1CLUeNoE6ezvudLgCQrKazv-zJ/view?usp=drivesdk"}]},{"id":14,"title":"Сетевые настройки","en":"Network Configuration","intro":"Сеть нужно проверять слоями: интерфейс и адрес, маршрут, разрешение имён, затем доступность конкретной службы. Успешный ping и открытый сервис — разные проверки.","sections":[{"title":"Основные термины","body":"Host — устройство в сети; network — набор взаимодействующих узлов; server предоставляет service, client обращается к нему. Router/gateway соединяет сети. Данные передаются пакетами по правилам протоколов; TCP/IP — семейство протоколов. Ethernet обычно описывает проводную сеть, Wi-Fi — беспроводную. IP адресует интерфейс, маска определяет сетевую часть адреса. Hostname — понятное человеку имя; URL включает также протокол и может содержать путь."},{"title":"IPv4, IPv6 и назначение адресов","body":"IPv4 использует 32 бита: четыре десятичных числа 0–255, разделённых точками. IPv6 использует 128 бит, шестнадцатеричные группы с двоеточиями; :: может один раз сократить последовательность нулевых групп. Loopback: 127.0.0.1 и ::1, интерфейс lo. DHCP автоматически предоставляет адрес и другие параметры; статическая настройка задаётся вручную. NAT позволяет нескольким внутренним узлам пользоваться внешним адресом шлюза. Переход между IPv4 и IPv6 требует совместимости устройств и программ."},{"title":"Конфигурационные файлы курса","body":"Пути настройки интерфейсов зависят от дистрибутива. В старом CentOS-примере курса используется /etc/sysconfig/network-scripts/ifcfg-eth0: IPADDR, PREFIX, GATEWAY и DNS1 для статических параметров, BOOTPROTO=dhcp для DHCP. Для IPv6 показаны IPV6INIT, IPV6ADDR, IPV6_DEFAULTGW и DHCPV6C. ifdown/ifup применяются к одному интерфейсу, перезапуск всей сети затрагивает все подключения. Эти примеры не универсальны для любого Linux."},{"title":"Разрешение имён","body":"/etc/hosts содержит локальные соответствия адресов и имён; /etc/resolv.conf — nameserver и параметры DNS, включая search/domain; /etc/nsswitch.conf определяет порядок источников. hosts: files dns означает сначала локальный hosts, потом DNS при отсутствии результата. Успешное локальное совпадение обычно не заменяется DNS лишь потому, что адрес оказался неверным. dig и host запрашивают DNS; dig -x делает обратный поиск по IP, host -t выбирает тип записи. FQDN включает имя узла и домен."},{"title":"Диагностика интерфейса и маршрута","body":"ifconfig показывает интерфейсы, ip addr show — современный аналог. route/route -n и ip route show показывают маршруты; default используется для адресов без более конкретного маршрута. ping -c 4 host ограничивает число ICMP-запросов; без ограничения ping в Linux обычно продолжает работу до Ctrl+C. Отсутствие ответа может означать фильтрацию ICMP. Если по IP работает, а по имени нет, нужно проверить разрешение имён."},{"title":"Соединения, порты и SSH","body":"netstat -tln и ss -tln показывают слушающие TCP-сокеты численно: -t TCP, -l listening, -n без преобразования имён. netstat -r показывает маршруты, -i статистику интерфейсов; ss -s — сводку сокетов. В ss Local Address — локальный адрес/порт, Peer Address — удалённый, Recv-Q/Send-Q — очереди данных. SSH обычно использует TCP 22; /etc/services связывает имена служб с номерами портов. ssh user@host открывает защищённый удалённый сеанс, exit возвращает к локальному. Отпечаток ключа сервера проверяют при первом подключении; known_hosts хранит доверенные ключи. Неожиданная смена ключа требует проверки причины."}],"commands":[{"cmd":"ip addr show","description":"Адреса интерфейсов."},{"cmd":"ip route show","description":"Таблица маршрутизации."},{"cmd":"ping -c 4 localhost","description":"Четыре проверки loopback."},{"cmd":"dig example.com","description":"DNS-запрос имени."},{"cmd":"dig -x 192.168.1.2","description":"Обратный DNS-запрос."},{"cmd":"ss -tln","description":"Слушающие TCP-порты в числовом виде."},{"cmd":"ssh student@host","description":"Вход на удалённый хост как student."}],"lab":[{"task":"Найдите свои IP-адреса и маршрут по умолчанию.","answer":"ip addr show\nip route show","explanation":"Адрес интерфейса и адрес шлюза выполняют разные роли; конкретные числа зависят от среды."},{"task":"Проверьте локальное соответствие localhost и выполните ровно четыре ping-запроса.","answer":"grep '127.0.0.1' /etc/hosts\nping -c 4 localhost","explanation":"Тест loopback проверяет локальный сетевой стек, но не доказывает выход в Интернет."},{"task":"Посмотрите DNS-сервер и выполните прямой и обратный запросы к учебному серверу.","answer":"cat /etc/resolv.conf\ndig cserver.example.com\ndig -x 192.168.1.2","explanation":"Адреса из лаборатории работают только в её настроенной сети; ANSWER содержит результат, SERVER — ответивший DNS."},{"task":"Проверьте, слушает ли SSH TCP-порт 22.","answer":"ss -tln","explanation":"Найдите :22 среди Local Address. Слушающий сокет показывает локальную службу; доступ извне дополнительно зависит от сети и фильтров."}],"pitfalls":["ping localhost не проверяет доступ в Интернет.","Отказ ping не доказывает, что веб-сервис или SSH недоступен.","dig проверяет DNS, а системное разрешение имени может использовать /etc/hosts по NSS.","Слушающий порт на 127.0.0.1 не означает доступность службы с другого компьютера.","Предупреждение SSH о смене ключа не следует автоматически игнорировать."],"questions":[{"type":"single","prompt":"Как называется узел, предоставляющий веб-страницы другим устройствам?","options":["Client","Server","Mask","Packet"],"answer":[1],"explanation":"Сервер предоставляет услугу клиентам.","difficulty":"basic"},{"type":"single","prompt":"Что соединяет разные IP-сети?","options":["Текстовый редактор","Router/gateway","Имя файла","RAM"],"answer":[1],"explanation":"Маршрутизатор пересылает пакеты между сетями.","difficulty":"basic"},{"type":"text","prompt":"Сколько бит в IPv6-адресе?","answer":["128"],"explanation":"IPv4 содержит 32 бита, IPv6 — 128.","difficulty":"basic"},{"type":"single","prompt":"Какой адрес корректен по формату IPv4?","options":["192.168.1.25","192.168.400.1","192:168:1:25","192.168.1"],"answer":[0],"explanation":"Нужны четыре октета от 0 до 255.","difficulty":"applied"},{"type":"single","prompt":"Какую задачу решает DHCP?","options":["Шифрует файлы","Автоматически выдаёт параметры сети","Удаляет DNS-записи","Перечисляет процессы"],"answer":[1],"explanation":"DHCP может передать IP, маску, шлюз и DNS.","difficulty":"basic"},{"type":"single","prompt":"Какую задачу решает DNS?","options":["Связывает доменные имена и сетевые адреса","Назначает права rwx","Делит диск на разделы","Измеряет RAM"],"answer":[0],"explanation":"DNS хранит записи имён и связанных данных.","difficulty":"basic"},{"type":"single","prompt":"В каком файле искать строку nameserver?","options":["/etc/passwd","/etc/resolv.conf","/etc/services","/etc/skel"],"answer":[1],"explanation":"resolv.conf задаёт DNS-серверы и параметры резолвера.","difficulty":"applied"},{"type":"single","prompt":"Что означает hosts: files dns в /etc/nsswitch.conf?","options":["Всегда использовать оба ответа одновременно","Сначала /etc/hosts, потом DNS при необходимости","Только сетевые файлы","Сначала DNS, затем /etc/hosts"],"answer":[1],"explanation":"Порядок источников имеет значение.","difficulty":"applied"},{"type":"single","prompt":"Имя найдено в /etc/hosts, но адрес ошибочен; NSS использует files dns. Что обычно происходит?","options":["DNS обязательно исправляет ошибку","Локальное совпадение используется без перехода к DNS","Система удаляет строку","Назначается случайный адрес"],"answer":[1],"explanation":"NSS видит успешное разрешение имени, даже если адрес не ведёт к нужной машине.","difficulty":"challenge"},{"type":"single","prompt":"Which command is a modern replacement for viewing ifconfig address information?","options":["ip addr show","ip user show","ip port remove","ip disk show"],"answer":[0],"explanation":"ip addr show отображает адреса интерфейсов.","difficulty":"applied"},{"type":"single","prompt":"Как посмотреть таблицу маршрутизации?","options":["ip route show","ip passwd show","dig -r","who -route"],"answer":[0],"explanation":"Объект route команды ip отвечает за маршруты.","difficulty":"applied"},{"type":"single","prompt":"Для чего используется маршрут default?","options":["Только для localhost","Для назначения без более подходящего конкретного маршрута","Для любого файла /etc","Для каждого пакета вне зависимости от таблицы"],"answer":[1],"explanation":"Выбирается наиболее специфичный подходящий маршрут; default — запасной.","difficulty":"applied"},{"type":"single","prompt":"Что проверяет ping -c 4 localhost?","options":["Четыре запроса к локальному узлу","Четыре DNS-сервера Интернета","Первые четыре порта SSH","Скорость диска за 4 секунды"],"answer":[0],"explanation":"-c ограничивает число запросов, localhost указывает на эту машину.","difficulty":"applied"},{"type":"single","prompt":"Ping по IP успешен, а имя не разрешается. Что проверить в первую очередь?","options":["Разметку GPT","DNS/NSS и локальные имена","Права /bin/bash","Число процессорных ядер"],"answer":[1],"explanation":"Сетевой путь к IP работает; проблема вероятнее в превращении имени в адрес.","difficulty":"applied"},{"type":"single","prompt":"Ping не получил ответ. Какой вывод корректен?","options":["Узел точно выключен","ICMP мог быть заблокирован; нужны другие проверки","Все службы точно недоступны","Нужно немедленно менять IP"],"answer":[1],"explanation":"Удалённая система может обслуживать TCP, не отвечая на ICMP.","difficulty":"applied"},{"type":"single","prompt":"Как запросить DNS-имя для IP 192.168.1.2?","options":["dig -x 192.168.1.2","dig -n 192.168.1.2","ping -d 192.168.1.2","route -x 192.168.1.2"],"answer":[0],"explanation":"-x включает обратный запрос, обычно PTR.","difficulty":"applied"},{"type":"single","prompt":"В имени cserver.example.com какая часть обозначает домен в примере курса?","options":["cserver","example.com","com.cserver","192.168.1.2"],"answer":[1],"explanation":"Полное имя сочетает имя узла cserver и домен example.com.","difficulty":"applied"},{"type":"single","prompt":"Что означает -n в netstat -tln?","options":["Новые соединения","Числовые адреса и порты без разрешения имён","Только IPv6","Отключение сети"],"answer":[1],"explanation":"-n позволяет увидеть 22 вместо имени ssh.","difficulty":"applied"},{"type":"multi","prompt":"Выберите 2 значения ключей netstat -tln.","options":["-t: TCP","-l: listening","-t: время входа","-l: локальные файлы"],"answer":[0,1],"explanation":"Команда ограничивает вывод слушающими TCP-сокетами.","difficulty":"applied"},{"type":"text","prompt":"Какой TCP-порт обычно использует SSH?","answer":["22"],"explanation":"Стандартная служба SSH слушает порт 22; администратор может его изменить.","difficulty":"basic"},{"type":"single","prompt":"Как подключиться к host под учётной записью student?","options":["ssh host/student","ssh student@host","su student@host","host ssh student"],"answer":[1],"explanation":"Синтаксис user@host задаёт удалённого пользователя.","difficulty":"applied"},{"type":"single","prompt":"SSH предупреждает о неожиданной смене host key. Что сделать?","options":["Сразу удалить весь known_hosts","Проверить, переустанавливался ли сервер и верен ли новый ключ","Отключить проверку навсегда","Передать пароль любому ответившему узлу"],"answer":[1],"explanation":"Причина может быть законной заменой ключа или подменой сервера.","difficulty":"applied"},{"type":"single","prompt":"Какая технология позволяет частным узлам совместно использовать внешний IPv4-адрес шлюза?","options":["NAT","RAM","GECOS","FHS"],"answer":[0],"explanation":"NAT преобразует сетевые адреса при прохождении шлюза.","difficulty":"applied"},{"type":"single","prompt":"В ss что означает Peer Address?","options":["Адрес удалённой стороны соединения","Домашний каталог","Локальный UID","Таблицу разделов"],"answer":[0],"explanation":"Local Address относится к этой машине, Peer — к другой стороне.","difficulty":"applied"},{"type":"single","prompt":"Для чего в /etc/services находятся названия вроде ssh?","options":["Для связи названий служб с портами и протоколами","Для хранения паролей SSH","Для списка текущих пользователей","Для выбора default gateway"],"answer":[0],"explanation":"Файл описывает известные соответствия, но сам не запускает службы.","difficulty":"applied"}],"sources":[{"kind":"lab","title":"NDG Linux Essentials - Lab 14_ Network Configuration.txt","url":"https://drive.google.com/file/d/1rShChsxbrWhGrnua8_bpR0SIsSMT36A0/view?usp=drivesdk"},{"kind":"chapter","title":"NDG Linux Essentials - Chapter 14 - Network Configuration.txt","url":"https://drive.google.com/file/d/1c7mEk-N2fYUfimZ1T54nQeBJAm_4sJqM/view?usp=drivesdk"}]},{"id":15,"title":"Пользователи и безопасность","en":"System and User Security","intro":"Права процессов зависят от учётной записи и групп. Для подготовки нужно уметь читать базы пользователей, различать текущие сеансы и историю входов, а также понимать разницу между su и sudo.","sections":[{"title":"Администратор, su и sudo","body":"UID 0 определяет полномочия root. Обычный пользователь получает только предоставленные права; системные учётные записи используются службами и обычно не предназначены для интерактивного входа. su - user открывает login-shell другого пользователя с его окружением; без имени подразумевается root. Обычному пользователю обычно нужен пароль целевой учётной записи. sudo command запускает разрешённую политикой команду, по умолчанию как root, и обычно запрашивает пароль вызывающего пользователя. Выполнение журналируется. Период повторного запроса пароля зависит от конфигурации, поэтому числа 5 и 15 минут в материалах не универсальны."},{"title":"/etc/passwd","body":"Одна строка соответствует учётной записи; семь полей разделены двоеточиями: имя:x:UID:GID:комментарий:домашний_каталог:shell. x указывает на хранение хеша пароля в shadow. UID и GID используются системой для идентификации; имена — удобное представление. GID здесь задаёт основную группу. /root обычно является домом root; обычный пользователь часто получает /home/name. /usr/sbin/nologin или /bin/false в поле shell ограничивает интерактивный вход."},{"title":"/etc/shadow и сроки","body":"shadow доступен ограниченному кругу процессов и хранит имя, хеш/маркер пароля, день последней смены, min, max, warn, inactive, expire и резервное поле. Даты last change и expire выражаются в днях от 1 января 1970. Min задаёт минимальный интервал между сменами, max — срок действия, warn — число дней предупреждения. Inactive задаёт интервал после истечения пароля до блокировки; expire — отдельную дату окончания действия учётной записи. ! или * не являются обычными паролями и могут запрещать парольную аутентификацию. Хеш — не открытый текст и не обратимо зашифрованный пароль."},{"title":"Системные записи и группы","body":"Службы используют отдельные аккаунты с ограниченными правами; низкие UID часто зарезервированы для них, но точные границы зависят от дистрибутива. /etc/group имеет формат имя:x:GID:список_пользователей. Последнее поле перечисляет дополнительные членства; основная группа берётся из passwd и пользователь не обязан быть продублирован в списке group. /etc/gshadow хранит защищённые сведения групп. Одно имя может существовать одновременно как имя пользователя и группы."},{"title":"Просмотр идентичности","body":"id показывает UID, основную GID и все группы текущего пользователя; id name — сведения указанной учётной записи. id -g выводит основную GID, id -G — все GID. grep '^name:' /etc/passwd ищет локальную запись, getent passwd name обращается к настроенным базам NSS, включая сетевые каталоги. getent group name показывает группу. man 5 passwd описывает формат файла, а не команду смены пароля."},{"title":"Сеансы и история","body":"who показывает текущие зарегистрированные сеансы, терминал, время и источник входа; who -b — время загрузки, who -r — runlevel. w добавляет uptime, нагрузку, idle и текущую команду WHAT. TTY — терминал; pts — псевдотерминал, который может использоваться и локально, и удалённо. last читает историю wtmp, включая завершённые сеансы и перезагрузки; still logged in означает незавершённый зарегистрированный сеанс. Наличие аккаунта не доказывает, что он когда-либо входил."}],"commands":[{"cmd":"su -","description":"Login-shell root, если разрешена такая аутентификация."},{"cmd":"sudo head -n 3 /etc/shadow","description":"Пример привилегированного чтения из лаборатории."},{"cmd":"getent passwd student","description":"Запись пользователя из настроенных источников."},{"cmd":"id student","description":"UID и группы пользователя."},{"cmd":"who","description":"Текущие зарегистрированные входы."},{"cmd":"w","description":"Текущие сеансы и их деятельность."},{"cmd":"last student","description":"Сохранённая история входов пользователя."}],"lab":[{"task":"В учебной VM сравните идентичность до su -, после него и после exit.","answer":"id\nsu -\nid\nexit\nid","explanation":"После входа в административный shell UID должен быть 0; exit возвращает прежний shell."},{"task":"Разберите строку ana:x:1100:1200:Student:/home/ana:/bin/bash.","answer":"Имя ana, UID 1100, основная GID 1200, комментарий Student, дом /home/ana, shell /bin/bash.","explanation":"x — заполнитель для хеша в shadow, а не пароль пользователя."},{"task":"Проверьте текущие сеансы и историю; сравните три команды.","answer":"who\nw\nlast","explanation":"who и w относятся к текущим сеансам, last — к зарегистрированной истории; вывод зависит от среды."},{"task":"Найдите учётную запись через системную базу и прочитайте описание формата.","answer":"getent passwd student\nman 5 passwd","explanation":"getent может учитывать сетевые записи; раздел man 5 описывает формат файла."}],"pitfalls":["sudo обычно спрашивает твой пароль; su — пароль целевого пользователя.","sudo требует разрешения в политике: одного знания пароля недостаточно.","Не путай /etc/passwd с командой passwd.","Отсутствие имени в последнем поле /etc/group не исключает основного членства.","pts само по себе не доказывает удалённый вход."],"questions":[{"type":"text","prompt":"Какой UID определяет административные полномочия root?","answer":["0"],"explanation":"Привилегии связаны с UID 0, а не только со строкой имени root.","difficulty":"basic"},{"type":"single","prompt":"Чей пароль обычно спрашивает sudo у разрешённого обычного пользователя?","options":["Всегда root","Самого вызывающего пользователя","Владельца файла","Любого члена группы"],"answer":[1],"explanation":"В стандартной конфигурации sudo подтверждает личность вызывающего пользователя.","difficulty":"applied"},{"type":"single","prompt":"Обычный пользователь выполняет su - bob. Чей пароль обычно нужен?","options":["Текущего пользователя","bob","Всегда root","Пароль группы bob"],"answer":[1],"explanation":"su аутентифицирует переход к целевой учётной записи.","difficulty":"applied"},{"type":"single","prompt":"Для чего у su используется -?","options":["Для запрета команд","Для login-shell с окружением целевого пользователя","Для просмотра паролей","Для удаления сеанса"],"answer":[1],"explanation":"Login-shell загружает настройки целевого пользователя.","difficulty":"applied"},{"type":"single","prompt":"Как вернуться из shell, запущенного su, к прежнему пользователю?","options":["exit","reboot","userdel","logout --all"],"answer":[0],"explanation":"exit завершает текущий вложенный shell.","difficulty":"basic"},{"type":"single","prompt":"Which file contains general local account records?","options":["/etc/passwd","/etc/services","/etc/resolv.conf","/var/log/wtmp"],"answer":[0],"explanation":"passwd хранит UID, GID, домашний каталог, shell и другие сведения.","difficulty":"basic"},{"type":"single","prompt":"В записи ali:x:1050:2000:Student:/home/ali:/bin/bash чему равна основная GID?","options":["1050","2000","0","Не указана"],"answer":[1],"explanation":"GID находится в четвёртом поле, после UID.","difficulty":"applied"},{"type":"single","prompt":"Что обычно означает x во втором поле /etc/passwd?","options":["Пользователь исполняемый","Хеш хранится в /etc/shadow","Пароль буквально x","Аккаунт удалён"],"answer":[1],"explanation":"Это заполнитель, а не реальный пароль.","difficulty":"applied"},{"type":"text","prompt":"Сколько полей содержит стандартная строка /etc/passwd?","answer":["7"],"explanation":"Поля разделяются двоеточиями: имя, пароль/заполнитель, UID, GID, комментарий, дом, shell.","difficulty":"basic"},{"type":"single","prompt":"Где обычно хранится хеш пароля локального пользователя?","options":["/etc/shadow","/etc/hosts","/usr/bin/passwd","/home/passwords"],"answer":[0],"explanation":"shadow ограничивает доступ к хешам и параметрам сроков.","difficulty":"basic"},{"type":"single","prompt":"В shadow min=5 и max=30. Что это означает?","options":["Пароль содержит 5–30 символов","Между сменами минимум 5 дней, срок действия 30 дней","UID от 5 до 30","Блокировку после 5 ошибок на 30 минут"],"answer":[1],"explanation":"Оба поля описывают время, а не длину или количество попыток.","difficulty":"applied"},{"type":"single","prompt":"Чем expire отличается от max в shadow?","options":["Expire — дата окончания учётной записи, max — срок действия пароля","Это одинаковые поля","Expire задаёт длину пароля","Max задаёт число групп"],"answer":[0],"explanation":"Истечение учётной записи и истечение пароля — отдельные механизмы.","difficulty":"applied"},{"type":"single","prompt":"Что представляет собой поле хеша пароля?","options":["Открытый пароль в другой кодировке","Результат одностороннего преобразования","IP-адрес владельца","Имя shell"],"answer":[1],"explanation":"Хеш проверяет совпадение введённого пароля; это не обратимое шифрование.","difficulty":"applied"},{"type":"single","prompt":"Для чего службам выделяют системные аккаунты?","options":["Чтобы каждая служба была root","Чтобы ограничить доступ нужными ресурсами","Чтобы скрыть все процессы от ps","Чтобы отключить UID"],"answer":[1],"explanation":"Отдельная идентичность ограничивает последствия компрометации службы.","difficulty":"applied"},{"type":"single","prompt":"Какой shell обычно указывает, что аккаунт не предназначен для обычного интерактивного входа?","options":["/bin/bash","/bin/sh","/usr/sbin/nologin","/usr/bin/less"],"answer":[2],"explanation":"nologin отказывает в интерактивном входе.","difficulty":"applied"},{"type":"single","prompt":"В строке research:x:1500:ana,bob что означает 1500?","options":["Пароль","UID ana","GID группы research","Число пользователей"],"answer":[2],"explanation":"Третье поле group — числовой идентификатор группы.","difficulty":"applied"},{"type":"single","prompt":"Имя ana отсутствует в списке research в /etc/group, но её passwd GID равна GID research. Является ли ana членом?","options":["Да, это её основная группа","Нет, требуется дублирование","Только после sudo","Определить невозможно даже с известной GID"],"answer":[0],"explanation":"Основное членство задаётся в passwd; список group прежде всего отражает дополнительные членства.","difficulty":"challenge"},{"type":"single","prompt":"Как показать все GID текущего пользователя?","options":["id -g","id -G","who -G","last -g"],"answer":[1],"explanation":"Заглавная -G выводит все группы; маленькая -g — основную.","difficulty":"applied"},{"type":"single","prompt":"Почему getent passwd user полезнее простого grep по /etc/passwd для сетевых аккаунтов?","options":["getent может обращаться к настроенным сетевым источникам","getent автоматически создаёт пользователя","grep меняет файл","getent всегда показывает пароль"],"answer":[0],"explanation":"NSS может объединять локальные базы и сетевой каталог.","difficulty":"applied"},{"type":"single","prompt":"Какой командой открыть документацию именно формата /etc/passwd?","options":["man 5 passwd","man 1 shadow","passwd --doc","help /etc/passwd"],"answer":[0],"explanation":"Раздел 5 руководства посвящён форматам файлов.","difficulty":"applied"},{"type":"multi","prompt":"Какие 2 команды предназначены для просмотра текущих зарегистрированных пользовательских сеансов?","options":["who","w","lastb","groupadd"],"answer":[0,1],"explanation":"who и w показывают текущие входы; lastb — историю неудачных попыток.","difficulty":"applied"},{"type":"single","prompt":"Администратор хочет видеть, что делает пользователь сейчас, включая колонку WHAT. Что выбрать?","options":["w","who -b","getent group","last -r"],"answer":[0],"explanation":"w дополняет список сеансов текущей командой и показателями активности.","difficulty":"applied"},{"type":"single","prompt":"Как посмотреть сохранённую историю завершённых входов?","options":["last","id","groups","whoami"],"answer":[0],"explanation":"last читает wtmp и выводит исторические сеансы.","difficulty":"applied"},{"type":"single","prompt":"Что показывает who -b?","options":["Число байтов пользователя","Время последней загрузки","Пароли заблокированных аккаунтов","Список Bash-скриптов"],"answer":[1],"explanation":"Опция -b (boot time) показывает время последней загрузки системы, а не историю входов пользователей.","difficulty":"applied"},{"type":"single","prompt":"Какое утверждение про sudo верно?","options":["Любой знающий свой пароль может стать root","Допуск определяется политикой, а действия могут журналироваться","Всегда запускает постоянный root-shell","Во всех Linux пароль кэшируется ровно 5 минут"],"answer":[1],"explanation":"Политика и конфигурация определяют разрешения и повторную аутентификацию.","difficulty":"applied"}],"sources":[{"kind":"chapter","title":"NDG Linux Essentials - Chapter 15 - System and User Security.txt","url":"https://drive.google.com/file/d/1diGXwA3pPUMutAsx6Issbuv7U1TgNlvk/view?usp=drivesdk"},{"kind":"lab","title":"NDG Linux Essentials - Lab 15_ System and User Security.txt","url":"https://drive.google.com/file/d/1hcFNFaRvQnPaJe4m66zwTCtmYQEvyBvd/view?usp=drivesdk"}]},{"id":16,"title":"Создание пользователей и групп","en":"Creating Users and Groups","intro":"Управление аккаунтами требует различать создание записи, назначение пароля, членство в группах и владение файлами. Изменение имени обычно не меняет числового владельца, а смена UID или GID требует отдельного внимания к существующим файлам.","sections":[{"title":"Планирование и группы","body":"Группы удобно создать до пользователей. groupadd team создаёт группу, -g задаёт GID, -r выбирает диапазон системных групп. Допустимые диапазоны определяются настройками дистрибутива; старые границы 500 и 1000 в курсе — примеры. groupmod -n new old меняет имя, -g меняет GID. Переименование сохраняет GID и связь с файлами; смена GID не переписывает автоматически GID всех файлов. groupdel удаляет группу, но обычно откажется удалить основную группу существующего пользователя. Файлы удалённой группы могут остаться с числовым GID."},{"title":"Значения по умолчанию","body":"useradd -D показывает настройки из /etc/default/useradd: GROUP, HOME, INACTIVE, EXPIRE, SHELL, SKEL, CREATE_MAIL_SPOOL. HOME здесь — базовый каталог для новых домашних папок; SKEL — источник начальных файлов. /etc/login.defs содержит диапазоны UID/GID, параметры сроков пароля, CREATE_HOME, UMASK, USERGROUPS_ENAB и другие значения. Пользовательская private group (UPG) обычно имеет то же имя, что и пользователь. Настройки по умолчанию относятся к созданию новых аккаунтов и не обязательно меняют уже существующие."},{"title":"Создание пользователя","body":"Обязательный аргумент useradd — имя. -u задаёт UID, -g основную существующую группу, -G дополнительные группы через запятую, -c комментарий, -s shell. -m создаёт домашний каталог, -M запрещает его создание; -b задаёт базу, -d полный путь, -k альтернативный skeleton вместе с -m. /etc/skel копируется в новый дом, а владельцем копий становится пользователь. Команда обновляет passwd/shadow и сведения о членстве; успешное создание ещё не означает наличие действующего пароля."},{"title":"Пароли и сроки","body":"passwd без аргумента меняет собственный пароль; администратор использует passwd user для начального или нового пароля другого аккаунта. chage -l показывает сроки; -m минимум дней, -M максимум, -W предупреждение, -I период неактивности после истечения, -E дату окончания аккаунта, -d дату последней смены. Ввод пароля в терминале обычно не отображается. Правила сложности и смены определяются политикой системы; числовые примеры курса не являются универсальным требованием."},{"title":"Изменение аккаунта","body":"usermod использует многие опции useradd: -c, -d, -g, -G, -s, -u, -e и -f. -l меняет login name. usermod -aG team user добавляет дополнительную группу; -G без -a заменяет весь список дополнительных групп. Активный сеанс обычно не получает новые группы до повторного входа. -L блокирует пароль, -U снимает эту блокировку; это не гарантирует блокировку всех способов входа, например SSH-ключей. Смена UID может потребовать исправить владельцев файлов вне домашнего каталога."},{"title":"Удаление и проверка","body":"userdel user удаляет учётную запись, сохраняя домашние файлы. userdel -r user дополнительно удаляет домашнюю папку и почтовый spool, но не все файлы пользователя по всему диску. Оставшиеся файлы могут стать сиротами — UID/GID уже не сопоставляется имени. Проверяй результат через getent, id, passwd/group и историю last. Для переносимости выбирают короткие имена с буквами нижнего регистра, цифрами, _ и -, без начальной цифры и завершающего дефиса."}],"commands":[{"cmd":"sudo groupadd research","description":"Создать группу."},{"cmd":"sudo useradd -m -G research -c 'Linux Student' student","description":"Создать пользователя с домом и дополнительной группой."},{"cmd":"sudo passwd student","description":"Задать начальный пароль."},{"cmd":"sudo usermod -aG research student","description":"Добавить группу, сохранив остальные."},{"cmd":"chage -l student","description":"Посмотреть сроки пароля/аккаунта при наличии доступа."}],"lab":[{"task":"В учебной VM создайте группу research и проверьте запись.","answer":"sudo groupadd research\ngetent group research","explanation":"Группа должна существовать до указания её в -G нового пользователя."},{"task":"Создайте student с домашним каталогом и дополнительной группой research, затем задайте пароль.","answer":"sudo useradd -m -G research -c 'Linux Student' student\nsudo passwd student\nid student","explanation":"useradd создаёт аккаунт, passwd отдельно задаёт пароль; фактическая основная группа зависит от настроек UPG."},{"task":"Добавьте существующего sysadmin в research, не теряя его предыдущие группы.","answer":"sudo usermod -aG research sysadmin\ngetent group research","explanation":"-a означает append. Для применения членства в текущей работе обычно нужен новый вход."},{"task":"Сравните действие userdel student и userdel -r student, не выполняя их на нужном аккаунте.","answer":"Первая команда удаляет запись аккаунта. Вторая также удаляет домашний каталог и mail spool.","explanation":"Файлы за пределами этих мест могут сохраниться; удаление не равнозначно смене владельцев."}],"pitfalls":["usermod -G без -a может лишить пользователя прежних дополнительных групп.","useradd без -m не на каждой системе создаёт домашний каталог.","Переименование группы и изменение её GID — разные операции.","Блокировка пароля -L не удаляет файлы и не равна запрету всех способов входа.","userdel -r не ищет и не удаляет автоматически все файлы пользователя по всей системе."],"questions":[{"type":"single","prompt":"Почему обычно удобно создавать группы раньше пользователей?","options":["useradd не умеет создавать пользователей","Группы для -g и -G уже будут существовать","Так всегда назначается UID 0","Чтобы удалить /etc/group"],"answer":[1],"explanation":"Можно сразу задать нужные членства при создании аккаунта.","difficulty":"applied"},{"type":"single","prompt":"Какая команда создаёт группу team с заданным GID 2500?","options":["groupadd -g 2500 team","groupmod -u 2500 team","useradd -G 2500 team","groupadd -n 2500 team"],"answer":[0],"explanation":"-g у groupadd устанавливает числовой идентификатор.","difficulty":"applied"},{"type":"single","prompt":"Что означает groupadd -r service?","options":["Рекурсивное удаление группы","Создание системной группы","Переименование root","Назначение только чтения"],"answer":[1],"explanation":"-r выбирает создание группы из системного диапазона.","difficulty":"applied"},{"type":"single","prompt":"Как переименовать sales в clerks, сохранив GID?","options":["groupmod -n clerks sales","groupmod -g clerks sales","groupadd clerks sales","usermod -l sales clerks"],"answer":[0],"explanation":"-n задаёт новое имя, последний аргумент — существующая группа.","difficulty":"applied"},{"type":"single","prompt":"После смены GID группы файлы со старым GID показывают число. Почему?","options":["Файлы уничтожены","Старый GID больше не сопоставлен имени группы","Файлы стали ссылками","Сменился формат UTF-8"],"answer":[1],"explanation":"В файлах хранится числовой GID; groupmod не переписывает его на всём диске.","difficulty":"applied"},{"type":"single","prompt":"Когда groupdel обычно откажется удалить группу?","options":["Группа основная хотя бы для одного пользователя","В группе больше одного символа","Группа имеет GID выше 1000","Группа пустая"],"answer":[0],"explanation":"Сначала нужно изменить основное членство пользователя.","difficulty":"applied"},{"type":"text","prompt":"Какой каталог обычно служит skeleton для новых домашних каталогов?","answer":["/etc/skel"],"explanation":"Его содержимое копируется при создании домашней папки.","difficulty":"basic"},{"type":"single","prompt":"Что показывает useradd -D без дополнительных изменений?","options":["Список удалённых пользователей","Значения по умолчанию для новых аккаунтов","Все текущие пароли","Дерево процессов"],"answer":[1],"explanation":"-D без изменяющих опций выводит настройки.","difficulty":"applied"},{"type":"single","prompt":"Какая опция useradd явно требует создать домашний каталог?","options":["-M","-m","-r","-G"],"answer":[1],"explanation":"Маленькая -m создаёт дом; большая -M запрещает создание.","difficulty":"applied"},{"type":"single","prompt":"В useradd -m -g users -G research,sales ana какая группа основная?","options":["research","sales","users","Все три основные"],"answer":[2],"explanation":"-g задаёт одну основную, -G список дополнительных.","difficulty":"applied"},{"type":"single","prompt":"Какое назначение у useradd -c 'Aida Student' aida?","options":["Установить пароль","Заполнить комментарий/GECOS","Выбрать каталог кеша","Включить шифрование"],"answer":[1],"explanation":"-c задаёт комментарий, часто полное имя.","difficulty":"applied"},{"type":"single","prompt":"Для нового пользователя нужен shell /bin/bash. Какая опция useradd нужна?","options":["-s /bin/bash","-b /bin/bash","-k /bin/bash","-p /bin/bash"],"answer":[0],"explanation":"-s задаёт путь login shell.","difficulty":"applied"},{"type":"single","prompt":"Как выбрать альтернативный skeleton /etc/skel-dev при создании дома?","options":["useradd -m -k /etc/skel-dev dev","useradd -s /etc/skel-dev dev","useradd -g /etc/skel-dev dev","useradd -D /etc/skel-dev dev"],"answer":[0],"explanation":"-k указывает шаблон каталога и используется вместе с -m.","difficulty":"applied"},{"type":"single","prompt":"Аккаунт создан успешно, но пароль ещё не задан. Что выполнит администратор?","options":["passwd student","passwordadd student","su --new-password","id -p student"],"answer":[0],"explanation":"passwd user задаёт начальный пароль при достаточных правах.","difficulty":"applied"},{"type":"single","prompt":"What does usermod -aG research ana do?","options":["Заменяет все группы на research","Добавляет research к дополнительным группам ana","Меняет основную группу","Создаёт research"],"answer":[1],"explanation":"-a дополняет список -G, не удаляя прежние дополнительные членства.","difficulty":"applied"},{"type":"single","prompt":"Ana была в sales и audit. Администратор выполнил usermod -G research ana. Что изменится?","options":["Добавится research, всё остальное сохранится","Дополнительный список станет только research","Основная группа станет audit","UID станет GID research"],"answer":[1],"explanation":"Без -a опция -G заменяет список дополнительных групп.","difficulty":"challenge"},{"type":"single","prompt":"Почему после добавления в группу открытый терминал ещё не получил новые права группы?","options":["Изменения всегда требуют переустановки","Группы текущего сеанса обычно фиксируются при входе","getent никогда не обновляется","Группы не влияют на права"],"answer":[1],"explanation":"Повторный вход создаёт процессы с обновлёнными группами.","difficulty":"applied"},{"type":"single","prompt":"Как показать сроки действия пароля пользователя?","options":["chage -l user","chmod -l user","passwd -r user","groupmod -l user"],"answer":[0],"explanation":"-l у chage перечисляет параметры aging.","difficulty":"applied"},{"type":"single","prompt":"Как ограничить срок действия пароля 60 днями?","options":["chage -M 60 user","chage -m 60 user","chage -W 60 user","chage -l 60 user"],"answer":[0],"explanation":"Большая -M задаёт максимум; маленькая -m — минимум между сменами.","difficulty":"applied"},{"type":"multi","prompt":"Какие 2 утверждения про userdel -r user верны?","options":["Удаляет домашний каталог пользователя","Удаляет его mail spool","Всегда удаляет любые его файлы во всей системе","Сохраняет запись passwd активной"],"answer":[0,1],"explanation":"Файлы в других местах могут остаться с прежним UID/GID.","difficulty":"applied"},{"type":"single","prompt":"Что изменяет usermod -l new old?","options":["Login name","UID обязательно становится 0","Права всех файлов","Только пароль"],"answer":[0],"explanation":"Переименование аккаунта сохраняет числовую идентичность, если UID отдельно не меняют.","difficulty":"applied"},{"type":"single","prompt":"Какое утверждение точнее описывает usermod -L student?","options":["Удаляет домашний каталог","Блокирует пароль, сохраняя аккаунт и файлы","Меняет все группы","Гарантированно запрещает каждый способ аутентификации"],"answer":[1],"explanation":"Блокировка пароля не равнозначна полному запрету доступа через другие механизмы.","difficulty":"applied"},{"type":"single","prompt":"Что означает CREATE_MAIL_SPOOL=yes в настройках useradd курса?","options":["Создавать место локальной почты нового пользователя","Запускать SMTP-сервер автоматически","Отправлять пароль по почте","Удалять старые письма"],"answer":[0],"explanation":"Spool — место хранения локальных сообщений, не настройка внешнего почтового сервера.","difficulty":"applied"},{"type":"single","prompt":"Какое имя лучше соответствует рекомендациям переносимости из курса?","options":["research_team","9team","team-","Team Name"],"answer":[0],"explanation":"Рекомендуется начинать с нижней буквы или _, избегать пробелов и завершающего дефиса.","difficulty":"applied"}],"sources":[{"kind":"lab","title":"NDG Linux Essentials - Lab 16_ Creating Users and Groups.txt","url":"https://drive.google.com/file/d/1fYHpiWBLb0WTpnHh2cp1Yab1J-m2ab4n/view?usp=drivesdk"},{"kind":"chapter","title":"NDG Linux Essentials - Chapter 16 - Creating Users and Groups.txt","url":"https://drive.google.com/file/d/1vPCtO-WSZczjfzD6HM2dliG26HrMMEp9/view?usp=drivesdk"}]},{"id":17,"title":"Владение и права доступа","en":"Ownership and Permissions","intro":"Разбирай задачи о правах по порядку: кто пользователь, какие у него группы, можно ли пройти по всем каталогам пути, какой класс прав применяется к самому объекту. Это предотвращает большинство ошибок в сценариях экзамена.","sections":[{"title":"Владелец и группа","body":"Файл хранит UID владельца и GID группы. Обычно новым файлом владеет создатель, а группа берётся из текущей основной группы процесса; setgid-каталог — важное исключение следующей главы. id и groups показывают членства. newgrp team запускает новый shell с другой текущей группой; exit возвращает прежний. usermod -g меняет основную группу учётной записи постоянно. chgrp меняет группу файла: обычному владельцу разрешена группа, в которой он состоит; root может выбирать шире. chown user:group меняет владельца и группу; передачу владения другому пользователю выполняет администратор. -R распространяет изменение на дерево."},{"title":"Чтение ls и типы","body":"В ls -l первый символ — тип: - обычный файл, d каталог, l символическая ссылка, b блочное устройство, c символьное устройство, p именованный канал, s сокет. Следующие девять позиций — rwx владельца, группы и остальных. Затем идут число ссылок, владелец, группа, размер, время и имя. ls -ld dir показывает сам каталог, ls -la — также скрытые имена, stat — подробности и числовой режим."},{"title":"Что значат r, w и x","body":"Для обычного файла r даёт чтение содержимого, w — изменение, x — прямое выполнение программы. Для каталога r позволяет перечислять имена, x — проходить через него и обращаться к известным вложенным именам, w вместе с x — создавать, удалять и переименовывать записи. Чтение файла требует x на всех каталогах пути и r на файле; r на каждом каталоге не обязательно. Удаление обычно определяется правами родительского каталога, а не w самого файла; sticky bit и другие механизмы могут накладывать дополнительные ограничения."},{"title":"Как выбирается класс доступа","body":"Для обычной проверки прав без ACL сначала проверяется совпадение UID владельца: тогда действуют только u-права. Иначе при членстве в группе файла действуют g-права; иначе — o-права. Права классов не складываются, и более разрешительные others не спасают владельца с u=---. Каждый каталог пути проверяется отдельно. Если членство пользователя в группе неизвестно, данных для ответа может не хватать. В задачах предполагается обычный пользователь, без привилегий root и дополнительных ACL, если не сказано иначе."},{"title":"Изменение режима","body":"chmod доступен владельцу и администратору. Символическая запись состоит из u/g/o/a, операции +/−/= и r/w/x: g+w добавляет запись группе, o-r убирает чтение у остальных, u=rx заменяет права владельца точно на r-x. Числовая запись использует r=4, w=2, x=1: 7 rwx, 6 rw-, 5 r-x, 4 r--, 3 -wx, 2 -w-, 1 --x, 0 ---. Три цифры идут в порядке владелец–группа–остальные. chmod 640 даёт rw-r-----."},{"title":"Права при создании: umask","body":"umask снимает указанные биты с режима, запрошенного создающей программой; это побитовая маска, не обычное вычитание чисел. Для типичных новых файлов берут 666, для каталогов 777, затем убирают биты маски: 027 даёт файл 640 и каталог 750; 022 — 644 и 755; 077 — 600 и 700. Маска никогда не добавляет x обычному файлу и не меняет уже существующие файлы. Команда umask показывает или задаёт значение текущего shell; дочерние процессы наследуют его. Для постоянной настройки выбирают подходящий файл конфигурации shell, в курсе — ~/.bashrc."}],"commands":[{"cmd":"ls -ld project","description":"Права самого каталога."},{"cmd":"stat note.txt","description":"Владельцы, режим и метаданные."},{"cmd":"chmod u+x,go-w task.sh","description":"Добавить x владельцу, убрать w у группы и остальных."},{"cmd":"chmod 640 note.txt","description":"Владелец читает/пишет, группа читает, остальные без прав."},{"cmd":"chgrp research note.txt","description":"Передать файл группе research при наличии права."},{"cmd":"sudo chown student:research note.txt","description":"Установить владельца и группу."},{"cmd":"umask 027","description":"Для новых типичных файлов 640, каталогов 750."}],"lab":[{"task":"Создайте учебные private/public каталоги и отдельные файлы; сравните права каталога и его содержимого.","answer":"mkdir priv-dir pub-dir\ntouch priv-dir/priv-file pub-dir/pub-file\nls -ld priv-dir pub-dir\nls -l priv-dir pub-dir","explanation":"-d переключает объект просмотра: без него ls показывает вложенные записи."},{"task":"Закройте priv-file для группы и остальных, сохранив права владельца.","answer":"chmod go= priv-dir/priv-file\nls -l priv-dir/priv-file","explanation":"Пустое значение после = устанавливает отсутствие всех прав для выбранных классов."},{"task":"Файл test.sh содержит date. Разрешите владельцу прямой запуск, затем задайте режим 775 и проверьте.","answer":"chmod u+x test.sh\n./test.sh\nchmod 775 test.sh\nstat test.sh","explanation":"775 соответствует rwxrwxr-x; выполнение скрипта также зависит от доступности интерпретатора и каталогов пути."},{"task":"В учебной VM измените владельца каталога и рекурсивно группу другого каталога.","answer":"sudo chown root:root pub-dir\nsudo chgrp -R users priv-dir","explanation":"Первая команда меняет только объект pub-dir; -R во второй охватывает каталог и все его вложенные объекты."}],"pitfalls":["Права u/g/o выбираются по одному классу и не объединяются.","r каталога позволяет видеть имена; x нужен, чтобы пройти по пути к файлу.","Файл без w всё равно может быть удалён из доступного на запись каталога без sticky bit.","umask — снятие битов: при маске 013 обычный файл получает 664, а не результат арифметики 666−013.","Право w на файл само по себе не даёт права менять его режим через chmod."],"questions":[{"type":"single","prompt":"В режиме -rwxr-x--- какие права имеют остальные?","options":["rwx","r-x","---","rw-"],"answer":[2],"explanation":"Последняя тройка относится к others.","difficulty":"basic"},{"type":"text","prompt":"Какое числовое значение у права read?","answer":["4"],"explanation":"r=4, w=2, x=1; значения складываются внутри тройки.","difficulty":"basic"},{"type":"single","prompt":"Какой режим соответствует rw-r-----?","options":["640","604","740","460"],"answer":[0],"explanation":"Владелец 4+2=6, группа 4, остальные 0.","difficulty":"applied"},{"type":"single","prompt":"Как выглядит режим 751?","options":["rwxr-x--x","rwxr-xr--","rw-r-x--x","rwxrw---x"],"answer":[0],"explanation":"7=rwx, 5=r-x, 1=--x.","difficulty":"applied"},{"type":"single","prompt":"Файл имел 644. После chmod g+w file какой режим?","options":["654","664","744","646"],"answer":[1],"explanation":"К группе добавляется w=2: 4 становится 6.","difficulty":"applied"},{"type":"single","prompt":"Файл имел 777. Выполнено chmod u=rx file. Какой режим?","options":["577","757","775","555"],"answer":[0],"explanation":"= заменяет именно права владельца на r-x=5.","difficulty":"applied"},{"type":"single","prompt":"Как посмотреть права каталога project, а не список его файлов?","options":["ls -ld project","ls -l project/*","cat project","ls -a /"],"answer":[0],"explanation":"-d заставляет ls показывать сам аргумент-каталог.","difficulty":"applied"},{"type":"single","prompt":"Какой первый символ ls -l обозначает символьное устройство?","options":["b","c","s","l"],"answer":[1],"explanation":"c — character device; b — block device.","difficulty":"applied"},{"type":"single","prompt":"Что разрешает r на каталоге без x, если путь до каталога доступен?","options":["Читать содержимое всех файлов","Перечислить имена, но не обязательно получить метаданные вложенных файлов","Создать новый файл","Выполнять любой файл внутри"],"answer":[1],"explanation":"Чтение записей каталога и проход по ним — отдельные операции.","difficulty":"applied"},{"type":"single","prompt":"Какое право на каждом каталоге пути необходимо для чтения известного файла внутри?","options":["x","w","Только r","Никакое"],"answer":[0],"explanation":"x — search/traverse: право использовать каталог как компонент пути.","difficulty":"applied"},{"type":"single","prompt":"У ana есть r на /data/report, но нет x на /data. Может ли она прочитать файл по этому пути?","options":["Да, файл важнее каталога","Нет, нельзя пройти по пути","Да, если размер меньше 1 KB","Только при расширении .txt"],"answer":[1],"explanation":"Перед доступом к файлу проверяется проходимость родительских каталогов.","difficulty":"applied"},{"type":"single","prompt":"У пользователя есть x, но нет r на каталоге; известное имя файла внутри доступно на чтение. Может ли он читать его?","options":["Нет, r каталога всегда обязательно","Да, если остальные каталоги пути также доступны","Только root","Только через ls"],"answer":[1],"explanation":"Для известного пути достаточно x каталога и r файла; список имён при этом недоступен.","difficulty":"applied"},{"type":"single","prompt":"Без sticky bit и ACL, при доступном пути, какие права каталога нужны для удаления известной вложенной записи?","options":["r и x","w и x","Только r файла","x файла"],"answer":[1],"explanation":"Удаление изменяет каталог; w даёт изменение записей, x — обращение по имени.","difficulty":"applied"},{"type":"single","prompt":"Ana владеет файлом режима 047 и входит в его группу. Может ли она читать файл как обычный пользователь?","options":["Да по группе","Да по others","Нет: применяется u=---","Да по сумме всех прав"],"answer":[2],"explanation":"Владелец использует только класс u; fallback к группе или others нет.","difficulty":"challenge"},{"type":"single","prompt":"Не-владелец входит в группу файла 604. Может ли он читать файл без дополнительных прав?","options":["Да через others","Нет, выбранная g-тройка ---","Да, все имеют 4","Только после chmod самим собой"],"answer":[1],"explanation":"При совпадении группы выбираются g-права, даже если others разрешают чтение.","difficulty":"challenge"},{"type":"single","prompt":"Кто может выполнить chmod для обычного файла в рамках базовой модели?","options":["Любой с r","Владелец или администратор","Любой из группы файла","Только создатель каталога"],"answer":[1],"explanation":"Право записи в содержимое не равно праву менять режим.","difficulty":"applied"},{"type":"single","prompt":"Обычный владелец хочет chgrp team file. Какое условие нужно?","options":["Он должен быть членом team","Файл обязан быть исполняемым","team обязана иметь GID 0","Все остальные должны иметь w"],"answer":[0],"explanation":"Владелец может выбирать среди своих групп.","difficulty":"applied"},{"type":"single","prompt":"Что делает newgrp research?","options":["Создаёт группу research","Запускает shell с другой текущей основной группой","Переписывает группы всех файлов","Меняет UID на root"],"answer":[1],"explanation":"Новые файлы в обычных каталогах будут использовать текущую группу этого shell.","difficulty":"applied"},{"type":"single","prompt":"Как постоянную основную группу ana изменяет администратор?","options":["usermod -g research ana","newgrp -p ana research","chmod g=research ana","id -g research ana"],"answer":[0],"explanation":"usermod изменяет запись аккаунта; newgrp меняет окружение нового shell.","difficulty":"applied"},{"type":"single","prompt":"Какое действие выполняет chown bob:team file?","options":["Ставит режим 777","Меняет владельца на bob и группу на team","Добавляет bob в team","Создаёт hard link"],"answer":[1],"explanation":"До двоеточия указан пользователь, после — группа.","difficulty":"applied"},{"type":"single","prompt":"Типичный новый обычный файл создаётся с базой 666 и umask 027. Итог?","options":["640","750","639","666"],"answer":[0],"explanation":"Из 666 убираются g-w и все o-биты; остаётся 640.","difficulty":"applied"},{"type":"single","prompt":"Типичный новый каталог создаётся с базой 777 и umask 027. Итог?","options":["640","750","770","027"],"answer":[1],"explanation":"Для каталогов x исходно присутствует, поэтому получается 750.","difficulty":"applied"},{"type":"single","prompt":"База нового файла 666, umask 013. Какой режим?","options":["653","664","654","663"],"answer":[1],"explanation":"Маска g=1 не снимает отсутствующий x; o=3 снимает w и x, оставляя r. Побитово получается 664.","difficulty":"challenge"},{"type":"single","prompt":"Что происходит с существующим файлом 666 после umask 077?","options":["Станет 600","Останется 666","Удалится","Станет 700"],"answer":[1],"explanation":"umask применяется при создании, а не изменяет существующие объекты.","difficulty":"applied"},{"type":"multi","prompt":"Выберите 2 результата umask 022 при обычных базах создания.","options":["Новый файл 644","Новый каталог 755","Новый файл 755","Старые файлы автоматически 644"],"answer":[0,1],"explanation":"Файл начинается с 666, каталог — с 777; маска снимает запись g/o.","difficulty":"applied"},{"type":"single","prompt":"Какой инструмент показывает режим и в символьной, и в числовой форме?","options":["stat","who","route","getent"],"answer":[0],"explanation":"stat выводит расширенные метаданные, включая Access/режим.","difficulty":"applied"},{"type":"single","prompt":"Что означает -R в chgrp -R team project?","options":["Только файлы с чтением","Рекурсивно изменить группу каталога и вложенных объектов","Только корневого пользователя","Отменить предыдущую команду"],"answer":[1],"explanation":"-R обходит всё дерево под project.","difficulty":"applied"},{"type":"single","prompt":"Неизвестно, входит ли bob в team. /data имеет owner sue, group team, режим 750. Достаточно ли этих данных, чтобы решить, войдёт ли bob в /data?","options":["Да, всегда войдёт","Да, всегда получит отказ","Нет, нужно членство bob в team","Нужно только расширение каталога"],"answer":[2],"explanation":"При членстве будут g=r-x, иначе o=---.","difficulty":"challenge"}],"sources":[{"kind":"lab","title":"NDG Linux Essentials - Lab 17_ Ownership and Permissions.txt","url":"https://drive.google.com/file/d/1_ANr_fIYp9wTrnoT_YH3l2FiTTYDngho/view?usp=drivesdk"},{"kind":"chapter","title":"NDG Linux Essentials - Chapter 17 - Ownership and Permissions.txt","url":"https://drive.google.com/file/d/1sh43Y4pT7Fl3VE3bOSamwLbTRTR2dESk/view?usp=drivesdk"}]},{"id":18,"title":"Спецправа и ссылки","en":"Special Directories and Files","intro":"Специальные биты дополняют rwx: setuid/setgid влияют на идентичность выполняемой программы, setgid каталога — на группу новых объектов, sticky bit — на удаление в общем каталоге. Hard link и symlink решают задачу дополнительных имён разными способами.","sections":[{"title":"Setuid","body":"На исполняемом бинарном файле setuid позволяет процессу получить эффективный UID владельца программы. Пример курса — passwd, которому нужно обновлять защищённый /etc/shadow, не предоставляя пользователю общий доступ к нему. В позиции x владельца s означает setuid вместе с x, S — setuid без этого x. chmod u+s добавляет бит, u-s снимает; числовая специальная цифра setuid — 4, например 4755. Бит не обязан означать root: результат зависит от владельца программы. Для shell-скриптов Linux обычно не применяет setuid."},{"title":"Setgid файла и каталога","body":"На бинарном исполняемом файле setgid задаёт эффективную группу владельца файла; пример — wall с группой tty. На каталоге он заставляет новые файлы наследовать группу каталога, а новые подкаталоги — также setgid. Это удобно для совместной работы участников team, даже если у них разные основные группы. Бит не гарантирует группе право записи: остаются важны режим создания и umask. s/S находится в позиции x группы. chmod g+s добавляет, g-s снимает; специальная цифра — 2, например 2770."},{"title":"Sticky bit и временные каталоги","body":"В общем доступном на запись каталоге sticky bit ограничивает удаление/переименование: обычно это разрешено владельцу файла, владельцу каталога или привилегированному процессу. Базовые права каталога всё равно нужны. Он не запрещает чтение или изменение содержимого файла, если обычные права это позволяют. /tmp и /var/tmp обычно имеют 1777. t в позиции x остальных означает sticky и x, T — sticky без o+x. chmod +t добавляет бит, -t снимает; специальная цифра — 1. /var/tmp предназначен для временных данных, сохраняемых между перезагрузками."},{"title":"Inode и жёсткие ссылки","body":"Inode хранит метаданные: UID/GID, режим, время, размер и указатели на данные; имя хранится в записи каталога. ln target alias создаёт ещё одну запись, указывающую на тот же inode. Оба имени равноправны, изменения содержимого и режима относятся к одному объекту. ls -i показывает inode, ls -li — также число жёстких ссылок. Удаление одного имени уменьшает счётчик, остальные имена продолжают работать. Hard links не пересекают границы файловых систем и обычным способом не создаются на каталоги."},{"title":"Символические ссылки","body":"ln -s target alias создаёт отдельный объект со своим inode, хранящий путь к цели. ls -l показывает тип l и стрелку target. Символическая ссылка может вести на каталог, в другую файловую систему или даже на пока несуществующий путь. Она не увеличивает число жёстких ссылок цели. Если целевой путь исчезает, ссылка остаётся, но обращение через неё не находит данные. Относительная цель разрешается относительно каталога самой ссылки. При доступе важны права цели и проходимость пути; обычные rwx самой ссылки в Linux не являются самостоятельным пропуском."},{"title":"Сравнение и выбор","body":"Жёсткая ссылка подходит для дополнительного равноправного имени в одной файловой системе: удаление первоначального имени не разрушает другую ссылку. Символическая ссылка удобна для каталогов и межфайловых переходов, а её назначение видно в ls -l. Копия создаёт независимые данные; ссылка предоставляет другое имя/путь к существующему объекту. Одинаковый номер inode имеет смысл сравнивать в пределах одной файловой системы."}],"commands":[{"cmd":"ls -ld /tmp /var/tmp","description":"Найти sticky bit в правах временных каталогов."},{"cmd":"ls -l /usr/bin/passwd /usr/bin/wall","description":"Примеры setuid и setgid из лаборатории."},{"cmd":"chmod g+s project","description":"Наследовать группу каталога новыми объектами."},{"cmd":"chmod +t shared","description":"Ограничить удаление в общем каталоге."},{"cmd":"ln source hardlink","description":"Создать второе имя того же inode."},{"cmd":"ln -s source softlink","description":"Создать ссылку, хранящую путь source."},{"cmd":"ls -li source hardlink softlink","description":"Сравнить inode, тип и число ссылок."}],"lab":[{"task":"Найдите, где отображаются sticky, setuid и setgid на учебной системе.","answer":"ls -ld /tmp /var/tmp\nls -l /usr/bin/passwd /usr/bin/wall","explanation":"t относится к позиции others, s у passwd — к user, s у wall в примере курса — к group; настройки конкретной системы могут отличаться."},{"task":"В отдельной учебной папке создайте source и две жёсткие ссылки. Сравните inode.","answer":"echo data > source\nln source hardlink\nln hardlink second\nls -li source hardlink second","explanation":"Обычно три имени имеют один inode и link count 3; никакое имя не является более главным."},{"task":"Удалите только учебную ссылку second. Что изменится?","answer":"rm second\nls -li source hardlink","explanation":"Счётчик станет 2; содержимое остаётся доступно по двум именам."},{"task":"Создайте символическую ссылку на source и на каталог /proc.","answer":"ln -s source softlink\nln -s /proc proc-link\nls -li source softlink proc-link","explanation":"Symlink имеет отдельный inode и может ссылаться на каталог другой файловой системы."}],"pitfalls":["Setuid делает программу эффективным владельцем файла, а не обязательно root.","Setgid каталога наследует группу, но не выдаёт автоматически g+w новым файлам.","Sticky bit ограничивает удаление/переименование, а не чтение или запись в содержимое.","Hard link не является независимой резервной копией.","Символическая ссылка не защищает от исчезновения целевого пути."],"questions":[{"type":"single","prompt":"Что меняет setuid на исполняемом бинарном файле в базовом сценарии?","options":["Эффективный UID процесса на UID владельца программы","Имя пользователя в passwd","Основную группу всех пользователей","UID всех файлов каталога"],"answer":[0],"explanation":"Идентичность меняется для выполняемого процесса, не для всей учётной записи.","difficulty":"applied"},{"type":"single","prompt":"Почему обычный пользователь может обновить свой пароль через setuid-программу passwd?","options":["shadow открыт всем на запись","Программа выполняет контролируемое изменение с полномочиями владельца root","Пароли хранятся только в RAM","sudo запускается автоматически внутри shell"],"answer":[1],"explanation":"Привилегированная программа проверяет допустимость изменения, не открывая shadow для произвольной записи.","difficulty":"applied"},{"type":"single","prompt":"Файл имеет владельца service и setuid. Обязательно ли он выполняется с эффективным UID 0?","options":["Да, setuid всегда root","Нет, эффективный UID соответствует service","Только если имя файла passwd","Нет, setuid означает группу"],"answer":[1],"explanation":"Специальный бит ориентируется на владельца файла.","difficulty":"applied"},{"type":"single","prompt":"Что означает маленькая s в позиции user execute?","options":["Setuid и user x включены","Только setuid, user x выключен","Только sticky","Файл обязательно socket"],"answer":[0],"explanation":"Строчная s объединяет специальный бит и обычный execute.","difficulty":"applied"},{"type":"single","prompt":"Что означает большая S в позиции group execute?","options":["Setgid установлен, g+x отсутствует","Sticky установлен","Группа имеет все права","Файл сжат"],"answer":[0],"explanation":"Размер буквы показывает наличие обычного execute в этой позиции.","difficulty":"applied"},{"type":"text","prompt":"Какая специальная восьмеричная цифра соответствует setuid?","answer":["4"],"explanation":"Специальная цифра 4 в старшем разряде даёт бит 4000.","difficulty":"basic"},{"type":"single","prompt":"Как добавить setgid каталогу, сохранив его обычные права?","options":["chmod g+s project","chmod u+s project","chmod o+t project","chown +g project"],"answer":[0],"explanation":"g+s добавляет setgid без замены остальных rwx.","difficulty":"applied"},{"type":"single","prompt":"Для чего в примере курса wall имеет setgid tty?","options":["Чтобы записывать сообщения в терминалы с группой tty","Чтобы менять пароль root","Чтобы выполнять все команды пользователя как root","Чтобы удалять /tmp"],"answer":[0],"explanation":"Эффективная группа процесса получает доступ к устройствам терминалов.","difficulty":"applied"},{"type":"single","prompt":"Каталог project имеет группу team и setgid. Файл создаёт ana с основной группой sales. Какая группа будет у нового файла?","options":["sales","team","root","Никакая"],"answer":[1],"explanation":"Setgid каталога заставляет наследовать его группу.","difficulty":"applied"},{"type":"single","prompt":"Что обычно наследует новый подкаталог внутри setgid-каталога?","options":["Только имя владельца root","Группу родителя и setgid","Все пароли участников","Только sticky bit"],"answer":[1],"explanation":"Наследование сохраняет групповую организацию дерева.","difficulty":"applied"},{"type":"single","prompt":"Файл в setgid-каталоге получил группу team и режим 640. Может ли другой член team редактировать его?","options":["Да, setgid всегда даёт w","Нет, группе дано только r","Да, каталог отменяет режим файла","Только при имени .txt"],"answer":[1],"explanation":"Наследование группы не добавляет отсутствующее право записи.","difficulty":"applied"},{"type":"single","prompt":"Какое значение имеет ведущая 1 в режиме каталога 1777?","options":["Setuid","Setgid","Sticky bit","Только чтение"],"answer":[2],"explanation":"Специальные значения: 4 setuid, 2 setgid, 1 sticky.","difficulty":"basic"},{"type":"single","prompt":"Какую проблему в общем каталоге решает sticky bit?","options":["Запрет чтения чужих файлов","Ограничение удаления чужих записей","Автоматическое шифрование","Ускорение записи"],"answer":[1],"explanation":"Он ограничивает удаление и переименование при общих правах записи.","difficulty":"applied"},{"type":"multi","prompt":"В каталоге sticky, при достаточных базовых правах, какие 2 обычных пользователя могут удалить файл?","options":["Владелец файла","Владелец каталога","Любой член группы файла","Любой, кто умеет читать файл"],"answer":[0,1],"explanation":"Помимо привилегированного процесса удаление допускается владельцу файла либо самого каталога.","difficulty":"applied"},{"type":"single","prompt":"У каталога режим 1777, файл ana имеет 666. Bob не владелец каталога. Что позволяет sticky bit?","options":["Bob не может удалить файл ana, но может менять его содержимое по w","Bob не может ни читать, ни писать","Bob становится владельцем","Файл автоматически становится 600"],"answer":[0],"explanation":"Sticky регулирует запись каталога, а разрешение w файла сохраняется.","difficulty":"challenge"},{"type":"single","prompt":"Что означает t в последней позиции прав каталога?","options":["Sticky и execute для others","Только execute владельца","Setuid без execute","Сокет"],"answer":[0],"explanation":"t занимает позицию o+x; T обозначает отсутствие o+x.","difficulty":"applied"},{"type":"single","prompt":"Какой каталог предназначен для временных файлов, сохраняемых между перезагрузками?","options":["/var/tmp","/bin","/proc/1","/etc/skel"],"answer":[0],"explanation":"FHS отличает /var/tmp от краткоживущего /tmp.","difficulty":"applied"},{"type":"single","prompt":"Что хранится в записи каталога, связывающей имя файла с объектом?","options":["Имя и номер inode","Открытый пароль владельца","Полная копия всех данных файла","Только путь к shell"],"answer":[0],"explanation":"Имена находятся в записях каталога; inode хранит метаданные объекта.","difficulty":"applied"},{"type":"single","prompt":"Как создать жёсткую ссылку alias на source?","options":["ln source alias","ln -s source alias","cp -r alias source","link -d source alias"],"answer":[0],"explanation":"ln без -s создаёт hard link.","difficulty":"basic"},{"type":"single","prompt":"source и alias — hard links одного обычного файла. Что у них общее?","options":["Только расширение имени","Один inode и содержимое","Всегда разные права","Только дата создания ссылки"],"answer":[1],"explanation":"Оба имени указывают на один объект файловой системы.","difficulty":"applied"},{"type":"single","prompt":"У файла link count 1. Добавлены две hard links и одна symlink. Какой link count цели?","options":["2","3","4","1"],"answer":[1],"explanation":"Каждая hard link увеличивает счётчик; symlink его не меняет.","difficulty":"applied"},{"type":"single","prompt":"Удалили исходное имя файла, но одна hard link осталась. Что с данными?","options":["Остаются доступны через оставшееся имя","Немедленно исчезают","Становятся каталогом","Доступны только root"],"answer":[0],"explanation":"Все жёсткие имена равноправны; удаление одного не удаляет остальные.","difficulty":"applied"},{"type":"multi","prompt":"Какие 2 возможности есть у symlink, но нет у обычной hard link?","options":["Ссылка на каталог","Переход на другую файловую систему","Обязательное совпадение inode с целью","Увеличение hard link count цели"],"answer":[0,1],"explanation":"Символическая ссылка хранит путь, поэтому не ограничена inode одной файловой системы.","difficulty":"applied"},{"type":"single","prompt":"Как создать символическую ссылку docs на /usr/share/doc?","options":["ln -s /usr/share/doc docs","ln /usr/share/doc docs","cp /usr/share/doc docs","chmod -s docs"],"answer":[0],"explanation":"-s выбирает символическую ссылку.","difficulty":"applied"},{"type":"single","prompt":"Цель symlink удалена, ссылка не удалялась. Что остаётся?","options":["Ссылка с неразрешимым целевым путём","Полная независимая копия","Автоматически новая hard link","Ничего, symlink удаляется сама"],"answer":[0],"explanation":"Такая ссылка называется dangling/broken; объект ссылки всё ещё существует.","difficulty":"applied"},{"type":"single","prompt":"Как увидеть inode при выводе списка файлов?","options":["ls -i","ls -h","ls -t","ls -R"],"answer":[0],"explanation":"-i добавляет номер inode; -li также показывает подробности.","difficulty":"applied"},{"type":"single","prompt":"Почему hard links нельзя делать через границу файловых систем?","options":["У каждой файловой системы собственное пространство inode","Потому что shell запрещает символ /","Потому что root никогда не может создавать ссылки","Из-за регистра имени"],"answer":[0],"explanation":"Один inode принадлежит конкретной файловой системе.","difficulty":"applied"},{"type":"single","prompt":"В каталоге /home/ana лежит symlink shortcut с целью docs/readme. Откуда отсчитывается этот относительный путь?","options":["От текущего каталога вызывающего процесса","От /home/ana, каталога самой ссылки","Всегда от /","От /proc"],"answer":[1],"explanation":"Относительный текст цели разрешается относительно места расположения symlink.","difficulty":"challenge"}],"sources":[{"kind":"lab","title":"NDG Linux Essentials - Lab 18_ Special Directories and Files.txt","url":"https://drive.google.com/file/d/1InGHVU44W4tG0PIgryfBwUs5Cp_Lpgok/view?usp=drivesdk"},{"kind":"chapter","title":"NDG Linux Essentials - Chapter 18 - Special Directories and Files.txt","url":"https://drive.google.com/file/d/13OenzPh5Htugd9wcyjvYVy82oaHmkmYH/view?usp=drivesdk"}]}];